(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,92604,14923,75513,e=>{"use strict";var t=e.i(66429);let n={id:"run-squash",region:"R0",title:"Run Squash",difficulty:"E",patterns:["syntax"],signals:["write this function","delete elements from a vector","erase inside a loop costs O(n) each time"],prerequisites:[],parSeconds:360,complexity:{time:"O(n)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.2,perf:.4},similar:[{name:"Remove Duplicates from Sorted Array",lcNumber:26}],spec:{kind:"function",name:"squashRuns",returns:"vector<int>",params:[{type:"vector<int>",name:"nums"}]}};e.s(["f",0,n],14923);let a={id:"step-counter",region:"R0",title:"Step Counter",difficulty:"E",patterns:["syntax"],signals:["design a class","constructor with a member initialiser list","this-> to avoid shadowing","clamp to a range"],prerequisites:[],parSeconds:540,complexity:{time:"O(1)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.2,perf:.4},similar:[{name:"Design Parking System",lcNumber:1603}],spec:{kind:"design",className:"StepCounter",ctor:[{type:"int",name:"limit"},{type:"int",name:"start"}],methods:[{name:"add",returns:"int",params:[{type:"int",name:"amount"}]},{name:"total",returns:"int",params:[]},{name:"reset",returns:"void",params:[]}]}};e.s(["f",0,a],75513);var s=e.i(27288),i=e.i(5665),o=e.i(78155),r=e.i(1153);let l={id:"drum-bag",region:"R4",title:"Drum Bag",difficulty:"M",patterns:["hash-design"],signals:["O(1) insert, erase and index access","array plus hash map of positions","swap with the last to delete"],prerequisites:["twin-scripts"],parSeconds:900,complexity:{time:"O(1)",space:"O(n)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.2,perf:.4},similar:[{name:"Insert Delete GetRandom O(1)",lcNumber:380}],spec:{kind:"design",className:"DrumBag",ctor:[],methods:[{name:"insert",returns:"bool",params:[{type:"int",name:"val"}]},{name:"erase",returns:"bool",params:[{type:"int",name:"val"}]},{name:"slot",returns:"int",params:[{type:"int",name:"i"}]},{name:"size",returns:"int",params:[]}]}};var h=e.i(3234);let c={id:"locker-board",region:"R4",title:"Locker Board",difficulty:"M",patterns:["hash-design"],signals:["build a hash map without the library map","buckets plus collision chains","put, get and remove by key"],prerequisites:["twin-scripts"],parSeconds:1080,complexity:{time:"O(1)",space:"O(n)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.2,perf:.4},similar:[{name:"Design HashMap",lcNumber:706}],spec:{kind:"design",className:"LockerBoard",ctor:[],methods:[{name:"put",returns:"void",params:[{type:"int",name:"key"},{type:"int",name:"val"}]},{name:"get",returns:"int",params:[{type:"int",name:"key"}]},{name:"remove",returns:"void",params:[{type:"int",name:"key"}]},{name:"count",returns:"int",params:[]}]}};var d=e.i(8994),u=e.i(721);let m={id:"gauge-stack",region:"R6",title:"Gauge Stack",difficulty:"M",patterns:["stack","design-ds"],signals:["stack with an extra O(1) query","the answer must survive pops","store a summary next to each element"],prerequisites:["crate-brackets"],parSeconds:600,complexity:{time:"O(1)",space:"O(n)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.2,perf:.4},similar:[{name:"Min Stack",lcNumber:155}],spec:{kind:"design",className:"GaugeStack",ctor:[],methods:[{name:"push",returns:"void",params:[{type:"int",name:"val"}]},{name:"pop",returns:"void",params:[]},{name:"top",returns:"int",params:[]},{name:"low",returns:"int",params:[]}]}},p={id:"ring-lane",region:"R6",title:"Ring Lane",difficulty:"M",patterns:["queue","design-ds"],signals:["fixed capacity queue","reuse freed slots instead of shifting","indices that wrap around with modulo"],prerequisites:["twin-stack-line"],parSeconds:780,complexity:{time:"O(1)",space:"O(k)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.25,adversarial:.25,perf:.3},similar:[{name:"Design Circular Queue",lcNumber:622}],spec:{kind:"design",className:"RingLane",ctor:[{type:"int",name:"capacity"}],methods:[{name:"offer",returns:"bool",params:[{type:"int",name:"val"}]},{name:"poll",returns:"bool",params:[]},{name:"front",returns:"int",params:[]},{name:"back",returns:"int",params:[]},{name:"empty",returns:"bool",params:[]},{name:"full",returns:"bool",params:[]}]}},g={id:"twin-stack-line",region:"R6",title:"Twin Stack Line",difficulty:"E",patterns:["stack","queue"],signals:["build a queue from stacks","reversing twice restores order","amortised O(1)"],prerequisites:["crate-brackets"],parSeconds:480,complexity:{time:"O(1)",space:"O(n)"},timeLimitMs:1e3,testWeights:{basic:.25,edge:.2,adversarial:.2,perf:.35},similar:[{name:"Implement Queue using Stacks",lcNumber:232}],spec:{kind:"design",className:"TwinStackLine",ctor:[],methods:[{name:"enqueue",returns:"void",params:[{type:"int",name:"val"}]},{name:"dequeue",returns:"int",params:[]},{name:"front",returns:"int",params:[]},{name:"empty",returns:"bool",params:[]}]}},f={"cargo-total":{meta:{id:"cargo-total",region:"R0",title:"Cargo Total",difficulty:"E",patterns:["syntax"],signals:["write this function","sum of many large values","total may exceed 32 bits"],prerequisites:[],parSeconds:240,complexity:{time:"O(n)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.3,adversarial:.2,perf:.3},similar:[{name:"Running Sum of 1d Array",lcNumber:1480}],spec:{kind:"function",name:"totalWeight",returns:"long long",params:[{type:"vector<int>",name:"w"}]}},statement:"# Cargo Total\n\nA freighter loads crates one after another. Crate `i` weighs `w[i]` grams. Return the total weight of all crates in grams.\n\nThe manifest can hold many heavy crates, so the total may be much larger than a single crate.\n\n## Examples\n\n- `w = [3, 5, 2]` gives `10`.\n- `w = [2000000000, 2000000000]` gives `4000000000`.\n- `w = []` gives `0`.\n\n## Constraints\n\n- `0 <= w.size() <= 100000`\n- `0 <= w[i] <= 2000000000`\n",editorial:'## Signals\nA statement that adds many values with large entries and a "total" in the question is a flag to check the accumulator\'s range before writing any code. Two numbers decide it: the largest item and the item count.\n\n## Brute force\nThere is no slower approach to compare with: every solution must look at each crate once. The reference check here uses a 128-bit accumulator so it cannot overflow, which proves the 64-bit answer is exact.\n\n## Key insight\nThe answer is at most 10^5 * 2 * 10^9 = 2 * 10^14. That fits in a 64-bit integer (about 9.2 * 10^18) but not in 32 bits (about 2.1 * 10^9), so the type of the running total is the whole problem.\n\n## Optimal\nOne pass with a `long long total` that starts at 0. Time O(n), space O(1).\n\n## C++ walkthrough\n`for (const int x : w)` reads each element without writing to the vector. `total += x` promotes `x` to `long long` before adding. `std::accumulate(w.begin(), w.end(), 0LL)` is the one-liner; with plain `0` the sum is computed in `int` and the overflow is silent (signed overflow is undefined behaviour). Taking `vector<int> w` by value copies it; interview solutions normally take `const vector<int>&`, and the harness accepts either.\n\n## Common bugs\nDeclaring `int total`; calling `accumulate` with `0` instead of `0LL`; widening only at the `return`, which is too late; reading only up to `size() - 1`.\n\n## Follow-ups\nReturn the average as a `double` without losing precision. Return the total modulo 10^9 + 7. Find the largest prefix whose sum stays below a limit.\n\n## Similar problems\nRunning Sum of 1d Array (LeetCode 1480).\n',reference:"class Solution {\npublic:\n    long long totalWeight(vector<int> w) {\n        long long total = 0;  // 10^5 crates of 2 * 10^9 g do not fit in int\n        for (const int x : w) total += x;\n        return total;\n    }\n};\n",hints:"## Nudge\nWhat is the biggest value an `int` can hold, and how big can this total get?\n\n## Approach\nAdd every crate into one running total. Decide the type of that total before you write the loop.\n\n## Key insight\n100000 crates of up to 2 * 10^9 sum to 2 * 10^14, far beyond `int`. Make the accumulator `long long`. If you use `std::accumulate`, the start value must be `0LL`, because the start value's type decides the type of the sum.\n",prompt:{question:"Why does `accumulate(w.begin(), w.end(), 0)` give a wrong total here even though `total` is returned as a long long?",options:["The initial value 0 is an int, so every addition is done in int and overflows silently","accumulate only reads the first half of the vector","Returning a long long from a function truncates it to int","The vector must be sorted before it is summed"],answer:0,why:"accumulate uses the type of its initial value as the accumulator type. 0LL makes every partial sum a long long; the return type cannot repair an overflow that already happened."},loadTests:async()=>(await e.A(98363)).default},"charge-meter":{meta:{id:"charge-meter",region:"R0",title:"Charge Meter",difficulty:"E",patterns:["syntax"],signals:["write this function","stop at the first time a total reaches a target","skip bad readings"],prerequisites:["cargo-total"],parSeconds:300,complexity:{time:"O(n)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.3,adversarial:.25,perf:.25},similar:[{name:"Minimum Value to Get Positive Step by Step Sum",lcNumber:1413}],spec:{kind:"function",name:"triggerIndex",returns:"int",params:[{type:"vector<int>",name:"readings"},{type:"long long",name:"limit"}]}},statement:"# Charge Meter\n\nA battery charges from a stream of readings, one per tick. A **negative** reading is sensor noise and is ignored. Every other reading is added to the stored charge, which starts at `0`.\n\nReturn the index of the first tick after which the stored charge is **at least** `limit`. If the charge never reaches `limit`, return `-1`.\n\n## Examples\n\n- `readings = [4, -3, 5, 2], limit = 9` gives `2`. The `-3` is skipped, the charge is 4 then 9.\n- `readings = [1, 1], limit = 5` gives `-1`.\n- `readings = [7], limit = 7` gives `0`.\n\n## Constraints\n\n- `0 <= readings.size() <= 100000`\n- `-1000000000 <= readings[i] <= 1000000000`\n- `1 <= limit <= 100000000000000`\n",editorial:'## Signals\n"Stop at the first time a running total reaches a target", plus "ignore some items". The first calls for an early exit; the second calls for skipping an iteration. Together they are the textbook use of `break` / `return` and `continue`.\n\n## Brute force\nCompute the charge after every tick into an array, then scan that array for the first value that reaches the limit. It does the same work in two passes and is easy to trust.\n\n## Key insight\nNothing after the first qualifying tick matters, so the loop can end there. Because negatives are skipped, the charge never decreases, so the first tick that reaches the limit is also the first tick at which it can be checked.\n\n## Optimal\nA single pass with an early exit. Time O(n) in the worst case (never reaching the limit), space O(1).\n\n## C++ walkthrough\n`continue` jumps to the next iteration without running the rest of the body. `return i` leaves the whole function, which here is the cleanest way to break out. The running total is `long long` because 10^5 readings of 10^9 reach 10^14. `limit` is also `long long`, so the comparison happens in 64 bits; comparing an `int` charge with it would still overflow before the comparison.\n\n## Common bugs\nAdding negative readings; `>` instead of `>=`; an `int` charge; returning `i + 1`; forgetting the `-1` for the case where the loop finishes.\n\n## Follow-ups\nCount how many readings were ignored before the trigger. Return the first index where the charge, including negatives, reaches the limit (a prefix-sum search). Handle a stream where readings arrive one at a time.\n\n## Similar problems\nMinimum Value to Get Positive Step by Step Sum (LeetCode 1413).\n',reference:"class Solution {\npublic:\n    int triggerIndex(vector<int> readings, long long limit) {\n        long long charge = 0;  // up to 10^5 * 10^9 = 10^14, so it must be 64-bit\n        for (int i = 0; i < static_cast<int>(readings.size()); ++i) {\n            if (readings[i] < 0) continue;  // noise: ignore and move on\n            charge += readings[i];\n            if (charge >= limit) return i;  // first tick that reaches the limit: stop looking\n        }\n        return -1;\n    }\n};\n",hints:'## Nudge\nYou must stop as soon as the charge reaches the limit. Which loop statements let you skip an item, and which let you leave the loop?\n## Approach\nWalk the readings by index. If a reading is negative, skip it. Otherwise add it to a running charge and check whether the charge has reached the limit.\n## Key insight\nUse `continue` for the noise case and `return i` the moment `charge >= limit`. The charge can reach 10^14, so it must be a `long long`, and "at least" means `>=`. Return the index, not the count of ticks.\n',loadTests:async()=>(await e.A(64883)).default},"drop-negatives":{meta:{id:"drop-negatives",region:"R0",title:"Drop Negatives",difficulty:"E",patterns:["syntax"],signals:["write this function","ListNode","the head itself may be removed","nullptr marks the end"],prerequisites:[],parSeconds:420,complexity:{time:"O(n)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.2,perf:.4},similar:[{name:"Remove Linked List Elements",lcNumber:203}],spec:{kind:"function",name:"dropNegatives",returns:"ListNode*",params:[{type:"ListNode*",name:"head"}]}},statement:"# Drop Negatives\n\nA singly linked list of readings is given by its head. Remove every node whose value is negative and return the head of the remaining list, keeping the order of the survivors. The list may become empty, in which case return `nullptr`.\n\nThe list node is the usual one:\n\n```cpp\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int x) : val(x), next(nullptr) {}\n};\n```\n\n## Examples\n\n- `head = [3,-1,4]` gives `[3,4]`.\n- `head = [-5,-2,7]` gives `[7]` (the head itself is removed).\n- `head = [-1,-2]` gives `[]`.\n- `head = []` gives `[]`.\n\n## Constraints\n\n- `0 <=` number of nodes `<= 100000`\n- `-1000 <= val <= 1000`\n",editorial:"## Signals\nA linked list where the head may be deleted. The dummy-head idiom removes the special case.\n\n## Brute force\nCopy the values into a vector, filter it, and rebuild a new list. O(n) time and memory; correct but allocates every node again.\n\n## Key insight\nKeep a tail pointer to the end of the kept list, starting at a dummy node that sits before the real head. Every kept node is appended to the tail; skipped nodes are simply never linked. No special case for the head.\n\n## Optimal\nOne pass, O(n) time, O(1) extra space (the dummy lives on the stack). By interview convention we do not `delete` removed nodes unless asked; mention it aloud.\n\n## C++ walkthrough\n`ListNode dummy(0); ListNode* tail = &dummy;` makes a node on the stack. In the loop `ListNode* cur = head; while (cur != nullptr)` we read `cur->next` before relinking, because `tail->next = cur` can change what `cur->next` means later. After the loop `tail->next = nullptr` closes the list. Return `dummy.next`, which is `nullptr` when nothing survived.\n\n## Common bugs\nHandling only nodes after the head, so a negative head survives. Forgetting `tail->next = nullptr`, which leaves a dropped node hanging off the end. Dropping zeros as well (`<= 0`). Returning `head` instead of `dummy.next`. Dereferencing `head->next` when `head` is `nullptr`.\n\n## Follow-ups\nRemove duplicates from a sorted list. Remove every node equal to a given value. Do it recursively and compare the stack cost.\n\n## Similar problems\nRemove Linked List Elements (LeetCode 203).\n",reference:'class Solution {\npublic:\n    ListNode* dropNegatives(ListNode* head) {\n        ListNode dummy(0);              // sits before the real head, so "the last kept node" always exists\n        ListNode* tail = &dummy;\n        for (ListNode* cur = head; cur != nullptr; cur = cur->next) {\n            if (cur->val >= 0) {\n                tail->next = cur;\n                tail = cur;\n            }\n        }\n        tail->next = nullptr;           // close the kept chain\n        return dummy.next;\n    }\n};\n',hints:'## Nudge\nWhat if the very first node has to go? Then the answer\'s head is a different node from the input\'s head.\n## Approach\nWalk with a pointer to the last kept node. Create a throwaway `ListNode dummy(0)` placed before the real head, so that "the last kept node" always exists, even before you keep anything. For each node, if it is not negative, link it after the last kept node. Finish by setting the last kept node\'s `next` to `nullptr` and returning `dummy.next`.\n## Key insight\nA dummy head turns "remove the head" into the same case as "remove any other node". Always terminate the kept chain with `nullptr`; otherwise the last kept node may still point at a node you meant to drop.\n',loadTests:async()=>(await e.A(14185)).default},"echo-chamber":{meta:{id:"echo-chamber",region:"R0",title:"Echo Chamber",difficulty:"E",patterns:["syntax"],signals:["write this function","exponent up to 10^18","answer modulo a prime","recursion that halves the input"],prerequisites:["cargo-total"],parSeconds:420,complexity:{time:"O(log e)",space:"O(log e)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.25,adversarial:.25,perf:.3},similar:[{name:"Pow(x, n)",lcNumber:50}],spec:{kind:"function",name:"echoStrength",returns:"int",params:[{type:"long long",name:"base"},{type:"long long",name:"bounces"}]}},statement:"# Echo Chamber\n\nA pulse of strength `1` enters a chamber. Every time it bounces off a wall, its strength is multiplied by `base`. After `bounces` bounces, report the strength **modulo 1000000007**.\n\nWith no bounces the strength is still `1`, whatever the base is.\n\n## Examples\n\n- `base = 2, bounces = 10` gives `1024`.\n- `base = 3, bounces = 0` gives `1`.\n- `base = 2, bounces = 100` gives `976371285` (2^100 modulo 1000000007).\n\n## Constraints\n\n- `0 <= base <= 1000000000`\n- `0 <= bounces <= 1000000000000000000`\n",editorial:'## Signals\n"Modulo a prime" and an exponent far too big to loop over. Whenever a repeated operation count is up to 10^18, you need to cut the count in half each step, not walk it.\n\n## Brute force\nMultiply one bounce at a time, reducing modulo 1000000007 after each step. It is O(bounces), which is fine for the 40-bounce checks and impossible at 10^18.\n\n## Key insight\n`base^e = (base^(e/2))^2` when `e` is even and `(base^(e/2))^2 * base` when it is odd (integer division). The exponent halves each call, so the recursion depth is at most 60 for `e <= 10^18`. A recursion that peels one bounce at a time has depth `e` and overflows the call stack almost immediately.\n\n## Optimal\nRecursive exponentiation by squaring. Time O(log e), space O(log e) for the call stack.\n\n## C++ walkthrough\nThe base case is the empty product, `1`. `half * half` is at most (10^9+6)^2, about 10^18, which fits in a `long long` (limit about 9.2 * 10^18) but not in an `int`. The `% MOD` after each multiplication keeps every value small. `base % MOD` before the first call handles a base equal to `MOD - 1` or larger values uniformly. Each recursive call gets its own stack frame holding `half` and `result`; the frames pile up until the base case and unwind in reverse. `static constexpr long long MOD` is a compile-time constant that belongs to the class rather than to any object.\n\n## Common bugs\nForgetting the odd case; multiplying in `int`; recursing on `e - 1` (stack overflow); returning `0` for a zero base with zero bounces; forgetting the final `% MOD`.\n\n## Follow-ups\nWrite it iteratively with a loop over the bits of `e`. Compute a modular inverse with Fermat\'s little theorem. Raise a 2x2 matrix to a power to get Fibonacci numbers.\n\n## Similar problems\nPow(x, n) (LeetCode 50).\n',reference:"class Solution {\n    static constexpr long long MOD = 1000000007LL;\n\n    // Invariant: returns base^e mod MOD, using about log2(e) nested calls (at most 60 here).\n    static long long power(long long base, long long e) {\n        if (e == 0) return 1;  // base case: the empty product\n        const long long half = power(base, e / 2);\n        long long result = half * half % MOD;  // both factors are < MOD, so the product fits in 64 bits\n        if (e % 2 == 1) result = result * base % MOD;\n        return result;\n    }\n\npublic:\n    int echoStrength(long long base, long long bounces) {\n        return static_cast<int>(power(base % MOD, bounces));\n    }\n};\n",hints:"## Nudge\nDoing one multiplication per bounce would take 10^18 steps. How could one step handle many bounces at once?\n## Approach\nBouncing `e` times is the same as bouncing `e / 2` times, squaring that strength, and bouncing once more if `e` is odd. That is a recursion that halves the problem.\n## Key insight\nWrite `power(base, e)` with the base case `e == 0` returning `1`. Take `half = power(base, e / 2)`, return `half * half % MOD`, and multiply by `base` once more when `e` is odd. The depth is about 60, so the stack is safe, and every product of two values below 1000000007 fits in a `long long`. Use `long long` for the multiplication, never `int`.\n",loadTests:async()=>(await e.A(45974)).default},"field-split":{meta:{id:"field-split",region:"R0",title:"Field Split",difficulty:"E",patterns:["syntax"],signals:["write this function","split a string on a delimiter","substr(pos, len) takes a length, not an end"],prerequisites:[],parSeconds:360,complexity:{time:"O(n)",space:"O(n)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.2,perf:.4},similar:[{name:"Split a String in Balanced Strings",lcNumber:1221}],spec:{kind:"function",name:"splitFields",returns:"vector<string>",params:[{type:"string",name:"line"}]}},statement:'# Field Split\n\nA logbook line stores fields separated by commas, for example `crab,,seal`. Split the line into its fields, in order. Empty fields are real fields and must be kept: `crab,,seal` has three fields, the middle one empty. A line with no commas has exactly one field, and the empty line has one empty field.\n\n## Examples\n\n- `line = "crab,reef,seal"` gives `["crab", "reef", "seal"]`.\n- `line = "a,,b"` gives `["a", "", "b"]`.\n- `line = "x,"` gives `["x", ""]`.\n- `line = ""` gives `[""]`.\n\n## Constraints\n\n- `0 <= line.size() <= 200000`\n- `line` contains lowercase letters, digits, spaces and commas only\n- fields are not trimmed: spaces belong to the field\n',editorial:'## Signals\n"Split on a delimiter" with a rule about empty pieces. Decide first what an empty piece means; library helpers often decide differently from the statement.\n\n## Brute force\nScan the characters once: a comma starts a new empty field, any other character is appended to the last field. This is O(n) and trivially handles empty fields because the vector starts with one empty field.\n\n## Key insight\nThe problem is a test of edge semantics. With `k` commas there are exactly `k + 1` fields, including empty ones at the start, middle and end. Tools that split by "reading tokens" (`stringstream` with `getline`, `operator>>`) are built for token streams and quietly drop the final empty field.\n\n## Optimal\nThe `find`-based loop below is also O(n) and avoids appending character by character. Time O(n), space O(n) for the output.\n\n## C++ walkthrough\n`find(\',\', start)` returns the index of the next comma at or after `start`, or `string::npos` (the largest `size_t`) if none. `substr(start, len)` copies `len` characters starting at `start`: always compute `len = comma - start`. The loop ends in the `npos` branch, which pushes the tail `substr(start)` (to the end), so the empty last field in `"x,"` is produced naturally. Every `substr` copies, so each character is copied once: O(n) total, not O(n^2).\n\n## Common bugs\nTreating the second argument of `substr` as an end index; forgetting the final field; using `getline` and losing a trailing empty field (and returning no fields for an empty line); comparing `find`\'s result to `-1` through an `int` instead of using `string::npos`.\n\n## Follow-ups\nSplit on any whitespace and skip empties. Honour quoted fields that may contain commas. Split into integers with `stoi`.\n\n## Similar problems\nA basic parsing warm-up, in the spirit of Reverse Words in a String (LeetCode 151).\n',reference:"class Solution {\npublic:\n    vector<string> splitFields(string line) {\n        vector<string> fields;\n        size_t start = 0;\n        while (true) {\n            const size_t comma = line.find(',', start);\n            if (comma == string::npos) {\n                fields.push_back(line.substr(start));  // the last field runs to the end, possibly empty\n                break;\n            }\n            fields.push_back(line.substr(start, comma - start));  // substr takes (pos, LENGTH)\n            start = comma + 1;\n        }\n        return fields;\n    }\n};\n",hints:'## Nudge\nWhat should `"x,"` and `""` give? Count the fields by counting the commas.\n## Approach\n`k` commas make `k + 1` fields. Walk the line with `find(\',\', start)`: take the text from `start` up to the comma, then move `start` just past the comma. After the last comma, the rest of the line is the final field.\n## Key insight\n`substr(pos, len)` takes a start and a length, not an end index. The length of a field is `comma - start`. And `getline(ss, part, \',\')` looks convenient but never returns a trailing empty field, so it fails the `"x,"` and `""` cases.\n',loadTests:async()=>(await e.A(78933)).default},"forge-chain":{meta:{id:"forge-chain",region:"R0",title:"Forge Chain",difficulty:"E",patterns:["syntax"],signals:["write this function","build a ListNode list with new","return nullptr for empty input","keep a tail pointer"],prerequisites:[],parSeconds:420,complexity:{time:"O(n)",space:"O(n)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.2,perf:.4},similar:[{name:"Merge Two Sorted Lists",lcNumber:21}],spec:{kind:"function",name:"forgeChain",returns:"ListNode*",params:[{type:"vector<int>",name:"values"}]}},statement:"# Forge Chain\n\nBuild a singly linked list from an array: the first value becomes the head, the second value the next node, and so on. Return the head. For an empty array return `nullptr`.\n\nYou create nodes with `new`. In interviews you normally do not free them, and you may say so aloud.\n\n(The node type is the usual `ListNode` with `val` and `next`; `ListNode(int x)` and `ListNode(int x, ListNode* next)` constructors exist.)\n\n## Examples\n\n- `values = [1,2,3]` gives the list `[1,2,3]`.\n- `values = [7]` gives `[7]`.\n- `values = [0,0]` gives `[0,0]`.\n- `values = []` gives `[]`.\n\n## Constraints\n\n- `0 <= values.size() <= 100000`\n- `-1000 <= values[i] <= 1000`\n",editorial:"## Signals\nConstructing a linked list: `new` for each node, plus a tail pointer so appends are O(1).\n\n## Brute force\nWalk to the end of the list from the head for every new value. O(n^2) time. Fine for small inputs; the checker builds from the back instead.\n\n## Key insight\nKeep a `tail` pointer. Each append is two assignments. A dummy head removes the empty-list special case.\n\n## Optimal\nO(n) time, O(n) space for the nodes themselves (that is the output, not extra work).\n\n## C++ walkthrough\n`new ListNode(value)` allocates one node on the heap and returns a pointer to it; the node outlives the function, unlike a local variable, which would dangle. `ListNode dummy(0);` lives on the stack and is fine because only `dummy.next` escapes. `for (const int v : values)` iterates without copying the vector's elements again.\n\n## Common bugs\nReturning `&dummy` or `dummy` rather than `dummy.next`, so the answer has an extra leading 0. Returning the tail instead of the head. Building in reverse by mistake. Creating a node on the stack (`ListNode node(v); tail->next = &node;`), which dangles as soon as the loop iteration ends. Dropping the last element with an off-by-one loop bound.\n\n## Follow-ups\nBuild the list from the back with no dummy node. Build a list that is a cycle. Free the list correctly when asked to.\n\n## Similar problems\nMerge Two Sorted Lists (LeetCode 21) builds its result with the same tail-pointer idiom.\n",reference:"class Solution {\npublic:\n    ListNode* forgeChain(vector<int> values) {\n        ListNode dummy(0);                       // stack node: only dummy.next escapes\n        ListNode* tail = &dummy;\n        for (const int value : values) {\n            tail->next = new ListNode(value);    // heap node: it must outlive this function\n            tail = tail->next;\n        }\n        return dummy.next;                       // nullptr when values is empty\n    }\n};\n",hints:"## Nudge\nYou need to append at the end of the list many times. What pointer would make each append O(1)?\n## Approach\nMake a dummy node on the stack and a pointer `tail` to it. For each value, do `tail->next = new ListNode(value); tail = tail->next;`. At the end return `dummy.next`.\n## Key insight\nStarting from a dummy node means the first append needs no special case, and an empty array naturally returns `dummy.next`, which is still `nullptr`. Building from the back (prepending) also works, but then you must walk the array in reverse.\n",loadTests:async()=>(await e.A(3791)).default},"grid-turn":{meta:{id:"grid-turn",region:"R0",title:"Grid Turn",difficulty:"E",patterns:["syntax"],signals:["write this function","build a 2D vector of a given shape","rows and columns swap on a non-square grid"],prerequisites:[],parSeconds:360,complexity:{time:"O(rows * cols)",space:"O(rows * cols)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.2,perf:.4},similar:[{name:"Transpose Matrix",lcNumber:867}],spec:{kind:"function",name:"transposeGrid",returns:"vector<vector<int>>",params:[{type:"const vector<vector<int>>&",name:"grid"}]}},statement:"# Grid Turn\n\nA map room stores each tide chart as a grid of integers, `rows` lines of `cols` numbers each. The archivist needs the chart turned on its side: the number at row `i`, column `j` of the input must appear at row `j`, column `i` of the output.\n\nReturn the turned grid. The result has `cols` rows and each of them has `rows` entries. The grid is not necessarily square.\n\n## Examples\n\n- `grid = [[1, 2, 3], [4, 5, 6]]` gives `[[1, 4], [2, 5], [3, 6]]`.\n- `grid = [[7]]` gives `[[7]]`.\n- `grid = [[1], [2], [3]]` gives `[[1, 2, 3]]`.\n\n## Constraints\n\n- `1 <= rows, cols` and `rows * cols <= 100000`\n- every row has the same length\n- `-1000000000 <= grid[i][j] <= 1000000000`\n",editorial:"## Signals\n\"Row becomes column\", a non-square matrix, and an output whose shape differs from the input's.\n\n## Brute force\nWalk down each input column and push its values into a new row. This is already O(rows * cols), the best possible because every value must be written once. It is the checker, and it shows the idea without any index arithmetic about the answer's shape.\n\n## Key insight\nThe output shape is `cols x rows`. Allocate it up front with `vector<vector<int>> turned(cols, vector<int>(rows))`, then assign `turned[j][i] = grid[i][j]`. All bugs in this problem come from mixing up which size belongs to which dimension.\n\n## Optimal\nOne pass over all cells. Time O(rows * cols), space O(rows * cols) for the answer (the input is read-only, so an in-place swap is only possible for square grids).\n\n## C++ walkthrough\n`vector<int>(rows)` is a row of `rows` zeros; the outer constructor copies that row `cols` times. `grid[0].size()` is the column count, which is why the constraints promise at least one row. `size_t` is unsigned, so the loops use `<` and never count down past zero. `const vector<vector<int>>&` avoids copying the whole grid.\n\n## Common bugs\nAssuming a square grid and swapping in place; allocating `rows x cols` instead of `cols x rows`; reading `grid[0].size()` on an empty grid (excluded here); using `int` loop variables compared against `size_t`, which draws warnings.\n\n## Follow-ups\nRotate the grid 90 degrees clockwise (transpose, then reverse each row). Transpose a square grid in place. Flatten the grid into one vector and index it as `i * cols + j`.\n\n## Similar problems\nTranspose Matrix (LeetCode 867).\n",reference:"class Solution {\npublic:\n    vector<vector<int>> transposeGrid(const vector<vector<int>>& grid) {\n        const size_t rows = grid.size();\n        const size_t cols = grid[0].size();\n        // The answer has the shape cols x rows: swap the two sizes when you build it.\n        vector<vector<int>> turned(cols, vector<int>(rows));\n        for (size_t i = 0; i < rows; ++i) {\n            for (size_t j = 0; j < cols; ++j) {\n                turned[j][i] = grid[i][j];\n            }\n        }\n        return turned;\n    }\n};\n",hints:"## Nudge\nSay the input has 2 rows and 3 columns. How many rows and how many columns must the answer have?\n## Approach\nCreate the answer first with the swapped shape, `cols` rows of `rows` zeros each, then copy every cell: the value at `grid[i][j]` goes to `turned[j][i]`.\n## Key insight\n`vector<vector<int>> turned(cols, vector<int>(rows));` builds the 2D vector in one line. Do not reuse one square loop bound for both dimensions: rows and columns are different sizes unless the grid happens to be square.\n",loadTests:async()=>(await e.A(39994)).default},"leaf-sum":{meta:{id:"leaf-sum",region:"R0",title:"Leaf Sum",difficulty:"E",patterns:["syntax"],signals:["write this function","TreeNode","a leaf has two null children","recursion with a null check"],prerequisites:[],parSeconds:480,complexity:{time:"O(n)",space:"O(h)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.2,perf:.4},similar:[{name:"Sum of Left Leaves",lcNumber:404}],spec:{kind:"function",name:"leafSum",returns:"int",params:[{type:"TreeNode*",name:"root"}]}},statement:"# Leaf Sum\n\nGiven the root of a binary tree, return the sum of the values of its leaves. A leaf is a node with no children at all. A node that has one child is not a leaf. The sum of an empty tree is `0`.\n\n(The node type is the usual `TreeNode` with `val`, `left` and `right`.)\n\n## Examples\n\n- `root = [3,9,20,null,null,15,7]` gives `31` (9 + 15 + 7).\n- `root = [1,2]` gives `2` (node 1 has one child, so it is not a leaf).\n- `root = [8]` gives `8`.\n- `root = []` gives `0`.\n\n## Constraints\n\n- `0 <=` number of nodes `<= 5000`\n- `-1000 <= val <= 1000`\n",editorial:"## Signals\nA property of the leaves only. Spot the leaf by its two null children and let recursion handle the rest.\n\n## Brute force\nTraverse with an explicit stack, add `val` whenever a popped node has no children. O(n) time, O(h) space.\n\n## Key insight\nThree cases are enough: null gives 0, a leaf gives its value, anything else gives the sum over its children. Because the null case already returns 0, you never need to check whether a single child exists.\n\n## Optimal\nEach node is visited once: O(n) time; recursion depth O(h), at worst O(n) = 5000 here.\n\n## C++ walkthrough\n`root->left == nullptr && root->right == nullptr` is the leaf test. The sum fits in `int`: 5000 values of at most 1000 in magnitude. The first line `if (root == nullptr) return 0;` protects every dereference that follows it.\n\n## Common bugs\nAdding every node's value (that is a total, not a leaf sum). Using `||` so a node with one child counts as a leaf. Skipping the null check and crashing on the empty tree or on one-child nodes. Treating the root as a leaf when it has children.\n\n## Follow-ups\nSum only the left leaves. Return the leaves in order as a vector. Count the leaves instead of summing them.\n\n## Similar problems\nSum of Left Leaves (LeetCode 404).\n",reference:"class Solution {\npublic:\n    int leafSum(TreeNode* root) {\n        if (root == nullptr) return 0;\n        if (root->left == nullptr && root->right == nullptr) return root->val;  // a leaf has NO children\n        return leafSum(root->left) + leafSum(root->right);\n    }\n};\n",hints:"## Nudge\nHow do you recognise a leaf using only the two child pointers?\n## Approach\nRecurse. If the node is `nullptr`, contribute `0`. If both `left` and `right` are `nullptr`, it is a leaf: return its value. Otherwise return the leaf sum of the left subtree plus that of the right subtree.\n## Key insight\nThe leaf test is `left == nullptr && right == nullptr`: both, not either. A node with exactly one child must pass the recursion down to that child, and the missing child contributes `0` through the null base case.\n",loadTests:async()=>(await e.A(70145)).default},"ledger-digits":{meta:{id:"ledger-digits",region:"R0",title:"Ledger Digits",difficulty:"E",patterns:["syntax"],signals:["write this function","digits of a number","values beyond 32 bits"],prerequisites:[],parSeconds:240,complexity:{time:"O(d)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.3,edge:.4,adversarial:.3,perf:0},similar:[{name:"Add Digits",lcNumber:258}],spec:{kind:"function",name:"digitSum",returns:"int",params:[{type:"long long",name:"n"}]}},statement:"# Ledger Digits\n\nThe harbour clerk checks each ledger number by adding up its decimal digits. The sign is not a digit, so `-407` and `407` both give `4 + 0 + 7 = 11`.\n\nGiven the ledger number `n`, return the sum of its decimal digits.\n\n## Examples\n\n- `n = 1234` gives `10`.\n- `n = -407` gives `11`.\n- `n = 0` gives `0`.\n\n## Constraints\n\n- `-9223372036854775807 <= n <= 9223372036854775807` (it fits in a 64-bit signed integer).\n",editorial:'## Signals\n"Write this function" on a single number with no data structure: this is plain control flow plus integer arithmetic. The wide constraint (64-bit) is the hint to keep every variable as `long long`.\n\n## Brute force\nConvert the number to text with `to_string` and add up the characters that are digits. It is correct and short; it costs O(d) time and O(d) space for `d` digits, and it allocates a string.\n\n## Key insight\n`n % 10` gives the last digit and `n / 10` drops it, so a loop over digits needs no string at all. The one trap is the sign: C++ truncates division toward zero and gives `%` the sign of the dividend, so for negative `n` each remainder is negative.\n\n## Optimal\nLoop while `n != 0`: take `n % 10`, add its absolute value to the total, then do `n /= 10`. Invariant: `total` holds the digit sum of the digits already removed. At most 19 iterations, so time O(d) and space O(1).\n\n## C++ walkthrough\nThe parameter is `long long` and is modified in place (it is a copy). Taking the absolute value per digit, not of `n`, avoids the overflow of `-n` at the minimum 64-bit value (the constraint excludes it, but the habit is the point). The result is at most 19 * 9, so `int` is safe.\n\n## Common bugs\nAdding signed remainders so negative inputs give negative sums; narrowing `n` to `int` and losing the high digits; looping `while (n > 0)` which returns 0 for every negative input.\n\n## Follow-ups\nRepeat until a single digit remains (digital root, and the O(1) formula using mod 9). Count digits instead of summing them. Do it in base 2 and compare with `__builtin_popcountll`.\n\n## Similar problems\nAdd Digits (LeetCode 258).\n',reference:"class Solution {\npublic:\n    int digitSum(long long n) {\n        int total = 0;\n        while (n != 0) {\n            const int digit = static_cast<int>(n % 10);  // negative n gives a negative remainder\n            total += digit < 0 ? -digit : digit;\n            n /= 10;  // truncates toward zero, so the loop ends at 0 for either sign\n        }\n        return total;\n    }\n};\n",hints:"## Nudge\nWhich two operators peel the last digit off a number and then shorten it?\n\n## Approach\n`n % 10` is the last digit and `n / 10` removes it. Repeat until the number is 0. Think about what `%` returns when `n` is negative.\n\n## Key insight\nIn C++ `%` takes the sign of the dividend, so `-407 % 10` is `-7`. Take the absolute value of each digit (not of `n`, which would overflow for the most negative value). Keep `n` as `long long` the whole way.\n",loadTests:async()=>(await e.A(37209)).default},"letter-tally":{meta:{id:"letter-tally",region:"R0",title:"Letter Tally",difficulty:"E",patterns:["syntax"],signals:["write this function","count letters with c - a","case-insensitive counting into 26 buckets"],prerequisites:[],parSeconds:360,complexity:{time:"O(n)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.2,perf:.4},similar:[{name:"Ransom Note",lcNumber:383}],spec:{kind:"function",name:"letterTally",returns:"vector<int>",params:[{type:"string",name:"s"}]}},statement:'# Letter Tally\n\nA printer is counting how many times each letter of the alphabet appears in a message. Uppercase and lowercase count as the same letter, and anything that is not a letter (digits, spaces, punctuation) is ignored.\n\nReturn a vector of exactly 26 integers: entry `0` is the count of `a`/`A`, entry `1` the count of `b`/`B`, and so on up to entry `25` for `z`/`Z`.\n\n## Examples\n\n- `s = "Abba"` gives `2` at index 0, `2` at index 1 and zeros elsewhere.\n- `s = "zZ!"` gives `2` at index 25 and zeros elsewhere.\n- `s = "42 [@]"` gives 26 zeros.\n\n## Constraints\n\n- `0 <= s.size() <= 200000`\n- `s` contains printable ASCII characters (codes 32 to 126)\n',editorial:"## Signals\n\"Count each letter\", a fixed small alphabet, and case-insensitive matching: a fixed-size count array replaces a map.\n\n## Brute force\nFor each of the 26 letters, scan the whole string and count matches of the lower- and uppercase form. O(26 * n), fine for checking, and obviously correct.\n\n## Key insight\n`c - 'a'` turns a lowercase letter into a bucket index 0..25 because letters are contiguous in ASCII. Normalise case with `tolower` first, and check the range before indexing, since the characters just outside the ranges (`@`, `[`, `` ` ``, `{`) would produce out-of-bounds indices and undefined behaviour.\n\n## Optimal\nOne pass with a 26-slot array. Time O(n), space O(1) (26 counters). This count-array trick is the base for anagram checks, window problems on lowercase letters and sorting by frequency.\n\n## C++ walkthrough\n`tolower` and `isalpha` come from `<cctype>` and take an `int` that must be representable as `unsigned char` (or `EOF`); a plain `char` that is negative is undefined behaviour, so cast first. `vector<int>(26, 0)` is 26 zeros. The subtraction `c - 'a'` promotes both operands to `int`, so it is a plain integer in `[0, 25]` after the guard.\n\n## Common bugs\nIgnoring uppercase; forgetting the range guard (digits and spaces index negative or past 25); an off-by-one in the upper bound (`< 'z'`); treating `'A'..'z'` as one contiguous block of letters (it contains six non-letters).\n\n## Follow-ups\nCheck whether two strings are anagrams. Find the most frequent letter. Count letters in a sliding window of fixed length.\n\n## Similar problems\nRansom Note (LeetCode 383), Valid Anagram (LeetCode 242).\n",reference:"class Solution {\npublic:\n    vector<int> letterTally(string s) {\n        vector<int> tally(26, 0);\n        for (const char raw : s) {\n            // Cast to unsigned char first: passing a negative char to <cctype> functions is undefined.\n            const char c = static_cast<char>(tolower(static_cast<unsigned char>(raw)));\n            if (c >= 'a' && c <= 'z') ++tally[c - 'a'];  // char arithmetic gives the bucket index\n        }\n        return tally;\n    }\n};\n",hints:"## Nudge\nWhich letter has index 0, and how can a character tell you its own index?\n## Approach\nKeep `vector<int> tally(26, 0)`. For each character, make it lowercase, check that it is between `'a'` and `'z'`, and increment `tally[c - 'a']`.\n## Key insight\nIn C++ a `char` is a small integer, so `c - 'a'` is the letter's position in the alphabet. Always guard the range before indexing: `'['` and `'@'` sit next to the letters in ASCII and would otherwise index outside the 26 buckets. Use `tolower` (cast to `unsigned char` first) instead of writing separate branches for uppercase.\n",loadTests:async()=>(await e.A(42088)).default},"middle-link":{meta:{id:"middle-link",region:"R0",title:"Middle Link",difficulty:"E",patterns:["syntax"],signals:["write this function","ListNode","count first, then walk","return a node, not a value"],prerequisites:[],parSeconds:420,complexity:{time:"O(n)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.2,perf:.4},similar:[{name:"Middle of the Linked List",lcNumber:876}],spec:{kind:"function",name:"middleLink",returns:"ListNode*",params:[{type:"ListNode*",name:"head"}]}},statement:"# Middle Link\n\nGiven the head of a singly linked list, return the node in the middle, which is the node at index `n / 2` (counting from 0, integer division). For an even length that is the second of the two middle nodes. The answer is the node itself, so the result is the list that starts there. For an empty list return `nullptr`.\n\n## Examples\n\n- `head = [1,2,3,4,5]` gives `[3,4,5]`.\n- `head = [1,2,3,4]` gives `[3,4]`.\n- `head = [9]` gives `[9]`.\n- `head = []` gives `[]`.\n\n## Constraints\n\n- `0 <=` number of nodes `<= 100000`\n- `-1000 <= val <= 1000`\n",editorial:"## Signals\nPointer walking: a position in a list is reached by following `next`, so you must count first.\n\n## Brute force\nCopy node pointers into a `vector<ListNode*>` and return `nodes[n / 2]`. O(n) time and O(n) space.\n\n## Key insight\nTwo passes need no extra memory: one to learn `n`, one to walk `n / 2` steps. The walk never leaves the list because `n / 2 < n` whenever `n >= 1`.\n\n## Optimal\nTime O(n), space O(1).\n\n## C++ walkthrough\n`for (ListNode* cur = head; cur != nullptr; cur = cur->next) ++n;` counts. The second loop is `for (int i = 0; i < n / 2; ++i) head = head->next;`, which reuses the parameter `head` (it is a local copy of the pointer, so the caller's list is untouched). With `n == 0` the loop body never runs and `head` is already `nullptr`.\n\n## Common bugs\nReturning the first middle (index `(n - 1) / 2`) for even lengths. Walking `n / 2 + 1` steps and falling off the end. Returning the value instead of the node. Dereferencing a null `head` before checking it.\n\n## Follow-ups\nDo it in one pass with a slow and a fast pointer. Return the first middle for even lengths. Split the list into two halves.\n\n## Similar problems\nMiddle of the Linked List (LeetCode 876).\n",reference:"class Solution {\npublic:\n    ListNode* middleLink(ListNode* head) {\n        int n = 0;\n        for (ListNode* cur = head; cur != nullptr; cur = cur->next) ++n;\n        for (int i = 0; i < n / 2; ++i) head = head->next;  // n/2 steps stays inside the list\n        return head;\n    }\n};\n",hints:"## Nudge\nYou cannot jump to index `n / 2` in a linked list. What do you need to know before you can walk there?\n## Approach\nFirst pass: count the nodes. Second pass: start at `head` and follow `next` exactly `n / 2` times. Return the node you land on. If `head` is `nullptr` the count is 0 and the answer is `nullptr` too.\n## Key insight\nTwo simple passes are already O(n). (Later you will meet the fast and slow pointer trick that does it in one pass.) The important C++ habit here is to loop on `node != nullptr` and never to follow `next` from a null pointer.\n",loadTests:async()=>(await e.A(71826)).default},"overlap-count":{meta:{id:"overlap-count",region:"R0",title:"Overlap Count",difficulty:"E",patterns:["syntax"],signals:["write this function","find with a start position","substr copies, so do not slice a suffix per step"],prerequisites:[],parSeconds:360,complexity:{time:"O(n * m)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.2,perf:.4},similar:[{name:"Find the Index of the First Occurrence in a String",lcNumber:28}],spec:{kind:"function",name:"countOverlaps",returns:"int",params:[{type:"string",name:"text"},{type:"const string&",name:"pat"}]}},statement:'# Overlap Count\n\nA sailor\'s tune is written as a string of letters. A phrase is a shorter string. Count how many positions in the tune are the start of the phrase. Occurrences may overlap: the phrase `aa` appears three times in `aaaa`.\n\n## Examples\n\n- `text = "aaaa", pat = "aa"` gives `3`.\n- `text = "abcabc", pat = "bc"` gives `2`.\n- `text = "abc", pat = "d"` gives `0`.\n- `text = "ab", pat = "abc"` gives `0` (the phrase is longer than the tune).\n\n## Constraints\n\n- `0 <= text.size() <= 200000`\n- `1 <= pat.size() <= 50`\n- both strings contain lowercase letters only\n',editorial:'## Signals\n"Find every occurrence" with overlap allowed, and a string long enough that per-step copies matter.\n\n## Brute force\nFor every start position compare up to `m` characters with the phrase. O(n * m) with m at most 50, so about 10^7 steps at the limits. It is the checker and it is even fast enough here; the point of the problem is the idiomatic `find` loop and the copy trap.\n\n## Key insight\nTo allow overlaps, restart the search one character after the previous match start. To keep it linear, do not create substrings: `find(pat, from)` searches in place. `substr` always allocates and copies its result, so slicing a suffix per iteration turns O(n) into O(n^2) bytes copied.\n\n## Optimal\nLoop on `find(pat, pos + 1)`. Time O(n * m) worst case but with `m <= 50` it is a small constant in practice, space O(1). (Linear-time matching with KMP or Z comes later, in the String Sea region, for when the phrase may be long.)\n\n## C++ walkthrough\n`find` returns the starting index of the first match at or after the given position, or `string::npos`. Because the return type is `size_t`, compare against `string::npos`, never `-1` stored in an `int`. `pat` is taken as `const string&` since it is read-only. The empty text case needs no special code: `find` simply returns `npos`.\n\n## Common bugs\nAdvancing by `pat.size()` (loses overlaps); `substr(i)` per step (time limit); writing the window loop with `<` instead of `<=` and missing a match at the very end; computing `text.size() - pat.size()` in `size_t` when the phrase is longer than the text, which wraps around to a huge number.\n\n## Follow-ups\nReturn the positions of all matches. Count matches of a phrase that may be as long as the text, using KMP. Count case-insensitively.\n\n## Similar problems\nFind the Index of the First Occurrence in a String (LeetCode 28).\n',reference:"class Solution {\npublic:\n    int countOverlaps(string text, const string& pat) {\n        int count = 0;\n        size_t pos = text.find(pat);\n        while (pos != string::npos) {\n            ++count;\n            pos = text.find(pat, pos + 1);  // move by ONE so overlapping occurrences are found\n        }\n        return count;\n    }\n};\n",hints:'## Nudge\nIn `"aaaa"` the phrase `"aa"` starts at positions 0, 1 and 2. After you find one match, where should the next search begin?\n## Approach\nUse `text.find(pat, from)` in a loop. Each time it returns a position `pos`, count it and continue from `pos + 1`. Stop when it returns `string::npos`.\n## Key insight\nSearching from `pos + pat.size()` skips overlapping matches. Also avoid `text.substr(i)` inside the loop: `substr` copies, and copying a suffix at every position is O(n^2) work. Pass a start position to `find` instead, which copies nothing.\n',loadTests:async()=>(await e.A(40600)).default},"pocket-calendar":{meta:{id:"pocket-calendar",region:"R0",title:"Pocket Calendar",difficulty:"E",patterns:["syntax"],signals:["write this function","fixed lookup table","leap year rule"],prerequisites:[],parSeconds:300,complexity:{time:"O(1)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.4,adversarial:.4,perf:0},similar:[{name:"Day of the Year",lcNumber:1154}],spec:{kind:"function",name:"dayOfYear",returns:"int",params:[{type:"int",name:"year"},{type:"int",name:"month"},{type:"int",name:"day"}]}},statement:"# Pocket Calendar\n\nGiven a valid date in the Gregorian calendar, return which day of its year it is, where January 1 is day `1`.\n\nA year is a **leap year** (February has 29 days) when it is divisible by 4, except years divisible by 100 are not leap years, unless they are also divisible by 400.\n\n## Examples\n\n- `year = 2023, month = 1, day = 31` gives `31`.\n- `year = 2024, month = 3, day = 1` gives `61` (2024 is a leap year).\n- `year = 1900, month = 12, day = 31` gives `365` (1900 is not a leap year).\n\n## Constraints\n\n- `1 <= year <= 9999`\n- `1 <= month <= 12`\n- The date is valid: `day` is between 1 and the length of that month.\n",editorial:'## Signals\nA calendar with irregular month lengths and an exception-laden rule. Fixed irregular data is best stored in a lookup table instead of an if-chain, and the leap rule is best isolated in a tiny helper.\n\n## Brute force\nWalk through the year day by day, counting, until the target month and day appear. It is easy to trust and independent of the table in the reference.\n\n## Key insight\nPrecompute "days before this month" for a non-leap year, so the answer is `table[month - 1] + day` plus one for leap years after February. The leap condition is `(y % 4 == 0 && y % 100 != 0) || y % 400 == 0`; reading it as three nested exceptions is the safest way to remember it.\n\n## Optimal\nOne table lookup, one helper call. Time O(1), space O(1).\n\n## C++ walkthrough\n`static const int daysBefore[12]` inside the function is a static local: it is initialised the first time the function runs and then lives for the rest of the program, so the table is not rebuilt on every call (a plain local array would be). `static bool isLeap` inside the class is a static member function: it belongs to the class, takes no hidden `this`, and can be called without an object, which fits a pure helper. A `static` free function or variable at file scope means something else again: internal linkage, visible only in that file. Array indexing is zero-based, hence `month - 1`.\n\n## Common bugs\nOnly testing `year % 4`; dropping the 400 rule; adding the leap day for February dates; indexing the table with `month`; a typo in one cumulative total.\n\n## Follow-ups\nReturn the date given a year and a day number. Count the days between two dates. Find the weekday of a date.\n\n## Similar problems\nDay of the Year (LeetCode 1154).\n',reference:"class Solution {\n    // static member function: no object state needed, so it does not get a `this`.\n    static bool isLeap(int year) {\n        return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;\n    }\n\npublic:\n    int dayOfYear(int year, int month, int day) {\n        // static local: built once, not on every call. Days in the year before each month starts (non-leap).\n        static const int daysBefore[12] = {0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334};\n        int n = daysBefore[month - 1] + day;\n        if (month > 2 && isLeap(year)) ++n;  // the extra day exists only after February 29\n        return n;\n    }\n};\n",hints:"## Nudge\nIf you knew how many days came before the first day of each month, what would the day number be? What changes in a leap year?\n## Approach\nKeep a table of the days that pass before each month starts in a normal year. Add the day of the month. In a leap year, add one more day if the date is after February.\n## Key insight\nThe leap rule has three layers: divisible by 4, but not by 100, unless by 400. The extra day only exists from March onward, so February dates are unchanged. A `static const` array is built once and shared by all calls.\n",loadTests:async()=>(await e.A(55435)).default},"pouch-sum":{meta:t.f,statement:"# Pouch Sum\n\nA traveller carries a pouch of coins. Coin `i` is worth `coins[i]`. The toll keeper only accepts coins worth at least `minValue`; all smaller coins are refused. Return the total value of the accepted coins.\n\n## Examples\n\n- `coins = [5, 1, 7, 3], minValue = 4` gives `12` (the 5 and the 7).\n- `coins = [2000000000, 2000000000], minValue = 1` gives `4000000000`.\n- `coins = [1, 2, 3], minValue = 10` gives `0`.\n\n## Constraints\n\n- `0 <= coins.size() <= 100000`\n- `0 <= coins[i] <= 2000000000`\n- `0 <= minValue <= 2000000000`\n",editorial:'## Signals\n"Add up only the values that qualify" is a filtered accumulation: one pass, one running total, one condition. The words "total" and "value up to 2 * 10^9" point at the accumulator\'s range.\n\n## Brute force\nThere is nothing asymptotically slower to compare with; every solution reads each coin once. The reference check uses an index loop with a 128-bit accumulator, so it cannot overflow and proves the 64-bit answer is exact.\n\n## Key insight\nThe answer is at most 10^5 * 2 * 10^9 = 2 * 10^14. That fits in 64 bits but not in 32, so the accumulator must be `long long`. The filter is "at least", so the comparison is `>=`.\n\n## Optimal\nOne pass: if the coin passes the filter, add it. Time O(n), space O(1) beyond the input.\n\n## C++ walkthrough\n`for (const auto& coin : coins)` reads each element without copying or modifying it. `total += coin` promotes the `int` to `long long` before adding. The pattern is the same shape as every accumulate-with-condition loop: initialise the accumulator with its final type, loop, test, update.\n\n## Common bugs\n`int total`; `>` instead of `>=`; stopping at `size() - 1`; filtering with the wrong direction (`<=`).\n\n## Follow-ups\nCount the accepted coins as well. Return the sum modulo 10^9 + 7. Do it for several `minValue` queries at once after sorting and building prefix sums.\n\n## Similar problems\nSum of All Odd Length Subarrays (LeetCode 1588) is a related accumulation exercise.\n',reference:"class Solution {\npublic:\n    long long pouchSum(vector<int> coins, int minValue) {\n        long long total = 0;  // 10^5 coins of 2 * 10^9 do not fit in int\n        for (const auto& coin : coins) {\n            if (coin >= minValue) total += coin;\n        }\n        return total;\n    }\n};\n",hints:'## Nudge\nWhich coins end up in the total, and how big can that total get?\n\n## Approach\nWalk the coins once. For each coin, test it against `minValue`, and only then add it to one running total. Decide that total\'s type before writing the loop.\n\n## Key insight\n`coin >= minValue` is the filter ("at least"), and the total can reach 2 * 10^14, so it must be `long long`. Adding an `int` coin to a `long long` total widens the coin first, which is exactly what you want.\n',loadTests:async()=>(await e.A(58290)).default},"rank-roster":{meta:{id:"rank-roster",region:"R0",title:"Rank Roster",difficulty:"E",patterns:["syntax"],signals:["write this function","custom ordering on a struct","operator< decides sort order"],prerequisites:[],parSeconds:480,complexity:{time:"O(n log n)",space:"O(n)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.2,perf:.4},similar:[{name:"Relative Ranks",lcNumber:506}],spec:{kind:"function",name:"rankPlayers",returns:"vector<int>",params:[{type:"vector<vector<int>>",name:"players"}]}},statement:"# Rank Roster\n\nA tournament keeps a roster of players. Each entry is `[id, score]`. Return the ids in ranking order: the higher score ranks first, and players with equal scores are ordered by the smaller id first. All ids are different.\n\nWrite a small `struct Player` with a constructor and an `operator<` so that `sort` can do the work.\n\n## Examples\n\n- `players = [[7,50],[3,90],[5,50]]` gives `[3,5,7]`.\n- `players = [[1,10],[2,10],[0,10]]` gives `[0,1,2]`.\n- `players = [[4,-5]]` gives `[4]`.\n- `players = []` gives `[]`.\n\n## Constraints\n\n- `0 <= players.size() <= 100000`\n- `0 <= id <= 1000000000`, and every id is different\n- `-1000000000 <= score <= 1000000000`\n",editorial:"## Signals\nA custom ordering over records that carry several fields. In C++ that is `operator<` (or a comparator) on a small struct.\n\n## Brute force\nRepeatedly scan for the best remaining player, append it and mark it used. O(n^2). It is the checker; it times out at the upper limit.\n\n## Key insight\nEncode the rule once, as the struct's `operator<`: higher score first, then smaller id. `std::sort` then uses it everywhere and needs no extra arguments. Ids are unique, so the order is total and the result is fully determined.\n\n## Optimal\nBuild the structs, `sort`, read out the ids. Time O(n log n), space O(n).\n\n## C++ walkthrough\nThe constructor uses a member initialiser list (`: id(id), score(score)`), which constructs the members directly instead of default-constructing and assigning. `operator<` is `const` because sorting compares through const references. `emplace_back(a, b)` builds the `Player` in place from the constructor arguments. `sort` uses `operator<` for ordering, so comparing with `>` on the score is how you say \"bigger first\".\n\n## Common bugs\nWriting `<` on the score (lowest first). Forgetting the tie-break, so equal scores come out in an unspecified order. Tie-breaking by larger id. Returning `true` for equal elements (`<=`), which breaks the strict weak ordering that `sort` requires and can crash it. Forgetting `const` on the operator.\n\n## Follow-ups\nRank by two keys and report each player's position. Keep only the top k with `partial_sort` or a heap. Use a lambda comparator instead of `operator<`.\n\n## Similar problems\nRelative Ranks (LeetCode 506).\n",reference:'struct Player {\n    int id;\n    int score;\n\n    Player(int id, int score) : id(id), score(score) {}\n\n    // "Smaller" means "ranks first": higher score, then smaller id.\n    bool operator<(const Player& other) const {\n        if (score != other.score) return score > other.score;\n        return id < other.id;\n    }\n};\n\nclass Solution {\npublic:\n    vector<int> rankPlayers(vector<vector<int>> players) {\n        vector<Player> roster;\n        roster.reserve(players.size());\n        for (const auto& p : players) roster.emplace_back(p[0], p[1]);\n        sort(roster.begin(), roster.end());\n        vector<int> ids;\n        ids.reserve(roster.size());\n        for (const auto& p : roster) ids.push_back(p.id);\n        return ids;\n    }\n};\n',hints:"## Nudge\n`sort` needs to know when one element should come before another. For ints it knows. For your own struct, you must tell it.\n## Approach\nDefine `struct Player { int id; int score; Player(int id, int score) : id(id), score(score) {} bool operator<(const Player& other) const { ... } };`. Make `operator<` return true when `*this` should come before `other`. Copy every entry into a `vector<Player>`, call `sort(v.begin(), v.end())`, then read the ids out.\n## Key insight\n`operator<` is the whole ranking rule: first compare scores (bigger first, so use `>`), and only when scores are equal fall back to the smaller id. It must be `const`, and it must be a strict ordering: never return true for two equal things.\n",loadTests:async()=>(await e.A(61164)).default},"run-squash":{meta:n,statement:"# Run Squash\n\nA conveyor belt carries labelled crates. Whenever several crates in a row carry the same label, the inspector keeps only the first crate of that run. Crates with equal labels that are separated by a different label are both kept.\n\nGiven the labels `nums` in belt order, return the labels that remain, in the same order.\n\n## Examples\n\n- `nums = [4, 4, 7, 7, 7, 4]` gives `[4, 7, 4]`.\n- `nums = [1, 2, 3]` gives `[1, 2, 3]`.\n- `nums = [9, 9, 9, 9]` gives `[9]`.\n- `nums = []` gives `[]`.\n\n## Constraints\n\n- `0 <= nums.size() <= 300000`\n- `-1000000000 <= nums[i] <= 1000000000`\n- `nums` is **not** sorted\n",editorial:'## Signals\n"Remove while keeping order" on a vector. When many elements go, do not erase them one at a time; compact in one pass (erase-remove idiom).\n\n## Brute force\nCopy an element into a new vector whenever it is the first or differs from its predecessor. O(n) time and extra O(n) space. It is correct and fast; it is the checker because it is obviously right.\n\n## Key insight\nThe real lesson is the cost of `vector::erase`: removing element `i` moves every later element one slot left, O(n - i). Erasing inside a loop therefore turns a linear task into a quadratic one, and the 3·10^5 equal labels in the perf group make that visible. The standard answer is the erase-remove idiom: an algorithm (`unique`, `remove`, `remove_if`) moves the survivors to the front and returns the new logical end, and a single `erase(newEnd, end)` trims the tail.\n\n## Optimal\n`erase(unique(...), end())`. Time O(n), space O(1) extra (the parameter is a copy the function is free to modify).\n\n## C++ walkthrough\n`unique` compares each element with the last kept one and only removes adjacent equals, so it also works on unsorted input for this task. It does not shrink the vector: the elements after the returned iterator are unspecified, so you must erase them. The parameter is taken by value on purpose, so we may modify it and return it.\n\n## Common bugs\nIncrementing the index after an `erase` (the next element slid into the current slot and gets skipped); deduplicating globally with a `set` (changes the meaning); calling `unique` and forgetting the final `erase`; erasing while iterating with a stale iterator.\n\n## Follow-ups\nRemove every occurrence of a given value (`remove`). Remove runs longer than two. Do the same on a linked list.\n\n## Similar problems\nRemove Duplicates from Sorted Array (LeetCode 26), Remove Element (LeetCode 27).\n',reference:"class Solution {\npublic:\n    vector<int> squashRuns(vector<int> nums) {\n        // std::unique shifts the kept elements to the front in one O(n) pass and returns the new end.\n        // It only removes ADJACENT equal elements, which is exactly the rule here.\n        nums.erase(unique(nums.begin(), nums.end()), nums.end());\n        return nums;\n    }\n};\n",hints:"## Nudge\nWhich elements survive? Think about what an element must be compared with to know whether it is the start of a run.\n## Approach\nAn element survives if it is the first one or differs from its left neighbour. Collect survivors, or let the STL shift them to the front for you.\n## Key insight\nCalling `erase` once per duplicate inside a loop shifts the whole tail every time: O(n) each, O(n^2) in total, which is too slow for 3·10^5 equal labels. `nums.erase(unique(nums.begin(), nums.end()), nums.end())` does one pass and one erase.\n",loadTests:async()=>(await e.A(50524)).default},"safe-midpoint":{meta:{id:"safe-midpoint",region:"R0",title:"Safe Midpoint",difficulty:"E",patterns:["syntax"],signals:["write this function","average of two ints","values near the int limit"],prerequisites:[],parSeconds:240,complexity:{time:"O(1)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.4,adversarial:.4,perf:0},similar:[{name:"Binary Search",lcNumber:704}],spec:{kind:"function",name:"midSlot",returns:"int",params:[{type:"int",name:"lo"},{type:"int",name:"hi"}]}},statement:"# Safe Midpoint\n\nA surveyor marks two posts on a very long road, at positions `lo` and `hi` metres from the start, with `lo <= hi`. Place a third post halfway between them. When the gap is odd, round down to the nearer post at the `lo` side.\n\nReturn the position of the middle post.\n\n## Examples\n\n- `lo = 2, hi = 8` gives `5`.\n- `lo = 3, hi = 6` gives `4`.\n- `lo = 2147483646, hi = 2147483647` gives `2147483646`.\n\n## Constraints\n\n- `0 <= lo <= hi <= 2147483647`\n",editorial:'## Signals\n"Average of two ints" with bounds that touch `INT_MAX` is the classic 32-bit overflow trap. The same bug sat in widely used library binary searches for years.\n\n## Brute force\nWiden both values to `long long` first, add, divide by two and narrow back. It is correct, just heavier than needed; it is used as the reference check here.\n\n## Key insight\nThe sum `lo + hi` can be as large as 2^32 - 2, which does not fit in a signed 32-bit integer. The difference `hi - lo` does fit, so move from `lo` by half of the gap.\n\n## Optimal\nReturn `lo + (hi - lo) / 2`. Integer division truncates toward zero and the gap is non-negative, so this equals the floor of the true midpoint. Time O(1), space O(1).\n\n## C++ walkthrough\nSigned integer overflow is undefined behaviour in C++, so `(lo + hi) / 2` is not merely "wraps to a negative number": the compiler may assume it cannot happen. `lo + (hi - lo) / 2` stays in range at every step. `(lo + hi) >> 1` has the same overflow problem; `std::midpoint` (C++20, `<numeric>`) is the library answer.\n\n## Common bugs\nWriting `(lo + hi) / 2`; rounding the other way with `hi - (hi - lo) / 2`; assuming the bug needs huge arrays (a handful of values near 2^31 is enough).\n\n## Follow-ups\nAllow negative positions (then `hi - lo` can overflow too, so use `long long` or `std::midpoint`). Return the ceiling midpoint. Use the safe midpoint inside a binary search for the first true.\n\n## Similar problems\nBinary Search (LeetCode 704) uses exactly this midpoint line.\n',reference:"class Solution {\npublic:\n    int midSlot(int lo, int hi) {\n        // lo + hi can reach 2 * (2^31 - 1) and overflow int; hi - lo cannot.\n        return lo + (hi - lo) / 2;\n    }\n};\n",hints:"## Nudge\nTry `lo = hi = 2147483647`. What does `lo + hi` do?\n\n## Approach\nYou want the average of two numbers without ever forming a value larger than the inputs. Think of walking from `lo` towards `hi`.\n\n## Key insight\n`hi - lo` always fits in `int` here (both are non-negative), so `lo + (hi - lo) / 2` is exact, rounds down, and never overflows. This is the line every binary search should use for its midpoint.\n",loadTests:async()=>(await e.A(27365)).default},"shelf-rank":{meta:{id:"shelf-rank",region:"R0",title:"Shelf Rank",difficulty:"E",patterns:["syntax"],signals:["write this function","answer many queries on a big read-only array","pass large containers by const reference"],prerequisites:[],parSeconds:300,complexity:{time:"O(m log n)",space:"O(m)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.2,perf:.4},similar:[{name:"Search Insert Position",lcNumber:35}],spec:{kind:"function",name:"countBelow",returns:"vector<int>",params:[{type:"const vector<int>&",name:"shelves"},{type:"const vector<int>&",name:"queries"}]}},statement:'# Shelf Rank\n\nA library keeps its shelf heights in a list sorted from lowest to highest (equal heights may repeat). Visitors ask many questions of the form: "how many shelves are strictly lower than `h`?"\n\nGiven the sorted `shelves` and a list of `queries`, return an array where entry `j` is the number of shelves with height strictly less than `queries[j]`.\n\n## Examples\n\n- `shelves = [1, 3, 3, 8], queries = [3, 9, 0]` gives `[1, 4, 0]`.\n- `shelves = [], queries = [5]` gives `[0]`.\n- `shelves = [2, 2, 2], queries = [2, 3]` gives `[0, 3]`.\n\n## Constraints\n\n- `0 <= shelves.size() <= 100000`, sorted in non-decreasing order\n- `0 <= queries.size() <= 100000`\n- `-1000000000 <= shelves[i], queries[j] <= 1000000000`\n',editorial:'## Signals\nA large array that never changes, a long list of queries about it, and a "sorted" promise in the constraints. Sorted data plus many lookups means binary search; many calls on a big container means you must not copy it.\n\n## Brute force\nFor each query, scan all shelves and count the lower ones. That is O(n * m) = 10^10 steps at the limits, far too slow, but it makes a trustworthy checker on small inputs.\n\n## Key insight\nStrictly lower than `h` is exactly the elements before the first element that is `>= h`. That position is what `lower_bound` finds, in O(log n). The second lesson is about calls: a helper declared `int f(vector<int> v, int h)` copies the vector every time it is called, so an O(log n) search silently becomes O(n) per query and the program times out even though the algorithm is right.\n\n## Optimal\nFor each query, one `lower_bound` on the shelves passed by const reference. Time O(m log n), space O(m) for the answer.\n\n## C++ walkthrough\n`const vector<int>&` binds to the caller\'s vector without copying and forbids modifying it. `lower_bound(begin, end, h) - begin` subtracts two random-access iterators to get an index. `static` on the helper means it is a function of the class, not of an object: it has no `this`, which is right for a pure helper. `answer.reserve(queries.size())` avoids reallocations; it is an optimisation, not a requirement.\n\n## Common bugs\n`upper_bound` (counts shelves equal to the query too); passing the vector by value into a helper; scanning linearly; using `int` for iterator differences without a cast, which warns on some compilers.\n\n## Follow-ups\nCount shelves lower than or equal to `h`. Count shelves in a half-open range `[a, b)`. Handle an unsorted shelf list by sorting a copy once.\n\n## Similar problems\nSearch Insert Position (LeetCode 35).\n',reference:'class Solution {\n    // const& means "read it, do not copy it": a copy per query would cost O(n) each.\n    static int countOne(const vector<int>& shelves, int h) {\n        return static_cast<int>(lower_bound(shelves.begin(), shelves.end(), h) - shelves.begin());\n    }\n\npublic:\n    vector<int> countBelow(const vector<int>& shelves, const vector<int>& queries) {\n        vector<int> answer;\n        answer.reserve(queries.size());\n        for (const int h : queries) answer.push_back(countOne(shelves, h));\n        return answer;\n    }\n};\n',hints:"## Nudge\nLook at how many queries there are and how big the shelf list is. What does it cost if every query touches every shelf, or even just copies every shelf?\n## Approach\nThe shelves are sorted, so each query is a binary search for the first shelf that is not lower than the query. The position of that shelf is the answer.\n## Key insight\n`std::lower_bound` returns the first element that is not less than the value, so its distance from `begin()` is exactly the count of strictly lower shelves. Take big containers as `const vector<int>&`: passing by value copies 10^5 ints per call, which times out when it happens 10^5 times.\n",loadTests:async()=>(await e.A(22089)).default},"step-counter":{meta:a,statement:'# Step Counter\n\nImplement a class `StepCounter`, a pedometer with a ceiling.\n\n- `StepCounter(int limit, int start)` creates a counter whose current total is `start`. It can never exceed `limit`. (`0 <= start <= limit`.)\n- `int add(int amount)` adds `amount` (which may be negative) to the total, then forces the total into the range `[0, limit]`, and returns the new total.\n- `int total()` returns the current total.\n- `void reset()` puts the total back to the `start` given to the constructor.\n\nCalls arrive in the usual format: a list of operation names, then a list of argument lists. The output has one entry per call, `null` for the constructor and for `void` methods.\n\n## Examples\n\n- Operations `["StepCounter","add","add","total"]` with arguments `[[10,3],[4],[20],[]]` give `[null,7,10,10]`.\n- Operations `["StepCounter","add","reset","total"]` with arguments `[[5,2],[-9],[],[]]` give `[null,0,null,2]`.\n- Operations `["StepCounter","total"]` with arguments `[[8,8],[]]` give `[null,8]`.\n\n## Constraints\n\n- `1 <= limit <= 1000000`\n- `0 <= start <= limit`\n- `-1000000 <= amount <= 1000000`\n- at most `200000` calls\n',editorial:'## Signals\nA small stateful class: private members, a constructor, and methods that keep an invariant (the total stays inside the range).\n\n## Brute force\nKeep a log of every `add` since the last `reset` and recompute the total from `start` each time, clamping after every step. O(k) per call, so O(n^2) overall. It is the checker.\n\n## Key insight\nClamping after every addition is not the same as clamping once at the end, so the state must be the clamped total, updated incrementally. Each call is then O(1).\n\n## Optimal\nEvery method is O(1), space O(1).\n\n## C++ walkthrough\nThe members are `private` (a `class` defaults to private, so the public part needs the `public:` label). The constructor uses a member initialiser list, which initialises members in the order they are declared, not the order you list them, so declare `limit`, `start`, `current` and initialise them in that order. `int total() const` is `const` because it only reads; the harness calls it on a non-const object, so either form compiles, but `const` is good style. `max(0, min(current, limit))` clamps without branches. `current` is an `int`: the largest intermediate value is 1000000 + 1000000, so `int` is safe here.\n\n## Common bugs\nWriting `limit = limit;` in the constructor body (the member stays at its default). Clamping only at the top, so the total can go negative. `reset` setting the total to 0 instead of `start`. Clamping only when reading `total()`, which makes the stored value drift. Forgetting `public:`, which makes every method private and fails to compile.\n\n## Follow-ups\nAdd a `setLimit` that re-clamps the total. Support `undo` of the last `add`. Make the class generic over the integer type with a template.\n\n## Similar problems\nDesign Parking System (LeetCode 1603): the same "constructor plus small methods" shape.\n',reference:"class StepCounter {\npublic:\n    StepCounter(int limit, int start) : limit(limit), start(start), current(start) {}\n\n    int add(int amount) {\n        current = max(0, min(current + amount, limit));  // clamp after EVERY addition\n        return current;\n    }\n\n    int total() const { return current; }\n\n    void reset() { current = start; }\n\nprivate:\n    int limit;\n    int start;\n    int current;\n};\n",hints:"## Nudge\nThe object has to remember three things between calls. Which three? Put each in a private member.\n## Approach\nStore `limit`, `start` and the current `total` as members. Set them in the constructor with a member initialiser list: `StepCounter(int limit, int start) : limit(limit), start(start), current(start) {}`. In `add`, add the amount to `current`, clamp it with `max(0, min(current, limit))`, and return it. `reset` copies `start` back into `current`.\n## Key insight\nIn `limit(limit)` the member is on the left and the parameter on the right, and C++ reads that correctly. But inside the body, `limit = limit;` assigns the parameter to itself and leaves the member untouched. Use the initialiser list, or write `this->limit = limit;`.\n",loadTests:async()=>(await e.A(92529)).default},"toll-booth":{meta:{id:"toll-booth",region:"R0",title:"Toll Booth",difficulty:"E",patterns:["syntax"],signals:["write this function","price depends on ranges","if / else-if chain with boundaries"],prerequisites:[],parSeconds:240,complexity:{time:"O(1)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.4,adversarial:.4,perf:0},similar:[{name:"Fizz Buzz",lcNumber:412}],spec:{kind:"function",name:"tollFee",returns:"int",params:[{type:"int",name:"hour"},{type:"int",name:"axles"}]}},statement:"# Toll Booth\n\nA bridge charges each vehicle per axle. The price per axle depends on the hour of the day the vehicle arrives (`hour` is on a 24-hour clock):\n\n- **Night**, hours `0` to `5` inclusive: 2 coins per axle.\n- **Rush**, hours `7` to `9` inclusive and hours `16` to `18` inclusive: 6 coins per axle.\n- **Day**, every other hour: 4 coins per axle.\n\nA vehicle with **5 or more axles** also pays a flat heavy-load fee of 10 coins, added once on top of the per-axle price.\n\nReturn the total fee in coins.\n\n## Examples\n\n- `hour = 8, axles = 2` gives `12` (rush, 2 x 6).\n- `hour = 3, axles = 5` gives `20` (night 5 x 2, plus the heavy-load fee 10).\n- `hour = 12, axles = 4` gives `16` (day, 4 x 4, no heavy-load fee).\n\n## Constraints\n\n- `0 <= hour <= 23`\n- `1 <= axles <= 8`\n",editorial:'## Signals\nA price or label that depends on which range a number falls in, with the bounds spelled out in the statement. These problems are won or lost on the boundary values, so list them before coding.\n\n## Brute force\nWrite the price of all 24 hours in a table and add it once per axle. It is slow in spirit but trivially correct, which makes it a good check for the range logic.\n\n## Key insight\nThere are only three prices, so the whole job is mapping an hour to a price. Because the checks run top to bottom and stop at the first match, `hour <= 5` needs no lower bound and the default `rate = 4` covers hour 6 and everything after 18 without listing it.\n\n## Optimal\nOne chain of comparisons, one multiplication and one conditional addition. Time O(1), space O(1).\n\n## C++ walkthrough\n`if / else if` evaluates conditions in order and runs only the first branch that is true. `&&` binds tighter than `||`, so `(hour >= 7 && hour <= 9) || (...)` is already grouped, but the parentheses keep it readable. `rate` starts at the day price so no branch can leave it uninitialised. `switch` would also work here, but each case label is a single value, so ranges would need a block of stacked `case` labels.\n\n## Common bugs\nUsing `<` where the statement says inclusive (hour 9 is rush); treating "5 or more" as `> 5`; charging the heavy-load fee per axle instead of once; reading hour 6 as night.\n\n## Follow-ups\nAdd a weekend discount. Change the clock to minutes since midnight. Replace the chain with a 24-entry lookup table and discuss when each is clearer.\n\n## Similar problems\nFizz Buzz (LeetCode 412).\n',reference:"class Solution {\npublic:\n    int tollFee(int hour, int axles) {\n        int rate = 4;  // day price unless a range below matches\n        if (hour <= 5) {\n            rate = 2;\n        } else if ((hour >= 7 && hour <= 9) || (hour >= 16 && hour <= 18)) {\n            rate = 6;\n        }\n        int fee = rate * axles;\n        if (axles >= 5) fee += 10;  // flat fee, added once\n        return fee;\n    }\n};\n",hints:'## Nudge\nWhich hours share the same price? Write them as ranges before you write any code.\n\n## Approach\nPick the price per axle with an `if / else if / else` chain, multiply by the axle count, then add the heavy-load fee once if the axle count qualifies.\n\n## Key insight\nEvery boundary is inclusive: hour 5 is night, hours 7 and 9 are rush, hour 6 is day. Test `hour <= 5` first and the two rush ranges second, so the chain never needs a lower bound for night. The heavy-load fee is flat, so add it after the multiplication, and use `>= 5` for "5 or more".\n',loadTests:async()=>(await e.A(78810)).default},"tree-height":{meta:{id:"tree-height",region:"R0",title:"Tree Height",difficulty:"E",patterns:["syntax"],signals:["write this function","TreeNode","nullptr is the base case","recursion on left and right"],prerequisites:[],parSeconds:420,complexity:{time:"O(n)",space:"O(h)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.2,perf:.4},similar:[{name:"Maximum Depth of Binary Tree",lcNumber:104}],spec:{kind:"function",name:"treeHeight",returns:"int",params:[{type:"TreeNode*",name:"root"}]}},statement:"# Tree Height\n\nGiven the root of a binary tree, return its height: the number of nodes on the longest path that starts at the root and goes down to a leaf. An empty tree has height `0`.\n\nThe tree node is the usual one:\n\n```cpp\nstruct TreeNode {\n    int val;\n    TreeNode* left;\n    TreeNode* right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n```\n\n## Examples\n\n- `root = [3,9,20,null,null,15,7]` gives `3`.\n- `root = [1,null,2]` gives `2`.\n- `root = [5]` gives `1`.\n- `root = []` gives `0`.\n\n## Constraints\n\n- `0 <=` number of nodes `<= 5000`\n- `-1000 <= val <= 1000`\n",editorial:"## Signals\nA tree question answered from the answers of its two subtrees: recursion with `nullptr` as the base case.\n\n## Brute force\nLevel-order traversal with a queue, counting levels. O(n) time and O(width) memory. It is the checker.\n\n## Key insight\n`height(node) = 1 + max(height(left), height(right))` with `height(nullptr) = 0`. The recursion mirrors the shape of the data.\n\n## Optimal\nVisits each node once: O(n) time. Space is the recursion depth: O(h), at worst O(n) for a skewed tree, which is why the limit is 5000.\n\n## C++ walkthrough\n`max` comes from `<algorithm>` (already included). `root->left` and `root->right` are `TreeNode*`, which may be `nullptr`; the recursive call accepts them because the first line checks for it. The function takes the pointer by value: only the pointer is copied, not the tree.\n\n## Common bugs\nReturning `-1` or `0` for the wrong base (counting edges instead of nodes). Following only the left child. Forgetting the null check and crashing on an empty tree or on any node with one child. Adding the heights of both sides instead of taking the larger.\n\n## Follow-ups\nDo it iteratively with a queue. Return the minimum depth. Check whether the tree is balanced by comparing the heights of both sides at every node.\n\n## Similar problems\nMaximum Depth of Binary Tree (LeetCode 104).\n",reference:"class Solution {\npublic:\n    int treeHeight(TreeNode* root) {\n        if (root == nullptr) return 0;  // an empty tree has no nodes on any path\n        return 1 + max(treeHeight(root->left), treeHeight(root->right));\n    }\n};\n",hints:'## Nudge\nA tree is a node plus two smaller trees. If you knew the height of each smaller tree, what would the height of the whole tree be?\n## Approach\nWrite a recursive function. If `root == nullptr` return `0`. Otherwise return `1 + max(height of left, height of right)`.\n## Key insight\nThe base case is the null pointer, not the leaf. Handling `nullptr` once at the top removes every "does this child exist?" check. Counting nodes (not edges) is what makes the empty tree `0` and a single node `1`.\n',loadTests:async()=>(await e.A(39365)).default},"vowel-census":{meta:{id:"vowel-census",region:"R0",title:"Vowel Census",difficulty:"E",patterns:["syntax"],signals:["write this function","loop over a string","count matching characters"],prerequisites:[],parSeconds:240,complexity:{time:"O(n)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.3,edge:.3,adversarial:.2,perf:.2},similar:[{name:"Reverse Vowels of a String",lcNumber:345}],spec:{kind:"function",name:"countVowels",returns:"int",params:[{type:"string",name:"s"}]}},statement:'# Vowel Census\n\nA lighthouse keeper counts the vowels in every message that arrives by signal flag. The vowels are `a`, `e`, `i`, `o`, `u`, and a vowel counts in both upper and lower case. The letter `y` is not a vowel here.\n\nGiven the message `s`, return how many of its characters are vowels.\n\n## Examples\n\n- `s = "Harbor"` gives `2` (`a` and `o`).\n- `s = "AEIOU sky"` gives `5`.\n- `s = "rhythm"` gives `0`.\n\n## Constraints\n\n- `0 <= s.length() <= 100000`\n- `s` contains only English letters and spaces.\n',editorial:'## Signals\n"Count characters that satisfy a property" over a string is a single pass with a counter. The only decision is how to write the property test.\n\n## Brute force\nSearch each character in a ten-character string of vowel spellings with `find`. That is O(n * 10), which is O(n) with a tiny constant, so the brute force and the reference differ in style rather than complexity.\n\n## Key insight\nFold the case once, then test five letters. The scan has no state beyond the counter.\n\n## Optimal\nOne pass, `count` incremented on each vowel. Time O(n), space O(1) (the string is passed by value here, so the call also copies it once).\n\n## C++ walkthrough\n`for (const char c : s)` is the range-for idiom; `const` documents that the loop does not modify the character. `tolower` lives in `<cctype>` and takes an `int` that must be representable as `unsigned char` (or `EOF`), hence the cast. An equally good alternative is `string("aeiouAEIOU").find(c) != string::npos`.\n\n## Common bugs\nForgetting capitals; counting `y`; using `s.length() - 1` as the bound and skipping the last character; calling `tolower` on a possibly negative `char`.\n\n## Follow-ups\nReturn the count of each vowel (`array<int, 5>`). Reverse only the vowels in place (two pointers). Count vowel substrings.\n\n## Similar problems\nReverse Vowels of a String (LeetCode 345).\n',reference:"class Solution {\npublic:\n    int countVowels(string s) {\n        int count = 0;\n        for (const char c : s) {\n            const char lower = static_cast<char>(tolower(static_cast<unsigned char>(c)));\n            if (lower == 'a' || lower == 'e' || lower == 'i' || lower == 'o' || lower == 'u') ++count;\n        }\n        return count;\n    }\n};\n",hints:"## Nudge\nA string is a sequence of `char`s you can loop over. How do you decide whether one `char` is a vowel?\n\n## Approach\nNormalise the case first (`tolower`), then compare against the five vowels. Count the hits in an `int`.\n\n## Key insight\nLower-casing each character once means you only write five comparisons instead of ten. Cast to `unsigned char` before calling `tolower` so the call is well defined for every character value.\n",loadTests:async()=>(await e.A(23251)).default},"wrap-dial":{meta:{id:"wrap-dial",region:"R0",title:"Wrap Dial",difficulty:"E",patterns:["syntax"],signals:["write this function","wrap around a circle","negative modulo"],prerequisites:[],parSeconds:240,complexity:{time:"O(1)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.25,edge:.45,adversarial:.3,perf:0},similar:[{name:"Circular Array Loop",lcNumber:457}],spec:{kind:"function",name:"wrapSlot",returns:"int",params:[{type:"int",name:"pos"},{type:"int",name:"m"}]}},statement:"# Wrap Dial\n\nA ship's dial has `m` slots numbered `0` to `m - 1` around a ring. Turning the dial moves a pointer by any number of slots, forwards (positive) or backwards (negative), and it wraps around the ring.\n\nThe pointer starts at slot `0`. After one turn of `pos` slots, return the slot it lands on, always in the range `0` to `m - 1`.\n\n## Examples\n\n- `pos = 7, m = 5` gives `2`.\n- `pos = -1, m = 5` gives `4` (one step back from slot 0 wraps to the last slot).\n- `pos = -10, m = 5` gives `0`.\n\n## Constraints\n\n- `-1000000000 <= pos <= 1000000000`\n- `1 <= m <= 100000`\n",editorial:'## Signals\nA pointer moving around a ring with forward and backward turns is modular arithmetic. Any time a statement says "wrap around" or asks for an index "in range", expect the negative-modulo trap.\n\n## Brute force\nMove the pointer one slot at a time, wrapping at both ends. Correct, but O(|pos|) steps, which is up to 10^9 for the stated range, so it is only a reference for small values.\n\n## Key insight\nTurning `pos` slots lands on `pos mod m`. Mathematically that is a value in `[0, m)`, but C++ `%` truncates toward zero, so `-1 % 5` is `-1`, not `4`.\n\n## Optimal\nCompute `r = pos % m`, which lies in `(-m, m)`, then add `m` if `r` is negative. Time O(1), space O(1).\n\n## C++ walkthrough\nSince `|r| < m <= 10^5`, `r + m` cannot overflow `int`. The one-line form `(pos % m + m) % m` also works for the same reason; the branch form says what is happening. Avoid `abs(pos)` because it mirrors the direction and `abs(INT_MIN)` is undefined behaviour.\n\n## Common bugs\nReturning the raw `%` for negative `pos`; applying `abs` first (turns -1 into 1); computing `pos + m` before the remainder, which overflows near 2 * 10^9 in other variants of this problem.\n\n## Follow-ups\nMake the pointer start at an arbitrary slot. Handle `m` up to 2^31 - 1 with `long long` intermediates. Implement floor division with the same repair.\n\n## Similar problems\nCircular Array Loop (LeetCode 457) uses the same wrap-an-index trick.\n',reference:"class Solution {\npublic:\n    int wrapSlot(int pos, int m) {\n        const int r = pos % m;        // in (-m, m): C++ keeps the sign of pos\n        return r < 0 ? r + m : r;     // shift negatives into [0, m)\n    }\n};\n",hints:"## Nudge\nTry `-1 % 5` on paper the way C++ computes it. Is the answer a valid slot?\n\n## Approach\nIn C++ the result of `%` has the same sign as the left operand, so it lands in `(-m, m)`. You only need to repair the negative case.\n\n## Key insight\n`((pos % m) + m) % m` or an `if (r < 0) r += m` always lands in `[0, m)`. The remainder is below `m` in size, so adding `m` cannot overflow `int` here.\n",loadTests:async()=>(await e.A(48418)).default},"badge-chain":{meta:{id:"badge-chain",region:"R2",title:"Badge Chain",difficulty:"M",patterns:["hash-lookup"],signals:["longest run of consecutive values","O(n) required","order does not matter"],prerequisites:["matching-pairs"],parSeconds:900,complexity:{time:"O(n)",space:"O(n)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.25,perf:.35},similar:[{name:"Longest Consecutive Sequence",lcNumber:128}],spec:{kind:"function",name:"longestChain",returns:"int",params:[{type:"vector<int>",name:"badges"}]}},statement:"# Badge Chain\n\nA guild hands out numbered badges, and a member may hold the same number more than once. A **chain** is a set of badge numbers that are consecutive integers, such as `4, 5, 6, 7`.\n\nGiven the list `badges` in any order, return the length of the longest chain you can form using the numbers that appear in the list. A number counts once however many copies exist.\n\nYour solution must run in linear time on average.\n\n## Examples\n\n- `badges = [100, 4, 200, 1, 3, 2]` gives `4` (the chain `1, 2, 3, 4`).\n- `badges = [5, 5, 5]` gives `1`.\n- `badges = [9, 1, 8, 2, 7]` gives `3` (the chain `7, 8, 9`).\n\n## Constraints\n\n- `0 <= badges.size() <= 100000`\n- `-1000000000 <= badges[i] <= 1000000000`\n",editorial:'## Signals\n"Longest run of consecutive values" with an O(n) requirement: sorting is the obvious route, but the order is irrelevant, so a hash set answers "is `x + 1` present?" directly.\n\n## Brute force\nSort, remove duplicates and scan for the longest run. O(n log n) time, O(1) extra space. It is correct, but the statement asks for linear time. A cruder version starts a walk from every number and re-walks long chains: O(n^2).\n\n## Key insight\nA chain has exactly one beginning: the number whose predecessor is missing. If you only start walks there, every element is visited by at most one walk.\n\n## Optimal\nInsert every number into an `unordered_set`. For each number `x` with `x - 1` absent, count `x, x + 1, ...` while present and keep the maximum. Invariant: each chain is walked once, from its smallest member, so total work is the set size plus the sum of chain lengths, which is O(n). Time O(n) expected, space O(n).\n\n## C++ walkthrough\nBuilding the set from iterators collapses duplicates for free. Iterating over the set (not the vector) avoids re-checking duplicate values. `start + length` never overflows `int` here because values stay within 10^9 and chain lengths within 10^5.\n\n## Common bugs\nStarting a walk at every element (quadratic); letting duplicates reset a sorted-scan run; assuming `max - min + 1` is the answer.\n\n## Follow-ups\nReturn the chain itself. Do it with union-find (merge `x` with `x - 1` and `x + 1`). What if numbers arrive in a stream and you must report the longest chain after each insert?\n\n## Similar problems\nLongest Consecutive Sequence (LeetCode 128) is this problem.\n',reference:"class Solution {\npublic:\n    int longestChain(vector<int> badges) {\n        const unordered_set<int> present(badges.begin(), badges.end());  // duplicates collapse\n        int best = 0;\n        for (const int start : present) {\n            if (present.count(start - 1)) continue;  // not the beginning of a chain\n            int length = 1;\n            while (present.count(start + length)) ++length;\n            best = max(best, length);\n        }\n        return best;\n    }\n};\n",hints:'## Nudge\nSorting finds the chain easily but costs n log n. What if you could ask "is `x + 1` in the list?" in O(1) instead?\n\n## Approach\nPut all numbers in a hash set. Only start counting at a number whose predecessor `x - 1` is **not** in the set, then walk upward while `x + 1, x + 2, ...` are present.\n\n## Key insight\nStarting only at chain beginnings means every number is walked over at most once in total, so the loop is linear even though it looks nested.\n',loadTests:async()=>(await e.A(23356)).default},"echo-gate":{meta:{id:"echo-gate",region:"R2",title:"Echo Gate",difficulty:"E",patterns:["hash-lookup"],signals:["seen before","same value again","within distance k"],prerequisites:[],parSeconds:480,complexity:{time:"O(n)",space:"O(n)"},timeLimitMs:1e3,testWeights:{basic:.25,edge:.25,adversarial:.2,perf:.3},similar:[{name:"Contains Duplicate II",lcNumber:219}],spec:{kind:"function",name:"hasEcho",returns:"bool",params:[{type:"vector<int>",name:"pings"},{type:"int",name:"k"}]}},statement:"# Echo Gate\n\nA gate records the id of every visitor in order, as `pings`. The gate raises an alarm if the **same id appears twice within `k` steps**: two positions `i < j` with `pings[i] == pings[j]` and `j - i <= k`.\n\nReturn `true` if the alarm would ring, otherwise `false`.\n\n## Examples\n\n- `pings = [4, 9, 4]`, `k = 2` gives `true`.\n- `pings = [4, 9, 4]`, `k = 1` gives `false`.\n- `pings = [1, 2, 3]`, `k = 5` gives `false`.\n\n## Constraints\n\n- `0 <= pings.size() <= 100000`\n- `-1000000000 <= pings[i] <= 1000000000`\n- `1 <= k <= 100000`\n",editorial:'## Signals\n"The same value again" combined with a distance limit is a hash lookup that remembers positions, not just membership.\n\n## Brute force\nFor each position compare against the next `k` positions. O(n * k) time, O(1) space; with n and k near 100000 that is billions of comparisons.\n\n## Key insight\nAmong all earlier copies of an id, only the **most recent** one can satisfy the distance limit if any does. So one position per id is enough.\n\n## Optimal\nScan once with `lastSeen[id] = position`. At position `j`, if `id` is present and `j - lastSeen[id] <= k`, return `true`. Then store `j`. Invariant: `lastSeen` holds the latest position of every id in `0..j-1`. Time O(n) expected, space O(n).\n\n## C++ walkthrough\n`find` before assigning keeps the check separate from the update. Positions are `int` because n <= 100000. The values reach 10^9 so they fit `int` but sums never occur.\n\n## Common bugs\nUsing `<` instead of `<=` for the gap; keeping the first position instead of the last; forgetting the distance entirely and answering "any duplicate".\n\n## Follow-ups\nDo it with O(k) memory by evicting ids that have left the window (a sliding window set). Return the earliest alarm position. Allow a value tolerance (near-duplicates need ordered buckets).\n\n## Similar problems\nContains Duplicate (LeetCode 217) drops the distance limit; Contains Duplicate II (LeetCode 219) is this problem.\n',reference:"class Solution {\npublic:\n    bool hasEcho(vector<int> pings, int k) {\n        unordered_map<int, int> lastSeen;  // id -> most recent position\n        for (int j = 0; j < static_cast<int>(pings.size()); ++j) {\n            const auto it = lastSeen.find(pings[j]);\n            if (it != lastSeen.end() && j - it->second <= k) return true;\n            lastSeen[pings[j]] = j;  // newest copy is always the closest one\n        }\n        return false;\n    }\n};\n",hints:"## Nudge\nIf an id repeats, which earlier position is the best one to compare with: the first, or the most recent?\n\n## Approach\nKeep a hash map from id to the last position where it appeared. At each position, if the id is in the map and the gap is at most `k`, the alarm rings.\n\n## Key insight\nAlways overwrite the stored position with the newest one. The most recent earlier copy is the closest, so if it is too far away every older copy is too.\n",loadTests:async()=>(await e.A(33795)).default},"exact-stretches":{meta:s.f,statement:"# Exact Stretches\n\nYou are given a list of integers `nums`, which may include negatives and zeros, and a number `target`. Count how many **consecutive, non-empty stretches** of the list add up to exactly `target`. Stretches at different positions count separately even if they hold the same values.\n\n## Examples\n\n- `nums = [1, 2, 3]`, `target = 3` gives `2` (`[1, 2]` and `[3]`).\n- `nums = [1, -1, 1, -1]`, `target = 0` gives `4`.\n- `nums = [0, 0, 0]`, `target = 0` gives `6`.\n\n## Constraints\n\n- `0 <= nums.size() <= 100000`\n- `-1000 <= nums[i] <= 1000`\n- `-1000000000 <= target <= 1000000000`\n\nThe count can exceed the range of a 32-bit integer (an array of zeros with target 0 has about 5 * 10^9 stretches). Aim for O(n) time.\n",editorial:'## Signals\n"Count the contiguous stretches with a given sum" and the values may be negative. Because adding an element can decrease the sum, the window cannot be moved monotonically, which rules out two pointers. Prefix sums plus a hash map is the standard answer.\n\n## Brute force\nFix the left end, extend the right end while accumulating, and count hits. O(n^2) time, O(1) space; about 5 * 10^9 steps at n = 100000, which times out.\n\n## Key insight\nWith `prefix[k]` the sum of the first `k` numbers, stretch `(i, j]` sums to `target` iff `prefix[i] = prefix[j] - target`. So for each `j`, the number of valid left ends is the number of earlier prefixes with that value. Counting them needs the multiplicity, not just presence: several earlier prefixes can share a total.\n\n## Optimal\nScan once, maintaining a map `seen` from prefix value to its count, initialised with `seen[0] = 1` (the empty prefix, which represents stretches starting at index 0). For each element: update `prefix`, add `seen[prefix - target]` to the answer, then increment `seen[prefix]`. Order matters: look up before inserting the current prefix, because a stretch must be non-empty. Time O(n) expected, space O(n).\n\n## C++ walkthrough\n`unordered_map::operator[]` inserts a zero if the key is missing, so use `find` for lookups that should not create entries (or accept the extra entries but know they exist). The answer can reach about 5 * 10^9, so both the map\'s value type and the counter should be 64-bit. The prefix itself is at most 10^8 in magnitude here but `prefix - target` can reach 1.1 * 10^9; keeping everything `long long` avoids reasoning about it.\n\n## Common bugs\nForgetting the `{0: 1}` seed (misses stretches that begin at index 0); inserting the current prefix before the lookup (counts empty stretches when `target = 0`); using a set instead of counts; `int` for the answer; sliding window on arrays with negatives.\n\n## Follow-ups\nReturn the longest such stretch (store first index instead of count). Make it work for a 2-D grid. What changes if the values are all positive? (Two pointers in O(1) space.) Count stretches whose sum is divisible by `k`.\n\n## Similar problems\nSubarray Sum Equals K (LeetCode 560).\n',reference:"class Solution {\npublic:\n    long long countStretches(vector<int> nums, long long target) {\n        // seen[p] = how many prefixes so far (including the empty one) have total p.\n        unordered_map<long long, long long> seen;\n        seen[0] = 1;\n        long long prefix = 0, count = 0;\n        for (const int x : nums) {\n            prefix += x;\n            // A stretch ending here sums to target iff an earlier prefix equals prefix - target.\n            const auto it = seen.find(prefix - target);\n            if (it != seen.end()) count += it->second;\n            ++seen[prefix];\n        }\n        return count;\n    }\n};\n",hints:'## Nudge\nNegative numbers break the usual "grow and shrink a window" idea. Think in terms of running totals instead: when does a stretch from `i` to `j` sum to `target`?\n\n## Approach\nLet `prefix[j]` be the total of the first `j` numbers. A stretch `(i, j]` sums to `target` exactly when `prefix[j] - prefix[i] == target`. While scanning, you need to know how many earlier prefixes equal `prefix[j] - target`.\n\n## Key insight\nKeep a hash map from prefix total to how many times it has occurred, seeded with `{0: 1}` for the empty prefix. At each step add `seen[prefix - target]` to the answer, then record the current prefix. Use `long long` for the prefix and the count.\n',loadTests:async()=>(await e.A(90091)).default},"ferry-pairs":{meta:{id:"ferry-pairs",region:"R2",title:"Ferry Pairs",difficulty:"M",patterns:["two-pointers"],signals:["at most two per group","weight limit","pair the heaviest with the lightest"],prerequisites:["mirror-check"],parSeconds:900,complexity:{time:"O(n log n)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.25,perf:.35},similar:[{name:"Boats to Save People",lcNumber:881}],spec:{kind:"function",name:"minFerries",returns:"int",params:[{type:"vector<int>",name:"weights"},{type:"int",name:"limit"}]}},statement:"# Ferry Pairs\n\nA ferry carries **at most two riders** at a time, and the combined weight of its riders must not exceed `limit`. Every rider weighs at most `limit`, so each can always ride alone.\n\nGiven the rider `weights`, return the fewest ferry trips needed to carry everyone once.\n\n## Examples\n\n- `weights = [1, 2], limit = 3` gives `1`.\n- `weights = [3, 2, 2, 1], limit = 3` gives `3` (pairs `1 + 2`, then `2` alone, then `3` alone).\n- `weights = [3, 5, 3, 4], limit = 5` gives `4`.\n\n## Constraints\n\n- `0 <= weights.size() <= 100000`\n- `1 <= weights[i] <= limit <= 1000000000`\n\nAim for O(n log n).\n",editorial:'## Signals\n"At most two per group" with a capacity limit: the pairing structure is the key, and sorted order gives a natural greedy for matching extremes.\n\n## Brute force\nRecursively decide, for the first unplaced rider, whether they ride alone or with each possible partner; take the minimum. Exponential, usable only for tiny inputs (it is the brute force in this package\'s tests).\n\n## Key insight\nExchange argument. Let `h` be the heaviest rider and `l` the lightest. If `h + l > limit`, then `h` fits with nobody, so `h` rides alone. Otherwise take any optimal plan in which `h` and `l` are on different trips: `h` rides with `y` (or alone) and `l` rides with `x` (or alone). Re-pair them as `(h, l)` and `(x, y)`. The first pair fits by assumption, and `x + y <= h + y <= limit` because `h` is the heaviest, so the trip count does not grow. The first case removes one rider, the second removes two; the same argument applies to the rest.\n\n## Optimal\nSort. `light = 0`, `heavy = n - 1`. While `light <= heavy`: if `light < heavy` and `weights[light] + weights[heavy] <= limit`, advance `light`; always decrement `heavy` and add one trip. Invariant: riders outside `[light, heavy]` are already carried in the counted trips. Time O(n log n) for the sort plus O(n) for the sweep; space O(1) extra.\n\n## C++ walkthrough\nThe condition `light < heavy` stops the last rider being "paired with themselves" when both pointers meet. Two weights up to 10^9 sum to 2 x 10^9, which still fits in a 32-bit `int` (max about 2.147 x 10^9); if the constraint were larger, widen to `long long`.\n\n## Common bugs\nPairing only adjacent sorted riders; dropping the light rider when the pair does not fit; letting a trip hold three riders; forgetting the `light < heavy` guard so one rider is counted as a pair.\n\n## Follow-ups\nWhat if a boat holds at most k riders? (It becomes bin packing, which is NP-hard in general.) What if riders arrive online? Return the actual pairing.\n\n## Similar problems\nBoats to Save People (LeetCode 881).\n',reference:"class Solution {\npublic:\n    int minFerries(vector<int> weights, int limit) {\n        sort(weights.begin(), weights.end());\n        int light = 0, heavy = static_cast<int>(weights.size()) - 1;\n        int ferries = 0;\n        while (light <= heavy) {\n            // The heaviest remaining rider leaves now; the lightest joins if (and only if) they fit together.\n            if (light < heavy && weights[light] + weights[heavy] <= limit) ++light;\n            --heavy;\n            ++ferries;\n        }\n        return ferries;\n    }\n};\n",hints:"## Nudge\nThink about the heaviest rider. Who is the best possible companion for them, if they have one at all?\n\n## Approach\nSort the weights. Keep a pointer at the lightest and one at the heaviest rider. Every trip takes the heaviest; the lightest joins if the two fit within the limit. Count trips until the pointers cross.\n\n## Key insight\nIf the heaviest rider cannot share with the lightest, they cannot share with anybody, so they ride alone. If they can, pairing them with the lightest wastes nothing a heavier partner would have used better.\n",loadTests:async()=>(await e.A(56906)).default},"hot-streak":{meta:{id:"hot-streak",region:"R2",title:"Hot Streak",difficulty:"M",patterns:["kadane"],signals:["best contiguous stretch","maximum sum ending here","negatives allowed, must pick at least one"],prerequisites:["range-ledger"],parSeconds:600,complexity:{time:"O(n)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.25,adversarial:.2,perf:.35},similar:[{name:"Maximum Subarray",lcNumber:53}],spec:{kind:"function",name:"bestStretch",returns:"long long",params:[{type:"vector<int>",name:"gains"}]}},statement:"# Hot Streak\n\nA trader logs the profit or loss of each day in `gains`. Positive numbers are profit, negative numbers are loss. Pick a run of **consecutive** days (at least one day) so that the total over that run is as large as possible.\n\nReturn that largest total. You must pick at least one day, so if every day is a loss the answer is the least bad single day.\n\n## Examples\n\n- `gains = [2, -5, 3, 4, -1, 6, -8]` gives `12` (days 2 to 5: `3 + 4 - 1 + 6`).\n- `gains = [-4, -2, -9]` gives `-2`.\n- `gains = [5]` gives `5`.\n\n## Constraints\n\n- `1 <= gains.size() <= 100000`\n- `-1000000000 <= gains[i] <= 1000000000`\n\nThe total can exceed the range of a 32-bit integer. Aim for O(n) time.\n",editorial:'## Signals\n"Best contiguous stretch" with negative numbers allowed and at least one element required. A running best-ending-here quantity is the signature of Kadane\'s algorithm, a one-dimensional DP in disguise.\n\n## Brute force\nTry every pair of endpoints, accumulating the sum as the right end grows: O(n^2) time, O(1) space. About 5 * 10^9 additions at n = 100000, which times out.\n\n## Key insight\nLet `E[i]` be the best total of a stretch ending at day `i`. A stretch ending at `i` is either day `i` alone or a stretch ending at `i - 1` plus day `i`, so `E[i] = max(g[i], E[i-1] + g[i])`. The answer is `max E[i]`. If `E[i-1]` is negative, carrying it only hurts, so it is dropped.\n\n## Optimal\nOne pass keeping two numbers, `endingHere` and `best`. Time O(n), space O(1). The recurrence only looks one step back, so the DP array collapses into a single variable.\n\n## C++ walkthrough\nTotals reach 10^5 x 10^9 = 10^14, so use `long long` for both variables. `max(gains[i], endingHere + gains[i])` mixes `int` and `long long`, which does not deduce for `std::max`: write `max<long long>(...)` or cast. Seed with `gains[0]` and loop from 1.\n\n## Common bugs\nSeeding `best` with 0 (returns 0 instead of a negative answer for all-loss input); `int` accumulators; resetting at `sum < 0` before recording `best`; looping from 0 after seeding with `gains[0]` (double counts day 0, which is harmless for the answer but shows the invariant is unclear).\n\n## Follow-ups\nReturn the start and end indices. Maximum product subarray (track both max and min). Maximum sum when the array is circular (see Ring Gain). Largest sum with at most one deleted element.\n\n## Similar problems\nMaximum Subarray (LeetCode 53).\n',reference:"class Solution {\npublic:\n    long long bestStretch(vector<int> gains) {\n        // endingHere = best total of a stretch that must finish at the current day.\n        long long endingHere = gains[0];\n        long long best = gains[0];\n        for (size_t i = 1; i < gains.size(); ++i) {\n            // Extend the previous stretch only if it helps; otherwise restart at today.\n            endingHere = max<long long>(gains[i], endingHere + gains[i]);\n            best = max(best, endingHere);\n        }\n        return best;\n    }\n};\n",hints:"## Nudge\nTrying every start and end is O(n^2). Instead ask: for each day, what is the best stretch that **ends** exactly on that day?\n\n## Approach\nKeep `endingHere`. On day `i` you either extend yesterday's best stretch or start fresh at day `i`. Track the maximum `endingHere` ever seen.\n\n## Key insight\nExtending is only worth it if the previous stretch's total is positive: `endingHere = max(gains[i], endingHere + gains[i])`. Initialise from `gains[0]`, not 0, so an all-loss input returns the least bad day.\n",loadTests:async()=>(await e.A(2505)).default},"matching-pairs":{meta:{id:"matching-pairs",region:"R2",title:"Matching Pairs",difficulty:"E",patterns:["hash-lookup"],signals:["pair summing to a target","seen before","count frequency"],prerequisites:[],parSeconds:480,complexity:{time:"O(n)",space:"O(n)"},timeLimitMs:1e3,testWeights:{basic:.25,edge:.25,adversarial:.2,perf:.3},similar:[{name:"Two Sum",lcNumber:1}],spec:{kind:"function",name:"countMatches",returns:"long long",params:[{type:"vector<int>",name:"nums"},{type:"int",name:"target"}]}},statement:"# Matching Pairs\n\nA merchant stamps each coin with an integer value and keeps them in a row, `nums`. Two coins **match** when their values add up to `target`.\n\nCount the pairs of positions `i < j` with `nums[i] + nums[j] == target`. Two coins with equal values still count as two different coins.\n\n## Examples\n\n- `nums = [1, 4, 2, 3]`, `target = 5` gives `2` (positions `0,1` and `2,3`).\n- `nums = [2, 2, 2]`, `target = 4` gives `3`.\n- `nums = [7]`, `target = 7` gives `0`.\n\n## Constraints\n\n- `0 <= nums.size() <= 100000`\n- `-1000000 <= nums[i] <= 1000000`\n- `-2000000 <= target <= 2000000`\n",editorial:'## Signals\n"Pair that adds up to a target" plus "have I seen the partner before?" is a hash lookup: the partner of `x` is fully determined, `target - x`.\n\n## Brute force\nCheck every pair `i < j`. O(n^2) time, O(1) space; with n = 100000 that is about 5 billion checks.\n\n## Key insight\nFor a fixed right coin the left partner\'s value is forced, so only its **frequency among earlier coins** matters. Counting by value turns the inner loop into one lookup.\n\n## Optimal\nScan left to right with `seen[value] = count so far`. For each `x` add `seen[target - x]` to the answer, then increment `seen[x]`. Invariant: before processing coin `j`, `seen` describes exactly coins `0..j-1`, so each pair is counted once, at its right coin. Time O(n) expected, space O(n) for the map. The answer is a `long long` because n(n-1)/2 is about 5 * 10^9.\n\n## C++ walkthrough\n`unordered_map<int,int>` default-initialises missing counts to 0 on `operator[]`, but `find` avoids inserting keys we only query. `const auto it` keeps the lookup cheap and read-only.\n\n## Common bugs\nInserting before looking up (a coin pairs with itself when `2x == target`); using `int` for the answer; counting distinct partners instead of how many earlier coins hold the partner value.\n\n## Follow-ups\nReturn the pair of positions when exactly one pair exists (store the index instead of a count). If the array is sorted, two pointers use O(1) space. Counting triples is 3Sum territory.\n\n## Similar problems\nTwo Sum (LeetCode 1) asks for the positions instead of the count; Two Sum II (LeetCode 167) is the sorted version.\n',reference:"class Solution {\npublic:\n    long long countMatches(vector<int> nums, int target) {\n        unordered_map<int, int> seen;  // value -> how many earlier coins carry it\n        long long pairs = 0;\n        for (const int x : nums) {\n            const auto it = seen.find(target - x);\n            if (it != seen.end()) pairs += it->second;  // look up before inserting: no self-pairing\n            ++seen[x];\n        }\n        return pairs;\n    }\n};\n",hints:'## Nudge\nWhen you stand on coin `j`, which single value would complete a match with an earlier coin? Can you ask "how many earlier coins have that value?" in O(1)?\n\n## Approach\nKeep a hash map from value to how many times it has appeared so far. For each coin, add the count of `target - value` to the answer, then record the coin.\n\n## Key insight\nLook up before you insert, so a coin never pairs with itself. The answer can reach about 5 billion (all values equal), so accumulate in `long long`.\n',loadTests:async()=>(await e.A(81262)).default},"mirror-check":{meta:{id:"mirror-check",region:"R2",title:"Mirror Check",difficulty:"E",patterns:["two-pointers"],signals:["read from both ends","palindrome","skip characters that do not count"],prerequisites:["scramble-check"],parSeconds:420,complexity:{time:"O(n)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.25,edge:.25,adversarial:.2,perf:.3},similar:[{name:"Valid Palindrome",lcNumber:125}],spec:{kind:"function",name:"isMirror",returns:"bool",params:[{type:"string",name:"line"}]}},statement:'# Mirror Check\n\nA lighthouse keeper scratches messages onto stones and claims some of them read the same from both ends. Letters and digits are the only characters that count; spaces and punctuation are decoration, and capital letters match their lowercase twins.\n\nGiven `line`, return `true` if the characters that count, read left to right, spell the same thing as when read right to left. An empty message, or one with nothing that counts, is a mirror.\n\n## Examples\n\n- `line = "A man a plan a canal Panama"` gives `true`.\n- `line = "race a car"` gives `false`.\n- `line = " ,. "` gives `true`.\n\n## Constraints\n\n- `0 <= line.size() <= 100000`\n- `line` contains only letters, digits, spaces and the characters `, . :`\n\nAim for O(n) time and O(1) extra space.\n',editorial:'## Signals\n"Reads the same from both ends" is a palindrome test. The decoration to ignore tells you not to compare raw positions: you need to skip characters while comparing outermost-first.\n\n## Brute force\nCopy only the letters and digits, lowercased, into a new string, reverse it and compare. O(n) time and O(n) extra space. It is correct; the interviewer will usually ask whether you can avoid the copy.\n\n## Key insight\nA palindrome is symmetric about its centre, so the outermost counting characters must match each other, then the next pair inward, and so on. Two indices walking toward each other visit exactly those pairs.\n\n## Optimal\nSet `left = 0`, `right = n - 1`. While `left < right`: if `line[left]` does not count, advance `left`; else if `line[right]` does not count, retreat `right`; else compare them case-insensitively, return `false` on a mismatch and move both inward. Invariant: every counting character outside `[left, right]` has been matched with its mirror. Each step moves an index, so time is O(n) and extra space O(1).\n\n## C++ walkthrough\n`isalnum` and `tolower` take an `int` that must be representable as `unsigned char` (or `EOF`), so cast the `char` first: `static_cast<unsigned char>(c)`. Passing a negative `char` is undefined behaviour. Taking `line` by value is fine here; use `const string&` when you do not need a copy.\n\n## Common bugs\nComparing spaces and punctuation; forgetting case folding; skipping only one end; using `left <= right` (harmless, but a sign you did not reason about the middle character); passing `char` straight to `isalnum`.\n\n## Follow-ups\nAllow deleting at most one character (Valid Palindrome II). Find the longest palindromic substring (expand around centres). Do it on a linked list.\n\n## Similar problems\nValid Palindrome (LeetCode 125).\n',reference:"class Solution {\npublic:\n    bool isMirror(string line) {\n        int left = 0, right = static_cast<int>(line.size()) - 1;\n        while (left < right) {\n            // Invariant: everything outside [left, right] has already matched.\n            if (!isalnum(static_cast<unsigned char>(line[left]))) { ++left; continue; }\n            if (!isalnum(static_cast<unsigned char>(line[right]))) { --right; continue; }\n            if (tolower(static_cast<unsigned char>(line[left])) != tolower(static_cast<unsigned char>(line[right]))) return false;\n            ++left;\n            --right;\n        }\n        return true;\n    }\n};\n",hints:"## Nudge\nBuilding a cleaned copy and reversing it works, but it costs extra memory. Can you compare the original string with two fingers instead?\n\n## Approach\nPut one index at the start and one at the end. Move each inward past characters that do not count, then compare the two that do (ignoring case). Stop when the indices meet.\n\n## Key insight\nThe pair of characters you compare are always the next-outermost ones that count, so a mismatch anywhere means the answer is `false`, and meeting in the middle means every pair matched.\n",loadTests:async()=>(await e.A(93211)).default},"range-ledger":{meta:{id:"range-ledger",region:"R2",title:"Range Ledger",difficulty:"E",patterns:["prefix-sum"],signals:["many range-sum queries","array never changes between queries","sum of a stretch"],prerequisites:["matching-pairs"],parSeconds:420,complexity:{time:"O(n + q)",space:"O(n)"},timeLimitMs:1e3,testWeights:{basic:.25,edge:.2,adversarial:.2,perf:.35},similar:[{name:"Range Sum Query - Immutable",lcNumber:303}],spec:{kind:"function",name:"stretchTotals",returns:"vector<long long>",params:[{type:"vector<int>",name:"coins"},{type:"vector<vector<int>>",name:"queries"}]}},statement:'# Range Ledger\n\nA harbour clerk records the coin value of each crate along a quay: `coins[i]` is the value of crate `i`. Auditors then ask many questions of the form "what is the total value of the crates from position `l` to position `r`, both ends included?"\n\nGiven `coins` and a list of `queries`, where each query is a pair `[l, r]`, return the answers in order as a list of totals.\n\n## Examples\n\n- `coins = [3, -1, 4, 1, 5]`, `queries = [[0, 4], [1, 2], [3, 3]]` gives `[12, 3, 1]`.\n- `coins = [7]`, `queries = [[0, 0]]` gives `[7]`.\n- `coins = [2, 2, 2]`, `queries = []` gives `[]`.\n\n## Constraints\n\n- `1 <= coins.size() <= 100000`\n- `-1000000000 <= coins[i] <= 1000000000`\n- `0 <= queries.size() <= 100000`\n- `0 <= l <= r < coins.size()` for every query\n\nA single total can exceed the range of a 32-bit integer. Aim for O(n + q) time overall.\n',editorial:'## Signals\nMany queries over a static array, each asking for the sum of a contiguous stretch. "Static" is the key word: nothing is updated between questions, so precomputation pays off.\n\n## Brute force\nFor each query, add up `coins[l..r]`. O(n) per query, O(n * q) overall: 10^10 additions at the limits, which times out.\n\n## Key insight\nA range sum is a difference of two running totals: `sum(l..r) = prefix[r + 1] - prefix[l]`. The prefix array turns "add up a stretch" into "subtract two numbers".\n\n## Optimal\nBuild `prefix` in one pass (`prefix[i + 1] = prefix[i] + coins[i]`), then answer each query in O(1). Time O(n + q), space O(n) for the prefix array (the output is separate). The invariant: `prefix[i]` equals the total of `coins[0..i-1]`, and `prefix[0] = 0` is the empty total.\n\n## C++ walkthrough\nEach coin is up to 10^9 in magnitude and there can be 10^5 of them, so totals reach 10^14: both the prefix array and the output must be `long long`. Declaring `prefix` as `vector<int>` compiles and passes small tests, then overflows silently. Iterate queries with `const auto& q` to avoid copying each pair.\n\n## Common bugs\nUsing a prefix array of length `n` and mishandling `l = 0`; using `prefix[r] - prefix[l]` (drops `coins[r]`); `prefix[r + 1] - prefix[l + 1]` (drops `coins[l]`); an `int` prefix array.\n\n## Follow-ups\nWhat if single values can be updated between queries? (Fenwick tree, later in the game.) How would you answer range sums on a 2-D grid? Count subarrays whose sum equals `k` (that is Exact Stretches).\n\n## Similar problems\nRange Sum Query - Immutable (LeetCode 303).\n',reference:"class Solution {\npublic:\n    vector<long long> stretchTotals(vector<int> coins, vector<vector<int>> queries) {\n        // prefix[i] = total of coins[0..i-1], so a stretch [l, r] is prefix[r + 1] - prefix[l].\n        vector<long long> prefix(coins.size() + 1, 0);\n        for (size_t i = 0; i < coins.size(); ++i) prefix[i + 1] = prefix[i] + coins[i];\n        vector<long long> answers;\n        answers.reserve(queries.size());\n        for (const auto& q : queries) answers.push_back(prefix[q[1] + 1] - prefix[q[0]]);\n        return answers;\n    }\n};\n",hints:"## Nudge\nRe-adding the same crates for every question repeats work. What could you compute once, before any question arrives, so that each question becomes a couple of lookups?\n\n## Approach\nBuild `prefix` where `prefix[i]` is the total of the first `i` crates. The total of crates `l..r` is the running total up to `r` minus the running total before `l`.\n\n## Key insight\nUse a prefix array of length `n + 1` with `prefix[0] = 0`; then the answer is exactly `prefix[r + 1] - prefix[l]` with no special case for `l = 0`. Store it as `long long`.\n",loadTests:async()=>(await e.A(61493)).default},"ring-gain":{meta:{id:"ring-gain",region:"R2",title:"Ring Gain",difficulty:"M",patterns:["kadane","prefix-sum"],signals:["best contiguous stretch on a circle","may wrap around the end","total minus the worst stretch"],prerequisites:["hot-streak"],parSeconds:900,complexity:{time:"O(n)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.25,adversarial:.2,perf:.35},similar:[{name:"Maximum Sum Circular Subarray",lcNumber:918}],spec:{kind:"function",name:"bestRingStretch",returns:"long long",params:[{type:"vector<int>",name:"gains"}]}},statement:"# Ring Gain\n\nStalls stand around a circular plaza, and `gains[i]` is the profit (or loss) of stall `i`. After the last stall comes the first one again. Choose a run of **consecutive** stalls, at least one and at most all of them, that is allowed to wrap from the end of the list back to the start, so that the total is as large as possible. Each stall may be used at most once.\n\nReturn that largest total.\n\n## Examples\n\n- `gains = [5, -3, 5]` gives `10` (stall 2, then wrapping to stall 0).\n- `gains = [1, -2, 3, -2]` gives `3`.\n- `gains = [-3, -2, -3]` gives `-2`.\n\n## Constraints\n\n- `1 <= gains.size() <= 100000`\n- `-1000000000 <= gains[i] <= 1000000000`\n\nThe total can exceed the range of a 32-bit integer. Aim for O(n) time.\n",editorial:'## Signals\nA circular array and "best contiguous stretch". The new twist over Hot Streak is that the stretch may wrap, so the stretch is either an ordinary interval or the complement of an ordinary interval.\n\n## Brute force\nStart at each stall and extend around the ring up to `n` stalls, tracking the best total: O(n^2) time, O(1) space, about 5 * 10^9 steps at the limit, which times out.\n\n## Key insight\nCase 1: the chosen run does not wrap; this is ordinary Kadane. Case 2: it wraps, so the stalls left out form one contiguous block strictly inside the array; the run\'s total is `total - (that block)`, which is largest when the block\'s sum is smallest. So case 2 is `total - (minimum subarray sum)`, computed by Kadane with min instead of max. Edge: if the minimum block is the entire array (every value negative) case 2 would choose an empty run, so the answer falls back to case 1.\n\n## Optimal\nOne pass maintaining `total`, the max Kadane pair and the min Kadane pair. Time O(n), space O(1). The case split gives `max(maxBest, total - minBest)`, guarded by `maxBest < 0`: if the best plain stretch is negative, all values are negative and the least bad single stall is the answer.\n\n## C++ walkthrough\nAll accumulators are `long long` (totals reach 10^14). `max(g, maxEnd + g)` needs both arguments of the same type, hence `const long long g`. Initialise from `gains[0]` and loop from index 1 so single-element input works. The guard `maxBest < 0` is equivalent to "all values negative" and avoids a separate scan.\n\n## Common bugs\nIgnoring the wrap case; the all-negative empty-run trap; `int` accumulators; computing the minimum with the maximum\'s code and a sign slip; trying to double the array and running a window (works but needs care to cap the length at `n`).\n\n## Follow-ups\nReturn the start and length of the best run. Solve it with prefix sums and a monotonic deque over the doubled array (length at most `n`). What if the run must contain at least two stalls?\n\n## Similar problems\nMaximum Sum Circular Subarray (LeetCode 918).\n',reference:'class Solution {\npublic:\n    long long bestRingStretch(vector<int> gains) {\n        // Either the best stretch does not wrap (plain Kadane), or it wraps and equals\n        // total minus the worst non-wrapping stretch in the middle.\n        long long total = gains[0];\n        long long maxEnd = gains[0], maxBest = gains[0];\n        long long minEnd = gains[0], minBest = gains[0];\n        for (size_t i = 1; i < gains.size(); ++i) {\n            const long long g = gains[i];\n            total += g;\n            maxEnd = max(g, maxEnd + g);\n            maxBest = max(maxBest, maxEnd);\n            minEnd = min(g, minEnd + g);\n            minBest = min(minBest, minEnd);\n        }\n        // If every element is negative the "wrap" option would remove everything (empty stretch): not allowed.\n        if (maxBest < 0) return maxBest;\n        return max(maxBest, total - minBest);\n    }\n};\n',hints:'## Nudge\nIf you already know the best plain stretch (Hot Streak), what extra shape can a circular answer take? Picture the stalls you do **not** use.\n\n## Approach\nA wrapping stretch leaves out one contiguous block in the middle of the list. So the best wrapping total is the grand total minus the **smallest** contiguous block. Run Kadane for the maximum and a mirrored Kadane for the minimum, in the same pass.\n\n## Key insight\nAnswer = `max(maxStretch, total - minStretch)`. One trap: if every value is negative, `minStretch` is the whole array, `total - minStretch = 0` means "use nothing", which is not allowed; in that case return `maxStretch`.\n',loadTests:async()=>(await e.A(51219)).default},"scramble-check":{meta:{id:"scramble-check",region:"R2",title:"Scramble Check",difficulty:"E",patterns:["hash-lookup"],signals:["count frequency","same letters rearranged"],prerequisites:[],parSeconds:360,complexity:{time:"O(n)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.25,edge:.25,adversarial:.2,perf:.3},similar:[{name:"Valid Anagram",lcNumber:242}],spec:{kind:"function",name:"isScramble",returns:"bool",params:[{type:"string",name:"a"},{type:"string",name:"b"}]}},statement:'# Scramble Check\n\nTwo words are a **scramble** of each other if one can be rearranged into the other using every letter exactly once.\n\nGiven lowercase words `a` and `b`, return `true` if they are scrambles of each other.\n\n## Examples\n\n- `a = "listen"`, `b = "silent"` gives `true`.\n- `a = "aab"`, `b = "abb"` gives `false`.\n- `a = ""`, `b = ""` gives `true`.\n\n## Constraints\n\n- `0 <= a.length(), b.length() <= 100000`\n- Both words contain only `a` to `z`.\n',editorial:'## Signals\n"Same letters, any order" means order is irrelevant and only letter frequencies matter: count frequency.\n\n## Brute force\nSort both words and compare. O(n log n) time, O(1) extra space for an in-place sort. It is correct and fine for small inputs, but a count beats it.\n\n## Key insight\nTwo words are scrambles exactly when their frequency vectors are equal. With a 26-letter alphabet the frequency vector is a fixed-size array.\n\n## Optimal\nIf the lengths differ, return `false`. Otherwise add 1 for each letter of `a` and subtract 1 for each letter of `b` in a 26-slot array; the words are scrambles iff every slot is 0. Time O(n), space O(1) (26 counters, independent of n).\n\n## C++ walkthrough\nA plain `int balance[26]` is faster and simpler than a map, and `c - \'a\'` maps a lowercase letter to its slot. The explicit length check is what makes "all slots zero" sufficient.\n\n## Common bugs\nComparing letter sets (loses multiplicity); comparing sums of letter codes (collisions); checking only for negative slots without comparing lengths.\n\n## Follow-ups\nUnicode input: use `unordered_map<char32_t,int>`. Find all scrambles of a pattern inside a text: fixed-size sliding window with the same balance array.\n\n## Similar problems\nValid Anagram (LeetCode 242) is this problem; Group Anagrams (LeetCode 49) groups many words by this relation.\n',reference:"class Solution {\npublic:\n    bool isScramble(string a, string b) {\n        if (a.size() != b.size()) return false;\n        int balance[26] = {};  // letters of a minus letters of b\n        for (const char c : a) ++balance[c - 'a'];\n        for (const char c : b) --balance[c - 'a'];\n        for (const int v : balance)\n            if (v != 0) return false;\n        return true;\n    }\n};\n",hints:"## Nudge\nDoes the order of the letters matter, or only how many of each letter there are?\n\n## Approach\nCount the letters of `a` in 26 slots, subtract the letters of `b`, and check that every slot ends at zero.\n\n## Key insight\nDifferent lengths can never match, so check that first. With 26 fixed slots the memory does not depend on the input size.\n",loadTests:async()=>(await e.A(72618)).default},"scramble-clans":{meta:{id:"scramble-clans",region:"R2",title:"Scramble Clans",difficulty:"M",patterns:["hash-lookup"],signals:["group by","same letters rearranged","canonical form as key"],prerequisites:["scramble-check"],parSeconds:840,complexity:{time:"O(n * L log L)",space:"O(n * L)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.25,perf:.35},similar:[{name:"Group Anagrams",lcNumber:49}],spec:{kind:"function",name:"largestClan",returns:"int",params:[{type:"vector<string>",name:"words"}]}},statement:'# Scramble Clans\n\nA word-smith sorts a list of words into **clans**: two words belong to the same clan when one is a rearrangement of the other (every letter used exactly once). Equal words belong to the same clan.\n\nReturn the size of the largest clan in `words`, or `0` if the list is empty.\n\n## Examples\n\n- `words = ["tea", "eat", "tan", "ate", "nat", "bat"]` gives `3` (the clan `tea, eat, ate`).\n- `words = ["abc", "abd", "abe"]` gives `1`.\n- `words = ["aa", "aa", "aa"]` gives `3`.\n\n## Constraints\n\n- `0 <= words.size() <= 20000`\n- `1 <= words[i].length() <= 20`\n- Every word contains only `a` to `z`.\n',editorial:'## Signals\n"Group by" a relation where order inside the item does not matter. The way in is a **canonical form**: one key per equivalence class.\n\n## Brute force\nFor each word, compare it with every other word (sorting both). O(n^2 * L log L) time, O(L) space. With n = 20000 this is hundreds of millions of sorts.\n\n## Key insight\nSorting a word\'s letters gives a key that is identical for every rearrangement and distinct for different letter multisets. Grouping then needs a single hash lookup per word.\n\n## Optimal\nFor each word, sort a copy and increment its count in an `unordered_map<string,int>`; the answer is the largest count seen. Invariant: after processing a prefix of words, `clanSize[key]` is the clan size within that prefix, so the running maximum is the answer. Time O(n * L log L), with L <= 20 effectively O(n); space O(n * L) for the keys.\n\n## C++ walkthrough\n`for (string word : words)` copies on purpose, because we sort the copy and must not touch the input. `++clanSize[word]` inserts a zero count if absent and returns the new value, so the maximum update is one expression. For a tighter key, a 26-count array encoded as a string avoids the sort: O(n * L).\n\n## Common bugs\nUsing length or letter sum as the key (collisions); sorting the input in place and then comparing against the original; returning the number of clans instead of the size of the largest.\n\n## Follow-ups\nReturn the groups themselves, in input order. Use a 26-count key to drop the log factor. Huge words: hash the count vector rather than store it.\n\n## Similar problems\nGroup Anagrams (LeetCode 49) asks for the groups; this asks for the largest size. Valid Anagram (LeetCode 242) is the pairwise test.\n',reference:"class Solution {\npublic:\n    int largestClan(vector<string> words) {\n        unordered_map<string, int> clanSize;  // sorted letters -> words in the clan\n        int best = 0;\n        for (string word : words) {\n            sort(word.begin(), word.end());  // canonical key shared by every rearrangement\n            best = max(best, ++clanSize[word]);\n        }\n        return best;\n    }\n};\n",hints:"## Nudge\nComparing every pair of words is too slow. Is there one value, computed from a single word, that is identical for every word in its clan and different across clans?\n\n## Approach\nSort the letters of each word to get a canonical key. Count how many words share each key in a hash map and take the largest count.\n\n## Key insight\nThe sorted spelling is a **canonical form**: it is the same for all rearrangements and different otherwise. Sorting one short word is cheap, so the cost is n times a tiny sort, not n squared.\n",loadTests:async()=>(await e.A(36287)).default},"sprinkler-lanes":{meta:{id:"sprinkler-lanes",region:"R2",title:"Sprinkler Lanes",difficulty:"M",patterns:["prefix-sum"],signals:["many range updates","only the final array is needed","add v to every cell in [l, r]"],prerequisites:["range-ledger"],parSeconds:600,complexity:{time:"O(lanes + jobs)",space:"O(lanes)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.2,perf:.4},similar:[{name:"Corporate Flight Bookings",lcNumber:1109},{name:"Range Addition",lcNumber:370}],spec:{kind:"function",name:"finalLevels",returns:"vector<long long>",params:[{type:"int",name:"lanes"},{type:"vector<vector<int>>",name:"jobs"}]}},statement:"# Sprinkler Lanes\n\nA garden has `lanes` lanes numbered `0` to `lanes - 1`, all starting with water level `0`. A list of `jobs` follows; each job is `[l, r, v]`: every lane from `l` to `r` (both included) receives `v` more units of water. A value `v` may be negative, which drains the lanes.\n\nReturn the final water level of every lane, after all jobs have been applied.\n\n## Examples\n\n- `lanes = 5`, `jobs = [[1, 3, 2], [2, 4, 3]]` gives `[0, 2, 5, 5, 3]`.\n- `lanes = 3`, `jobs = [[0, 2, 7], [1, 1, -7]]` gives `[7, 0, 7]`.\n- `lanes = 4`, `jobs = []` gives `[0, 0, 0, 0]`.\n\n## Constraints\n\n- `1 <= lanes <= 100000`\n- `0 <= jobs.size() <= 100000`\n- `0 <= l <= r < lanes` and `-1000000000 <= v <= 1000000000` for each job\n\nFinal levels can exceed the range of a 32-bit integer. Aim for O(lanes + jobs) time.\n",editorial:'## Signals\nLots of "add a value to every cell in a range" updates, and the question is only about the array after all of them. When queries and updates are not interleaved, the difference array is the tool.\n\n## Brute force\nFor each job, loop from `l` to `r` and add `v`. O(lanes * jobs) = 10^10 in the worst case, which times out.\n\n## Key insight\nStore differences instead of values: `delta[i] = level[i] - level[i-1]`. A range add changes only two differences: `+v` at `l` (the level jumps up) and `-v` at `r + 1` (it jumps back). Recovering levels is a prefix sum over `delta`, which is the inverse of taking differences.\n\n## Optimal\nOne pass over jobs updating two cells each, then one prefix-sum pass. Time O(lanes + jobs), space O(lanes). The array has `lanes + 1` slots so that `r + 1` for the last lane is safe; the extra slot is never read as a level.\n\n## C++ walkthrough\nContributions stack: 10^5 jobs of 10^9 can put 10^14 in a single lane, so `delta`, the running total and the result must be `long long`. `vector<long long>(lanes + 1, 0)` value-initialises; forgetting the `+ 1` writes one past the end. Pass `jobs` by `const auto&` in the loop.\n\n## Common bugs\nCancelling at `r` instead of `r + 1`; forgetting to cancel at all; an off-by-one array size; `int` accumulation; trying to maintain levels directly and re-introducing the inner loop.\n\n## Follow-ups\nWhat if queries for single-lane levels arrive between jobs? (Fenwick tree with range update, point query.) Extend to a 2-D grid with rectangle updates. What if only the maximum final level is needed? (Sort the event points.)\n\n## Similar problems\nCorporate Flight Bookings (LeetCode 1109), Range Addition (LeetCode 370).\n',reference:"class Solution {\npublic:\n    vector<long long> finalLevels(int lanes, vector<vector<int>> jobs) {\n        // delta[i] = change in level between lane i-1 and lane i. A job adds v at l and takes it back after r.\n        vector<long long> delta(lanes + 1, 0);\n        for (const auto& job : jobs) {\n            delta[job[0]] += job[2];\n            delta[job[1] + 1] -= job[2];\n        }\n        vector<long long> level(lanes);\n        long long running = 0;\n        for (int i = 0; i < lanes; ++i) {\n            running += delta[i];\n            level[i] = running;\n        }\n        return level;\n    }\n};\n",hints:'## Nudge\nApplying each job lane by lane costs O(lanes) per job. Only the final levels matter, so can you record each job in O(1) and rebuild everything once at the end?\n\n## Approach\nRecord, for each job, where its effect starts and where it stops, in a "change" array. Then sweep left to right keeping a running total; that total is the level of the current lane.\n\n## Key insight\nA job adds `v` at index `l` and subtracts `v` at index `r + 1` in the change array, so the running sum is `v` exactly on lanes `l..r`. Size the array `lanes + 1` so index `r + 1` is always valid, and use `long long`.\n',loadTests:async()=>(await e.A(28271)).default},"tide-pools":{meta:{id:"tide-pools",region:"R2",title:"Tide Pools",difficulty:"H",patterns:["two-pointers"],signals:["water held between walls","each cell is bounded by the best wall on each side","O(n) time with O(1) extra space"],prerequisites:["widest-basin"],parSeconds:1800,complexity:{time:"O(n)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.25,perf:.35},similar:[{name:"Trapping Rain Water",lcNumber:42}],spec:{kind:"function",name:"poolVolume",returns:"long long",params:[{type:"vector<int>",name:"heights"}]}},statement:"# Tide Pools\n\nA sea wall is built from unit-wide columns, and `heights[i]` is the height of column `i`. When the tide recedes, water stays in the hollows. A unit cell above a column holds water if there is a taller-or-equal wall somewhere to its left **and** somewhere to its right; the water level there is the lower of the two tallest walls on each side.\n\nReturn the total number of unit cells of water left behind. The ends of the wall are open, so water never rests beyond them.\n\n## Examples\n\n- `heights = [0, 1, 0, 2, 1, 0, 1, 3, 2, 1, 2, 1]` gives `6`.\n- `heights = [4, 2, 0, 3, 2, 5]` gives `9`.\n- `heights = [3, 0, 2]` gives `2`.\n\n## Constraints\n\n- `0 <= heights.size() <= 100000`\n- `0 <= heights[i] <= 100000`\n\nThe answer can exceed 32 bits. Aim for O(n) time and O(1) extra space.\n",editorial:"## Signals\n\"Water held between walls\": each position's answer depends on the best wall on each side, and a global sum over positions is requested. Prefix and suffix maxima appear naturally; the O(1)-space ask points to two pointers.\n\n## Brute force\nFor every column, scan left for the tallest wall and right for the tallest wall, and add `min(leftMax, rightMax) - height`. O(n^2) time, O(1) space; at n = 100000 that is about 10^10 operations.\n\nA better version precomputes `leftMax[i]` and `rightMax[i]` in two passes, then sums `min(leftMax[i], rightMax[i]) - heights[i]`. O(n) time, O(n) space.\n\n## Key insight\nWe only need `min(leftMax, rightMax)` at each column. Keep pointers at both ends and the tallest wall seen so far from each end. If `heights[left] < heights[right]`, then the right side holds a wall at least `heights[right] > heights[left]`, so the bound at `left` is exactly the running maximum on its own side, regardless of what lies between. Process `left` and move on. The symmetric case handles `right`.\n\n## Optimal\nMaintain `leftWall`, `rightWall` and `water` (a `long long`). While `left < right`: process the end with the smaller height: update that side's wall with `max`, add `wall - height`, and move that pointer inward. Invariant: all columns outside `[left, right]` have their water counted exactly. Each iteration finalises one column, so time is O(n), space O(1).\n\n## C++ walkthrough\nThe total can reach about 10^5 x 10^5 = 10^10, so `water` must be `long long`; each added term fits in `int`. When `heights[left] == heights[right]` either side may move; the `else` branch handles it. Taking `heights` by value is not needed (a `const vector<int>&` is better), it is by value here only to match the judge's signature.\n\n## Common bugs\nUsing the global maximum instead of per-side maxima; accumulating in `int`; counting water over the very first or last column's outside; stopping at the global peak and ignoring basins after it; updating the wall after adding water (so negative contributions appear).\n\n## Follow-ups\nDo it with a monotonic stack. Trap water on a 2-D grid (use a heap with Dijkstra-like expansion). What if heights stream in?\n\n## Similar problems\nTrapping Rain Water (LeetCode 42); Container With Most Water is the easier cousin (see Widest Basin).\n",reference:"class Solution {\npublic:\n    long long poolVolume(vector<int> heights) {\n        int left = 0, right = static_cast<int>(heights.size()) - 1;\n        int leftWall = 0, rightWall = 0;  // tallest wall seen so far from each end\n        long long water = 0;\n        while (left < right) {\n            // Whichever end is lower is bounded by its own side's tallest wall,\n            // because the other side already has a wall at least that tall.\n            if (heights[left] < heights[right]) {\n                leftWall = max(leftWall, heights[left]);\n                water += leftWall - heights[left];\n                ++left;\n            } else {\n                rightWall = max(rightWall, heights[right]);\n                water += rightWall - heights[right];\n                --right;\n            }\n        }\n        return water;\n    }\n};\n",hints:"## Nudge\nFor one column, how much water sits above it? It depends on the tallest wall on each side, and only on the shorter of those two.\n\n## Approach\nPrecompute the tallest wall to the left and to the right of every column and sum `min(left, right) - height`. Then notice you can do it with two pointers and two running maxima, no arrays.\n\n## Key insight\nMove the pointer at the lower end. Its side's running maximum is the true bound there, because the other side already has a wall at least as tall as that end, so the lower end's water level is its own side's maximum.\n",loadTests:async()=>(await e.A(89171)).default},"triple-tally":{meta:{id:"triple-tally",region:"R2",title:"Triple Tally",difficulty:"M",patterns:["two-pointers"],signals:["triples that sum to a target","count distinct combinations","sort first"],prerequisites:["mirror-check"],parSeconds:1200,complexity:{time:"O(n^2)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.25,perf:.35},similar:[{name:"3Sum",lcNumber:15}],spec:{kind:"function",name:"countTriples",returns:"int",params:[{type:"vector<int>",name:"nums"}]}},statement:"# Triple Tally\n\nA salvage crew logs the buoyancy of each crate as an integer: positive crates float, negative crates sink. A **balanced trio** is three crates whose buoyancy sums to exactly `0`.\n\nGiven the list `nums`, return how many **distinct** balanced trios exist. Two trios are the same if they hold the same three values, regardless of which crates they came from or in what order. For example, `[-1, 0, 1]` taken from two different `-1` crates is still one trio.\n\n## Examples\n\n- `nums = [-1, 0, 1, 2, -1, -4]` gives `2` (the trios `-1, -1, 2` and `-1, 0, 1`).\n- `nums = [0, 1, 1]` gives `0`.\n- `nums = [0, 0, 0, 0]` gives `1`.\n\n## Constraints\n\n- `0 <= nums.size() <= 3000`\n- `-100000 <= nums[i] <= 100000`\n\nA cubic scan over all trios is too slow; aim for O(n^2).\n",editorial:'## Signals\n"Three values that sum to a target" with "distinct combinations" asked for. Reducing "three" to "one plus a pair" and sorting to make pair search linear is the classic two-pointer reduction.\n\n## Brute force\nTry every index triple, insert the sorted values into a set, and return its size. O(n^3) time: 4.5 billion trios at n = 3000, far beyond the limit.\n\n## Key insight\nAfter sorting, once the smallest value is fixed, the pair search is monotone: a sum that is too small can only be fixed by raising the low end, and one that is too large only by lowering the high end. That makes the pair search O(n) instead of O(n^2).\n\n## Optimal\nSort. For `i` from the left: stop when `nums[i] > 0` (three positives cannot sum to zero); skip `i` when it equals the previous value. Set `lo = i + 1`, `hi = n - 1`. While `lo < hi`, look at `sum = nums[i] + nums[lo] + nums[hi]`: below zero, `++lo`; above, `--hi`; equal, count one trio and advance `lo` and `hi` past every copy of their current values. Invariant: every unseen trio with smallest value `nums[i]` lies inside `[lo, hi]`. Time O(n^2) after an O(n log n) sort; extra space O(1) beyond the sorted copy.\n\n## C++ walkthrough\nAccumulate the sum in `long long` out of habit; here three values within 10^5 fit comfortably in `int`, so state that you checked. Use `while (lo < hi && nums[lo] == a)` rather than a single `++lo` so a block of repeats is skipped in one go. Taking `nums` by value lets you sort without touching the caller\'s data.\n\n## Common bugs\nCounting repeats because only the first index is de-duplicated; advancing only one pointer after a hit and then re-finding the same trio; breaking at `nums[i] >= 0` and losing the `0, 0, 0` trio; skipping duplicates with `nums[i] == nums[i + 1]` instead of the previous element, which loses `-1, -1, 2`.\n\n## Follow-ups\nReturn the trios themselves. Generalise to k-Sum with recursion (4Sum). Find the trio sum closest to a target (3Sum Closest). What changes if the array cannot be sorted?\n\n## Similar problems\n3Sum (LeetCode 15) returns the trios; this problem returns only their count.\n',reference:"class Solution {\npublic:\n    int countTriples(vector<int> nums) {\n        sort(nums.begin(), nums.end());\n        const int n = static_cast<int>(nums.size());\n        int count = 0;\n        for (int i = 0; i + 2 < n; ++i) {\n            if (nums[i] > 0) break;                          // sorted: all three would be positive\n            if (i > 0 && nums[i] == nums[i - 1]) continue;   // same smallest value as before\n            int lo = i + 1, hi = n - 1;\n            while (lo < hi) {\n                const long long sum = static_cast<long long>(nums[i]) + nums[lo] + nums[hi];\n                if (sum < 0) ++lo;\n                else if (sum > 0) --hi;\n                else {\n                    ++count;\n                    const int a = nums[lo], b = nums[hi];\n                    while (lo < hi && nums[lo] == a) ++lo;   // skip repeats of the middle value\n                    while (lo < hi && nums[hi] == b) --hi;   // skip repeats of the largest value\n                }\n            }\n        }\n        return count;\n    }\n};\n",hints:"## Nudge\nFixing one crate leaves a two-crate problem: find two values that sum to its negation. Sorted data makes that cheap.\n\n## Approach\nSort. For each smallest value `nums[i]`, run two pointers over the rest: move the low one up when the sum is too small, the high one down when too large. When it hits zero, count it and step both past repeated values. Skip a repeated `nums[i]` too.\n\n## Key insight\nDe-duplicating the three positions (smallest, middle, largest) separately is what makes each distinct trio counted exactly once.\n",loadTests:async()=>(await e.A(48969)).default},"widest-basin":{meta:i.f,statement:"# Widest Basin\n\nAlong a canal, vertical posts stand one unit apart. The post at position `i` has height `heights[i]`. Choose any two posts and stretch a tarp between them to make a basin: its **capacity** is the distance between the posts (the difference of their positions) times the height of the **shorter** of the two. Tall posts between them do not matter.\n\nReturn the largest capacity you can get. If there are fewer than two posts, the answer is `0`.\n\n## Examples\n\n- `heights = [1, 8, 6, 2, 5, 4, 8, 3, 7]` gives `49` (the posts of height 8 and 7, seven apart).\n- `heights = [1, 1]` gives `1`.\n- `heights = [4, 3, 2, 1, 4]` gives `16`.\n\n## Constraints\n\n- `0 <= heights.size() <= 100000`\n- `0 <= heights[i] <= 100000`\n\nNote that the answer can exceed the range of a 32-bit integer. Aim for O(n) time.\n",editorial:'## Signals\n"Best pair of positions" where the value is (distance) x (the smaller of two things). The value has a trade-off between width and height, and the input is not sorted, so look for a greedy argument that discards candidates.\n\n## Brute force\nTry all pairs `(i, j)` and take the maximum of `(j - i) * min(heights[i], heights[j])`. O(n^2) time, O(1) space: about 5 billion pairs at n = 100000, which times out.\n\n## Key insight\nStart with the widest pair `(0, n - 1)`. Suppose `heights[left] <= heights[right]`. Any pair using `left` with a partner closer than `right` has smaller width and height at most `heights[left]`, so it cannot beat the current capacity. Hence `left` can be dropped without losing the optimum.\n\n## Optimal\nTwo pointers at the ends. Each step: update `best` with `(right - left) * min(h[left], h[right])`, then move the pointer at the shorter post inward (either one on a tie). Invariant: the optimal pair lies within `[left, right]` or its value has already been recorded. Each step shrinks the window by one, so time is O(n), space O(1).\n\n## C++ walkthrough\n`(right - left) * min(...)` can reach 10^5 x 10^5 = 10^10, which overflows `int`; widen one operand to `long long` before multiplying (`static_cast<long long>(right - left) * ...`), not the product afterwards. `std::min` on two `int`s returns an `int`.\n\n## Common bugs\nMoving the taller pointer; using `right - left + 1` as the width; computing the product in `int`; returning garbage for `n < 2` (the loop condition handles it); trying to prove correctness with the sorted case only.\n\n## Follow-ups\nReturn the pair of indices. What if the tarp must stay above every post in between (that is Tide Pools)? What if heights are streamed?\n\n## Similar problems\nContainer With Most Water (LeetCode 11).\n',reference:"class Solution {\npublic:\n    long long bestBasin(vector<int> heights) {\n        int left = 0, right = static_cast<int>(heights.size()) - 1;\n        long long best = 0;\n        while (left < right) {\n            const long long width = right - left;\n            best = max(best, width * min(heights[left], heights[right]));\n            // The shorter wall caps every basin it forms with anything closer, so it can never do better.\n            if (heights[left] < heights[right]) ++left;\n            else --right;\n        }\n        return best;\n    }\n};\n",hints:"## Nudge\nChecking every pair is O(n^2). Start with the widest pair and think about which of its two posts is worth keeping when you shrink the width.\n\n## Approach\nBegin with posts at both ends. Record the capacity, then move the pointer at the **shorter** post inward. Repeat until the pointers meet.\n\n## Key insight\nThe shorter post limits every basin it can form with any closer partner (they are narrower and cannot be taller than the shorter one), so that post has already given its best result and can be discarded safely.\n",loadTests:async()=>(await e.A(31364)).default},"calm-window":{meta:{id:"calm-window",region:"R3",title:"Calm Window",difficulty:"M",patterns:["sliding-window"],signals:["contiguous substring","longest with a condition","at most k distinct"],prerequisites:[],parSeconds:900,complexity:{time:"O(n)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.25,edge:.2,adversarial:.25,perf:.3},similar:[{name:"Longest Substring with At Most K Distinct Characters",lcNumber:340}],spec:{kind:"function",name:"longestCalm",returns:"int",params:[{type:"string",name:"s"},{type:"int",name:"k"}]}},statement:'# Calm Window\n\nA sensor logs one lowercase letter per tick as a string `s`. A stretch of consecutive ticks is **calm** if it contains at most `k` different letters.\n\nReturn the length of the longest calm stretch in `s`.\n\n## Examples\n\n- `s = "eceba"`, `k = 2` gives `3` (the stretch `"ece"`).\n- `s = "aaaa"`, `k = 1` gives `4`.\n- `s = "abc"`, `k = 5` gives `3`.\n\n## Constraints\n\n- `0 <= s.length() <= 100000`\n- `s` contains only `a` to `z`.\n- `1 <= k <= 26`\n',editorial:'## Signals\n"Longest contiguous stretch" with a condition that only gets harder as the stretch grows (more letters can only add distinct values) is a sliding window.\n\n## Brute force\nFor every start, extend to the right while the distinct count is at most `k`, tracking the best length. O(n^2) time, O(1) space (a 26-slot count array). With n = 100000 and few distinct letters this does billions of steps.\n\n## Key insight\nCalmness is monotone: removing letters from a calm stretch keeps it calm. So when the window becomes too diverse you only ever need to move its left edge forward, never restart.\n\n## Optimal\nMaintain `count[26]` and `distinct` for the window `[left, right]`. Add `s[right]`; if its count went 0 to 1, increment `distinct`. While `distinct > k`, remove `s[left]` (decrement; if it hits 0, decrement `distinct`) and advance `left`. After this the window is calm, so record `right - left + 1`. Invariant: after each step the window is the longest calm stretch ending at `right`. Each index is added once and removed at most once: time O(n), space O(1) (26 counters).\n\n## C++ walkthrough\nA fixed `int count[26]` beats a hash map here: no hashing, no allocation. The shrink is a `while` loop so the window is calm before we measure it. The result is an `int` because it never exceeds n <= 100000.\n\n## Common bugs\nForgetting to update `distinct` when a count returns to zero; measuring the window before it is calm again; returning the final window length instead of the maximum seen.\n\n## Follow-ups\nWhat if the alphabet is Unicode or large? Use a hash map for counts (still O(n) expected). Return the stretch itself, not just its length. Count how many calm stretches exist (add `right - left + 1` each step).\n\n## Similar problems\nLongest Substring with At Most K Distinct Characters (LeetCode 340, premium); Longest Substring Without Repeating Characters (LeetCode 3) is the same idea with "distinct equals length".\n',reference:"class Solution {\npublic:\n    int longestCalm(string s, int k) {\n        int count[26] = {};   // occurrences of each letter inside the window\n        int distinct = 0;     // letters with count > 0\n        int best = 0;\n        int left = 0;\n        for (int right = 0; right < static_cast<int>(s.size()); ++right) {\n            if (count[s[right] - 'a']++ == 0) ++distinct;\n            while (distinct > k) {  // shrink until calm again\n                if (--count[s[left] - 'a'] == 0) --distinct;\n                ++left;\n            }\n            best = max(best, right - left + 1);\n        }\n        return best;\n    }\n};\n",hints:"## Nudge\nIf a stretch is calm, is every smaller stretch inside it calm too? What does that let you do when it stops being calm?\n\n## Approach\nGrow a window to the right one letter at a time. When it has too many different letters, move the left edge forward until it is calm again.\n\n## Key insight\nKeep a count per letter and the number of letters with a non-zero count. Each index enters and leaves the window at most once, so the whole scan is linear. Shrink in a loop: dropping one character does not always remove a letter from the window.\n",loadTests:async()=>(await e.A(87216)).default},"cover-strip":{meta:{id:"cover-strip",region:"R3",title:"Cover Strip",difficulty:"H",patterns:["sliding-window","hash-lookup"],signals:["shortest stretch that contains everything required","required items can repeat","grow right until valid, shrink left while valid"],prerequisites:["tight-patch","tidy-tape","shuffle-spotter"],parSeconds:1500,complexity:{time:"O(n + m)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.25,perf:.35},similar:[{name:"Minimum Window Substring",lcNumber:76}],spec:{kind:"function",name:"smallestCover",returns:"string",params:[{type:"string",name:"tape"},{type:"string",name:"charms"}]}},statement:'# Cover Strip\n\nA banner is printed as a string of letters, `tape`. A collector needs a set of charms, given as the string `charms`: every letter in `charms` stands for one charm, so `"aab"` means two `a` charms and one `b` charm.\n\nA stretch of consecutive letters of `tape` **covers** the charms when it holds at least as many copies of each letter as `charms` asks for (it may hold extra letters too).\n\nReturn the **shortest** covering stretch. If several have the same shortest length, return the one that starts **leftmost**. If no stretch covers the charms, return the empty string.\n\n## Examples\n\n- `tape = "xaybzacb"`, `charms = "abc"` gives `"acb"` (length 3; `"bzac"` also covers but is longer).\n- `tape = "aab"`, `charms = "ab"` gives `"ab"`.\n- `tape = "abca"`, `charms = "aa"` gives `"abca"` (two `a` are needed).\n- `tape = "xyz"`, `charms = "w"` gives `""`.\n\n## Constraints\n\n- `0 <= tape.length() <= 100000`\n- `1 <= charms.length() <= 100000`\n- Both strings contain only English letters `a` to `z` and `A` to `Z` (upper and lower case are different letters).\n',editorial:'## Signals\n"Shortest stretch that contains everything required", where the requirement is a multiset of letters. Growing the stretch never breaks a cover and shrinking can, which is the monotone shape that lets two pointers replace trying every start. The repeats in `charms` (`"aab"` needs two `a`) rule out a plain set of letters.\n\n## Brute force\nFor every start, extend to the right until the stretch covers, remember the shortest. O(n^2) time even with an O(1) coverage check (a `missing` counter), O(1) extra space. With `n = 100000` and the last needed letter at the very end of the tape, every start scans to the end: about 5 * 10^9 steps.\n\n## Key insight\nIf `[l, r]` covers, then `[l, r\']` covers for every `r\' >= r`. So for each right end there is a largest `l` such that `[l, r]` still covers, and that `l` never decreases as `r` grows. Two pointers that only move forward visit each position twice.\n\n## Optimal\n`need[c]` starts as the number of copies of `c` the charms ask for. Adding a letter does `need[c]--`; if it was positive the letter was really needed, so `missing` drops by one. When `missing == 0` the window covers: record it if it is strictly shorter than the best so far, then drop `tape[left]` (`need[c]++`; if it becomes positive we lost a needed copy and `missing` rises) and advance `left`. Time O(n + m), space O(1) (a 128-entry table).\n\n## C++ walkthrough\n`array<int, 128>` indexed by `static_cast<unsigned char>(ch)` avoids negative indices if `char` is signed. The trick `need[c]-- > 0` reads the old value and decrements in one step; counts at or below zero mean spare copies. `bestLen = n + 1` is a sentinel for "none found", and `tape.substr(bestStart, bestLen)` is only called when a cover exists. Strict `<` keeps the leftmost of equal lengths because the leftmost cover is found first.\n\n## Common bugs\nTreating `charms` as a set (the answer for `"aab"` needs two `a`); using `<=` so the rightmost of equal covers wins; returning the first covering prefix without shrinking; shrinking before the window covers; calling `substr` with the sentinel when nothing covers; checking coverage by scanning the whole table each step and still being fine, but doing it per start and timing out.\n\n## Follow-ups\nReturn the length only, or every shortest cover. Allow arbitrary bytes (use `unordered_map`). Count the covering stretches instead (for each right end add `left_max + 1`). Do the same on a stream where you cannot go back.\n\n## Similar problems\nMinimum Window Substring (LeetCode 76).\n',reference:'class Solution {\npublic:\n    string smallestCover(string tape, string charms) {\n        const int n = static_cast<int>(tape.size());\n        array<int, 128> need{};  // need[c] > 0: copies of c the window still lacks; <= 0: spare copies\n        for (const char ch : charms) ++need[static_cast<unsigned char>(ch)];\n        int missing = static_cast<int>(charms.size());  // charm copies not yet covered\n        int bestStart = 0;\n        int bestLen = n + 1;  // n + 1 means "no cover found"\n        int left = 0;\n        for (int right = 0; right < n; ++right) {\n            if (need[static_cast<unsigned char>(tape[right])]-- > 0) --missing;\n            while (missing == 0) {  // window [left, right] covers: record it, then try to shrink\n                if (right - left + 1 < bestLen) {  // strict \'<\' keeps the leftmost on ties\n                    bestLen = right - left + 1;\n                    bestStart = left;\n                }\n                if (++need[static_cast<unsigned char>(tape[left])] > 0) ++missing;  // we dropped a needed copy\n                ++left;\n            }\n        }\n        return bestLen > n ? "" : tape.substr(bestStart, bestLen);\n    }\n};\n',hints:"## Nudge\nFix the right end of a stretch and ask: what is the best (rightmost) left end that still covers? If the right end moves forward, can that best left end ever move backward?\n\n## Approach\nKeep a window `[left, right]` and a table of how many copies of each letter are still missing. Move `right` forward, adding its letter. As soon as nothing is missing, record the window, then move `left` forward while the window still covers, recording each time it does.\n\n## Key insight\nBoth ends only move forward, so each letter enters and leaves the window once: O(n + m) total. Track `missing` (the number of charm copies not yet covered) instead of comparing the whole table each step, and use a strict `<` on the length so that the leftmost of equally short covers is kept.\n",loadTests:async()=>(await e.A(66611)).default},"distinct-picks":{meta:{id:"distinct-picks",region:"R3",title:"Distinct Picks",difficulty:"H",patterns:["sliding-window","hash-lookup"],signals:["count stretches with exactly k different values","at most k kinds minus at most k-1 kinds","count can exceed int"],prerequisites:["odd-picks","flip-budget"],parSeconds:1500,complexity:{time:"O(n)",space:"O(n)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.25,perf:.35},similar:[{name:"Subarrays with K Different Integers",lcNumber:992}],spec:{kind:"function",name:"countKindStretches",returns:"long long",params:[{type:"vector<int>",name:"beads"},{type:"int",name:"k"}]}},statement:"# Distinct Picks\n\nA jeweller strings beads in a row; `beads[i]` is the colour code of bead `i`. A stretch of consecutive beads is **k-coloured** when it contains **exactly `k` different colour codes** (each may repeat any number of times).\n\nCount the k-coloured stretches. Two stretches are different when they start or end at different positions, even if they hold the same colours.\n\n## Examples\n\n- `beads = [3, 1, 3, 2, 2]`, `k = 2` gives `5` (`[3,1]`, `[1,3]`, `[3,1,3]`, `[3,2]`, `[3,2,2]`).\n- `beads = [4, 4, 4]`, `k = 1` gives `6` (every stretch).\n- `beads = [1, 2, 3]`, `k = 4` gives `0`.\n\n## Constraints\n\n- `0 <= beads.size() <= 100000`\n- `1 <= beads[i] <= 100000`\n- `1 <= k <= 100000`\n- The answer can exceed the range of a 32-bit integer.\n",editorial:'## Signals\n"Count the stretches with exactly k different values." Counting plus an exact number of kinds is the cue for the "at most k minus at most k - 1" trick. A single window cannot count exact matches: when the window has k colours, the valid starts for this right end are a range whose lower end needs a second pointer.\n\n## Brute force\nFor every start, extend to the right while tracking the set of colours and count each stop where the set size equals `k`. O(n^2) time (times log n with `std::set`), O(n) space. With few colours and `k` at least the number of colours, every start extends to the end: about 5 * 10^9 steps for `n = 100000`.\n\n## Key insight\nStretches with at most `limit` colours are closed under shrinking, so for each right end the valid starts form one contiguous range `[left, right]`, and `left` never moves backward. Stretches with exactly `k` colours are those with at most `k` minus those with at most `k - 1`.\n\n## Optimal\n`atMost(limit)`: keep `count[colour]` and `kinds`. Add `beads[right]`; while `kinds > limit` remove from the left; add `right - left + 1`. Return `atMost(k) - atMost(k - 1)`, with `atMost(0) = 0`. Time O(n), space O(n) for the count table (colours are at most 100000, so an array replaces a hash map).\n\n## C++ walkthrough\n`count[beads[right]]++ == 0` tests "first copy" and increments in one step. The total is `long long`: a row of identical beads with `k = 1` has n(n+1)/2 stretches, about 5 * 10^9. `atMost` is a `static` helper taking `const vector<int>&` so nothing is copied. The `limit <= 0` guard makes `atMost(0) = 0` explicit (the window would also give 0, but it skips a pointless scan and an allocation).\n\n## Common bugs\nReturning `atMost(k)` (that includes stretches with fewer colours); an `int` total that overflows; adding only one stretch per right end instead of `right - left + 1`; resetting the count table inside the loop; extending from every start and timing out.\n\n## Follow-ups\nDo it with only a single pass using two left pointers (the "shortest and longest valid left end" approach). Colours up to 10^9 (use `unordered_map` or compress first). Report the longest k-coloured stretch instead of counting.\n\n## Similar problems\nSubarrays with K Different Integers (LeetCode 992), Count Number of Nice Subarrays (LeetCode 1248).\n',reference:"class Solution {\npublic:\n    long long countKindStretches(vector<int> beads, int k) {\n        return atMost(beads, k) - atMost(beads, k - 1);\n    }\n\nprivate:\n    // Stretches with at most `limit` different colours. Shrinking such a stretch keeps it valid,\n    // so one window is enough: every start from `left` to `right` works for this right end.\n    static long long atMost(const vector<int>& beads, int limit) {\n        if (limit <= 0) return 0;\n        vector<int> count(100001, 0);  // count[c]: copies of colour c inside the window\n        int kinds = 0;\n        int left = 0;\n        long long total = 0;\n        for (int right = 0; right < static_cast<int>(beads.size()); ++right) {\n            if (count[beads[right]]++ == 0) ++kinds;\n            while (kinds > limit) {\n                if (--count[beads[left]] == 0) --kinds;\n                ++left;\n            }\n            total += right - left + 1;\n        }\n        return total;\n    }\n};\n",hints:'## Nudge\n"Exactly k" is awkward for a window because shrinking can jump from "too many colours" straight past "exactly k". Is there a nearby question that a window answers cleanly?\n\n## Approach\nCount the stretches with at most `limit` colours using a window: for each right end, every start from `left` to `right` is valid, so add `right - left + 1`. Answer = `atMost(k) - atMost(k - 1)`.\n\n## Key insight\nThe set "at most `limit` colours" is closed under shrinking, so two forward-only pointers count it in O(n). Subtracting the stretches with at most `k - 1` colours leaves exactly `k`. The total can reach about n^2 / 2, so keep it in a `long long`, and return 0 when the limit is not positive.\n',loadTests:async()=>(await e.A(46503)).default},"flip-budget":{meta:{id:"flip-budget",region:"R3",title:"Flip Budget",difficulty:"M",patterns:["sliding-window"],signals:["longest run after at most k changes","count the bad items inside the window","bad count may not exceed the budget"],prerequisites:["tidy-tape"],parSeconds:780,complexity:{time:"O(n)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.25,perf:.35},similar:[{name:"Max Consecutive Ones III",lcNumber:1004}],spec:{kind:"function",name:"longestAfterFlips",returns:"int",params:[{type:"vector<int>",name:"lamps"},{type:"int",name:"budget"}]}},statement:"# Flip Budget\n\nA corridor has a row of lamps. `lamps[i]` is `1` if lamp `i` is on and `0` if it is off. A technician can switch **at most `budget` lamps from off to on** (lamps that are already on stay on).\n\nAfter the flips, what is the length of the longest run of consecutive lamps that are all on? Return that best possible length.\n\n## Examples\n\n- `lamps = [1, 1, 0, 0, 1, 1, 1, 0, 1]`, `budget = 2` gives `7` (flip the two zeros at positions 2 and 3, or at 3 and 7; the first choice gives the run from position 0 to 6).\n- `lamps = [0, 0, 0]`, `budget = 0` gives `0`.\n- `lamps = [1, 0, 1]`, `budget = 1` gives `3`.\n\n## Constraints\n\n- `0 <= lamps.size() <= 100000`\n- `lamps[i]` is `0` or `1`.\n- `0 <= budget <= 100000`\n",editorial:'## Signals\n"Longest run after changing at most `k` items." Reword it: the longest window containing at most `k` bad items (zeros), since each bad item can be fixed with one change. Contiguity plus a monotone budget is the variable sliding window again, this time counting one kind of element instead of letters.\n\n## Brute force\nTry every window and count its zeros. O(n^3), or O(n^2) with a running count and early break. For `n = 100000` with an effectively unlimited budget the quadratic version does about 5 * 10^9 steps.\n\n## Key insight\nA window can be made all-on iff `zeros <= budget`. Validity is preserved when shrinking, so a two-pointer scan that only moves right finds the longest valid window.\n\n## Optimal\nFor each `right`, add `lamps[right]` to the zero count; while `zeros > budget`, remove `lamps[left]` (decrementing `zeros` if it was off) and advance `left`; record `right - left + 1`. Time O(n), space O(1).\n\n## C++ walkthrough\nNo flipping is simulated. Compare with `==` against `0` and keep the zero count as an `int`. When `budget = 0` the window collapses to runs of ones, and an all-zero input gives `0`, which falls out of the loop naturally (the window becomes empty after each zero).\n\n## Common bugs\n`>=` instead of `>` in the shrink test (an off-by-one in the budget); forgetting to decrement the zero count when the dropped lamp was off; answering `ones + budget` (ignores positions); resetting the window when the budget is exceeded instead of sliding it.\n\n## Follow-ups\nReturn the window\'s start. Do the same with a cost per flip (positive costs, total budget; still a window). Allow flipping in both directions with a budget for each. How does it relate to "Longest Repeating Character Replacement"?\n\n## Similar problems\nMax Consecutive Ones III (LeetCode 1004).\n',reference:"class Solution {\npublic:\n    int longestAfterFlips(vector<int> lamps, int budget) {\n        int zeros = 0;  // off lamps inside the window [left, right]\n        int left = 0;\n        int best = 0;\n        for (int right = 0; right < static_cast<int>(lamps.size()); ++right) {\n            if (lamps[right] == 0) ++zeros;\n            while (zeros > budget) {  // cannot afford this many flips: drop from the left\n                if (lamps[left] == 0) --zeros;\n                ++left;\n            }\n            best = max(best, right - left + 1);\n        }\n        return best;\n    }\n};\n",hints:'## Nudge\nFlipping a zero costs one unit of budget. A window of lamps can be made all-on exactly when it has at most `budget` zeros. What is the largest such window?\n\n## Approach\nKeep a window and a count of the zeros inside it. Add lamps on the right; if the zero count goes over the budget, move the left edge forward until it is back within budget.\n\n## Key insight\nThe condition "zeros <= budget" is monotone: a sub-window of a valid window is valid. So the left edge never moves back and the scan is O(n). You never flip anything: you only count. The answer is the longest window ever seen within budget.\n',loadTests:async()=>(await e.A(98851)).default},"odd-picks":{meta:{id:"odd-picks",region:"R3",title:"Odd Picks",difficulty:"M",patterns:["sliding-window"],signals:["count stretches with exactly k of something","at most k minus at most k-1","count could exceed int"],prerequisites:["tight-patch","flip-budget"],parSeconds:1080,complexity:{time:"O(n)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.25,perf:.35},similar:[{name:"Count Number of Nice Subarrays",lcNumber:1248},{name:"Subarrays with K Different Integers",lcNumber:992}],spec:{kind:"function",name:"countExactOdds",returns:"long long",params:[{type:"vector<int>",name:"nums"},{type:"int",name:"k"}]}},statement:"# Odd Picks\n\nA game master lays out a row of number cards, `nums`. A stretch of consecutive cards is a **lucky pick** when it contains **exactly `k` odd numbers** (any number of even ones).\n\nCount the lucky picks. Two stretches are different when they start or end at different positions, even if they hold the same values.\n\n## Examples\n\n- `nums = [1, 1, 2, 1, 1]`, `k = 3` gives `2` (positions 0..3 and 1..4).\n- `nums = [2, 4, 6]`, `k = 1` gives `0`.\n- `nums = [2, 1, 2]`, `k = 1` gives `4` (`[1]`, `[2,1]`, `[1,2]`, `[2,1,2]`).\n\n## Constraints\n\n- `0 <= nums.size() <= 100000`\n- `1 <= nums[i] <= 1000000000`\n- `1 <= k <= 100000`\n- The answer can exceed the range of a 32-bit integer.\n",editorial:'## Signals\n"Count the stretches with exactly k of something." Counting (not maximising) plus an exact target is the cue for the "at most k minus at most k - 1" trick. A plain window cannot count exact matches because shrinking from the left can move you from "too many" straight past "exactly k".\n\n## Brute force\nFor every start, extend to the right while counting odd numbers and count each stop where the count equals `k`. O(n^2) time, O(1) space; for `n = 100000` with few odd numbers that is about 5 * 10^9 steps.\n\n## Key insight\nThe set of stretches with at most `k` odds is monotone under shrinking, so a window can count them in O(n). The stretches with exactly `k` odds are those with at most `k` minus those with at most `k - 1`.\n\n## Optimal\n`atMost(limit)`: slide `right`; add its parity; while the odd count exceeds `limit`, drop from the left; add `right - left + 1` (every start in the window works for this right end). Return `atMost(k) - atMost(k - 1)`, with `atMost(-1) = 0`. Time O(n), space O(1). Each call proves its own correctness: the window for a given right end is the longest valid stretch ending there, and shorter starts stay valid.\n\n## C++ walkthrough\n`nums[i] & 1` is the parity without a branch (values are positive, but it also works for negatives in two\'s complement). The total uses `long long`: with 100000 cards the answer can be about 5 * 10^9. `atMost` is a `static` private helper taking `const vector<int>&` so the input is not copied twice. `odds -= nums[left++] & 1` drops and advances in one step.\n\n## Common bugs\nCounting one stretch per right end (misses the even cards that can sit before the first odd); returning `atMost(k)` alone; an `int` total that overflows; forgetting the `limit < 0` guard when `k = 0` is allowed; using `if` instead of `while` for the shrink.\n\n## Follow-ups\nAllow `k = 0` (all-even stretches). Solve it with prefix counts and a frequency table instead (count previous prefixes with odd-count `p - k`). Apply the same trick to "exactly K different integers" (the hard version in this region). Return the stretches\' endpoints for the smallest one.\n\n## Similar problems\nCount Number of Nice Subarrays (LeetCode 1248), Subarrays with K Different Integers (LeetCode 992).\n',reference:'class Solution {\npublic:\n    long long countExactOdds(vector<int> nums, int k) {\n        // "exactly k" is the difference of two monotone questions.\n        return atMost(nums, k) - atMost(nums, k - 1);\n    }\n\nprivate:\n    // Number of stretches with at most `limit` odd numbers.\n    static long long atMost(const vector<int>& nums, int limit) {\n        if (limit < 0) return 0;\n        long long total = 0;\n        int odds = 0;  // odd numbers inside the window [left, right]\n        int left = 0;\n        for (int right = 0; right < static_cast<int>(nums.size()); ++right) {\n            odds += nums[right] & 1;\n            while (odds > limit) odds -= nums[left++] & 1;\n            total += right - left + 1;  // every start in [left, right] gives a valid stretch ending here\n        }\n        return total;\n    }\n};\n',hints:'## Nudge\n"Exactly k" windows are awkward because shrinking can break them. "At most k" windows are not: a sub-window of a valid one is valid. Can you turn one into the other?\n\n## Approach\nCount the stretches with at most `k` odd numbers using a sliding window: for each right end, every start from `left` to `right` is valid, so add `right - left + 1`. Do the same for at most `k - 1` and subtract.\n\n## Key insight\n`exactly(k) = atMost(k) - atMost(k - 1)`. The total can be about n^2 / 2, so keep it in a `long long`, and handle `k - 1 < 0` (it counts nothing).\n',loadTests:async()=>(await e.A(27514)).default},"pane-peaks":{meta:o.f,statement:"# Pane Peaks\n\nA greenhouse roof is a row of glass panes. `heat[i]` is the temperature reading of pane `i` (it can be negative on frosty days). A cleaning frame covers exactly `width` neighbouring panes and starts over the first `width` panes. It then slides one pane to the right at a time until it reaches the last pane.\n\nFor every position of the frame, record the **hottest** reading among the panes it covers. Return all these readings in order, from the leftmost frame position to the rightmost.\n\n## Examples\n\n- `heat = [2, 7, 1, 5, 3]`, `width = 3` gives `[7, 7, 5]`.\n- `heat = [4, 4, 4]`, `width = 2` gives `[4, 4]`.\n- `heat = [-3, -8, -1]`, `width = 1` gives `[-3, -8, -1]`.\n- `heat = [9, 1, 2]`, `width = 3` gives `[9]`.\n\n## Constraints\n\n- `1 <= heat.size() <= 100000`\n- `1 <= width <= heat.size()`\n- `-1000000000 <= heat[i] <= 1000000000`\n",editorial:'## Signals\n"The best value in every window of a fixed width", with output size about `n`. Re-scanning each window is O(n * width); a heap handles it in O(n log n) but needs lazy deletion. The shape "candidates that can never win again can be thrown away the moment a better, later one arrives" is the cue for a monotonic deque.\n\n## Brute force\nFor each frame start, loop over the `width` panes and take the maximum. O(n * width) time, O(1) extra space besides the answer. At `n = 100000` and `width = 50000` that is about 2.5 * 10^9 comparisons, well over the time limit.\n\n## Key insight\nTake two panes `a < b` (indices) in the same frame. If `heat[a] <= heat[b]`, then `a` leaves the frame before `b` does and is never hotter, so `a` can be discarded forever. The panes worth remembering are therefore a sequence whose readings strictly decrease as the index grows. The front is the oldest and hottest; it is the frame maximum.\n\n## Optimal\nKeep a `deque<int>` of indices with strictly decreasing `heat`. For each new index `i`: pop from the back while the back is not hotter than `heat[i]`; push `i`; pop the front if it is `<= i - width` (at most one index expires per step); once `i >= width - 1`, append `heat[front]`. Each index enters and leaves once: O(n) time, space O(k) where k = `width`.\n\n## C++ walkthrough\nStore indices because the expiry test needs positions, and the value is one lookup away. `<=` when popping keeps the deque strictly decreasing, so ties keep the newest pane, which leaves last. `answer.reserve(n - width + 1)` avoids reallocations; the number of frames is `n - width + 1`. `std::deque` is fine here; a `vector` plus a head index also works and is slightly faster.\n\n## Common bugs\nForgetting to expire the front (the answer then uses a pane outside the frame); `<` instead of `<=` in the expiry check (off by one); `if` instead of `while` when popping the back; starting to record at `i >= width` and losing the first frame; storing values and then being unable to tell what expired; rescanning each frame and timing out.\n\n## Follow-ups\nThe minimum of every window (flip the comparison). Both max and min at once for "longest stretch whose max minus min is at most a limit" (two deques plus a window). The same idea as a DP optimisation: best of the previous `k` states. Do it with a heap and lazy deletion, and compare.\n\n## Similar problems\nSliding Window Maximum (LeetCode 239), Longest Continuous Subarray With Absolute Diff Less Than or Equal to Limit (LeetCode 1438).\n',reference:"class Solution {\npublic:\n    vector<int> paneMaxima(vector<int> heat, int width) {\n        const int n = static_cast<int>(heat.size());\n        vector<int> answer;\n        answer.reserve(n - width + 1);\n        deque<int> window;  // indices; heat[] strictly non-increasing from front to back, front is the max\n        for (int i = 0; i < n; ++i) {\n            // A smaller pane to the left of i can never be the maximum again: i is hotter and leaves later.\n            while (!window.empty() && heat[window.back()] <= heat[i]) window.pop_back();\n            window.push_back(i);\n            // The front may have slid out of the frame [i - width + 1, i].\n            if (window.front() <= i - width) window.pop_front();\n            if (i >= width - 1) answer.push_back(heat[window.front()]);\n        }\n        return answer;\n    }\n};\n",hints:"## Nudge\nWhen the frame slides, one pane leaves on the left and one arrives on the right. If a pane is hotter than an older pane that is still in the frame, can the older pane ever be the answer again?\n\n## Approach\nKeep a deque of pane indices whose readings go from hottest (front) to coolest (back). Before adding pane `i`, pop every cooler pane off the back. Then add `i`. If the front index has slid out of the frame, pop it. Once the first frame is complete, the front is the answer for that frame.\n\n## Key insight\nAn older pane that is not hotter than a newer one is useless: the newer one stays in every frame the older one does, and is at least as hot. So the deque stays sorted and every index is pushed and popped at most once, giving O(n) instead of O(n * width). Store indices, not values, so you can tell when the front has expired.\n",loadTests:async()=>(await e.A(62274)).default},"peak-stretch":{meta:{id:"peak-stretch",region:"R3",title:"Peak Stretch",difficulty:"E",patterns:["sliding-window"],signals:["fixed-size contiguous block","best total of k in a row","slide by adding one and dropping one"],prerequisites:[],parSeconds:420,complexity:{time:"O(n)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.25,edge:.25,adversarial:.15,perf:.35},similar:[{name:"Maximum Average Subarray I",lcNumber:643}],spec:{kind:"function",name:"peakStretch",returns:"long long",params:[{type:"vector<int>",name:"readings"},{type:"int",name:"k"}]}},statement:"# Peak Stretch\n\nA buoy records one integer reading per minute, in the list `readings`. Readings can be negative. Look at every block of exactly `k` consecutive minutes and add up its readings.\n\nReturn the largest block total.\n\n## Examples\n\n- `readings = [1, 4, 2, 10, 3]`, `k = 2` gives `13` (the block `[10, 3]`; the block `[2, 10]` only gives 12).\n- `readings = [-5, -2, -9]`, `k = 1` gives `-2`.\n- `readings = [3, -1, 3]`, `k = 3` gives `5`.\n\n## Constraints\n\n- `1 <= k <= readings.size() <= 100000`\n- `-1000 <= readings[i] <= 1000`\n",editorial:'## Signals\n"Every block of exactly `k` consecutive items" is a fixed-size window. The block always has the same length, so consecutive blocks differ by one item entering and one leaving.\n\n## Brute force\nFor each start index sum the next `k` readings. O(n * k) time, O(1) space; with `n = 100000` and `k` near `n / 2` this is about 2.5 * 10^9 additions and times out.\n\n## Key insight\n`total(i+1) = total(i) + readings[i + k] - readings[i]`. Keep the running total and update it in O(1) while sliding.\n\n## Optimal\nSum the first `k` readings, record it as `best`, then for each later index add the new reading and subtract the one `k` places back, updating `best`. Time O(n), space O(1). The total is at most 10^8 in magnitude so `int` would fit, but `long long` keeps the habit for larger limits.\n\n## C++ walkthrough\nUse `LLONG_MIN` (or the first block\'s total) as the initial maximum, never `0`. Loop `i` from `k` so that `readings[i - k]` is always valid. A `const int n = static_cast<int>(readings.size())` avoids signed/unsigned comparison surprises.\n\n## Common bugs\nStarting `best` at `0` (wrong when every block is negative); dropping the wrong element (off by one in `i - k`); stopping the loop one block early; recomputing each block from scratch.\n\n## Follow-ups\nReturn the average as a `double`. Return the start index of the best block. What if `k` can be larger than the list? (Decide and state the contract.) What changes for a circular list?\n\n## Similar problems\nMaximum Average Subarray I (LeetCode 643).\n',reference:"class Solution {\npublic:\n    long long peakStretch(vector<int> readings, int k) {\n        const int n = static_cast<int>(readings.size());\n        long long window = 0;  // total of the k readings ending at index i\n        for (int i = 0; i < k; ++i) window += readings[i];\n        long long best = window;\n        for (int i = k; i < n; ++i) {\n            window += readings[i] - readings[i - k];  // slide: add the newcomer, drop the oldest\n            best = max(best, window);\n        }\n        return best;\n    }\n};\n",hints:"## Nudge\nTwo neighbouring blocks of `k` minutes share almost all of their readings. How do their totals differ?\n\n## Approach\nAdd up the first `k` readings once. Then move the block one minute at a time: add the new reading on the right and subtract the one that just left on the left.\n\n## Key insight\nEach slide costs O(1), so the whole scan is O(n) instead of O(n * k). Start `best` from the first block's total, not from 0, because every total can be negative.\n",loadTests:async()=>(await e.A(50386)).default},"quota-run":{meta:{id:"quota-run",region:"R3",title:"Quota Run",difficulty:"H",patterns:["monotonic-deque","prefix-sum","sliding-window"],signals:["shortest stretch with sum at least a target","values can be negative so a plain window fails","prefix sums plus a deque of candidates"],prerequisites:["tight-patch","pane-peaks"],parSeconds:1800,complexity:{time:"O(n)",space:"O(n)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.25,perf:.35},similar:[{name:"Shortest Subarray with Sum at Least K",lcNumber:862}],spec:{kind:"function",name:"shortestQuota",returns:"int",params:[{type:"vector<int>",name:"change"},{type:"long long",name:"quota"}]}},statement:"# Quota Run\n\nA trader logs the change in coins at the end of each day: `change[i]` is positive for a good day and negative for a bad one. The trader wants to know how quickly a **run of consecutive days** can add up to the quota.\n\nReturn the length of the **shortest** non-empty run of consecutive days whose changes sum to **at least** `quota`. If no run reaches the quota, return `-1`.\n\n## Examples\n\n- `change = [2, -1, 2]`, `quota = 3` gives `3` (only the whole row reaches 3).\n- `change = [5]`, `quota = 5` gives `1`.\n- `change = [1, 2]`, `quota = 4` gives `-1`.\n- `change = [84, -37, 32, 40, 95]`, `quota = 167` gives `3` (`32 + 40 + 95 = 167`, and no run of two days reaches 167).\n\n## Constraints\n\n- `1 <= change.size() <= 100000`\n- `-100000 <= change[i] <= 100000`\n- `1 <= quota <= 10000000000`\n- Sums of a run can exceed the range of a 32-bit integer.\n",editorial:'## Signals\n"Shortest run with sum at least a target" looks like a sliding window, but the values can be negative. The window needs monotonicity: adding an element must not decrease the sum and removing one must not increase it. Negatives break both, so the plain two-pointer pass gives wrong answers. The cue to switch is "contiguous, sum condition, negatives allowed": go to prefix sums.\n\n## Brute force\nFor each start, extend to the right until the sum reaches the quota (stop at the first hit, since longer is never better). O(n^2) time, O(1) space. If no run reaches the quota (say every change is -1), every start scans to the end: about 5 * 10^9 additions at `n = 100000`.\n\n## Key insight\nWith `prefix[0] = 0` and `prefix[k] = change[0] + ... + change[k-1]`, a run from start `s` to end `e` (`s < e`) has sum `prefix[e] - prefix[s]`. We want the smallest `e - s` with `prefix[e] - prefix[s] >= quota`. Fix `e`. A start `s` is useless in two situations. (1) It already satisfied some earlier end `e\'`: every later end is farther away, so `s` can only give longer runs than the one just recorded. (2) A newer start `s\' > s` has `prefix[s\'] <= prefix[s]`: `s\'` is closer and gives a sum at least as large, so `s` can never win.\n\n## Optimal\nMaintain a deque of start indices whose prefix values strictly increase from front to back. For each end `e` from 0 to `n`: while `prefix[e] - prefix[front] >= quota`, record `e - front` and pop the front (rule 1); then while `prefix[back] >= prefix[e]`, pop the back (rule 2); push `e`. Each index is pushed and popped once: O(n) time, O(n) space for the prefix array and the deque.\n\n## C++ walkthrough\n`prefix` is `vector<long long>`: `n * max|change| = 10^10` does not fit in `int`, and `quota` is already `long long`. The front check is a `while`, not an `if`: after popping one start, the next start may also satisfy the quota at the same end. The deque stores indices rather than values because the answer is a length. The sentinel `best = n + 1` means "no run", and is converted to `-1` at the end. The first loop runs on the front, the second on the back; keep their order, since pushing before checking the front would allow an empty run (`e - e = 0`).\n\n## Common bugs\nUsing the positive-numbers window (wrong when a negative appears inside the best run or makes a prefix of the window drag the sum down); never popping dominated starts from the back; recording the front without popping it; an `if` instead of `while` on the front; `int` prefix sums that overflow on large inputs; returning `0` for "no run" instead of `-1`; the O(n^2) per-start scan.\n\n## Follow-ups\nPositive values only: the plain window is enough, and the deque is not needed (compare with Tight Patch). Longest run with sum at least the quota (a different structure: monotone stack of prefixes plus binary search). Count the runs instead (needs an ordered or Fenwick structure). Return the start index too, with ties going leftmost.\n\n## Similar problems\nShortest Subarray with Sum at Least K (LeetCode 862), Maximum Sum Circular Subarray (LeetCode 918, same prefix + deque idea), Constrained Subsequence Sum (LeetCode 1425).\n',reference:'class Solution {\npublic:\n    int shortestQuota(vector<int> change, long long quota) {\n        const int n = static_cast<int>(change.size());\n        vector<long long> prefix(n + 1, 0);  // prefix[i] = sum of the first i days\n        for (int i = 0; i < n; ++i) prefix[i + 1] = prefix[i] + change[i];\n        int best = n + 1;  // n + 1 means "no run reaches the quota"\n        deque<int> starts;  // indices with strictly increasing prefix values: the only useful run starts\n        for (int end = 0; end <= n; ++end) {\n            // The oldest start that reaches the quota is the shortest run ending here. After using it, any\n            // later end is farther away, so this start can never give a shorter run: drop it.\n            while (!starts.empty() && prefix[end] - prefix[starts.front()] >= quota) {\n                best = min(best, end - starts.front());\n                starts.pop_front();\n            }\n            // A start with a prefix not smaller than prefix[end] is beaten by `end`: it is older (longer runs)\n            // and has a bigger prefix (smaller sums), so it can never win. Drop it.\n            while (!starts.empty() && prefix[starts.back()] >= prefix[end]) starts.pop_back();\n            starts.push_back(end);\n        }\n        return best > n ? -1 : best;\n    }\n};\n',hints:'## Nudge\nTry the usual window: grow on the right, shrink on the left while the sum is big enough. Where does it break when `change` has negative numbers? Then rewrite "sum of days i..j" using prefix sums.\n\n## Approach\nLet `prefix[k]` be the sum of the first `k` days. A run from start `s` to end `e` has sum `prefix[e] - prefix[s]`. Sweep `e` from 0 to `n` and keep a deque of candidate starts whose prefix values increase. While the front start makes the sum reach the quota, record `e - start` and pop it. Before pushing `e`, pop starts from the back whose prefix is not smaller than `prefix[e]`.\n\n## Key insight\nTwo facts justify throwing candidates away. A start that already reached the quota is never useful again, because every later end is farther away. A start with a prefix at least as big as a newer start\'s prefix is older (longer runs) and gives smaller sums, so the newer one always beats it. What remains is a deque with increasing prefix values: a monotonic deque again. Use `long long` for prefix sums: they reach 10^10.\n',loadTests:async()=>(await e.A(99701)).default},"shuffle-spotter":{meta:{id:"shuffle-spotter",region:"R3",title:"Shuffle Spotter",difficulty:"M",patterns:["sliding-window"],signals:["window of fixed length","same letters in any order","compare letter counts, not strings"],prerequisites:["peak-stretch","tidy-tape"],parSeconds:840,complexity:{time:"O(n)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.25,perf:.35},similar:[{name:"Find All Anagrams in a String",lcNumber:438},{name:"Permutation in String",lcNumber:567}],spec:{kind:"function",name:"countShuffles",returns:"int",params:[{type:"string",name:"text"},{type:"string",name:"word"}]}},statement:'# Shuffle Spotter\n\nA puzzle booth prints a long banner `text` and shows a short `word`. A stretch of the banner is a **shuffle** of the word when it has the same length as the word and uses exactly the same letters the same number of times, in any order (`"tea"` and `"eat"` are shuffles of each other).\n\nCount how many positions `i` have the stretch `text[i .. i + word.length() - 1]` equal to a shuffle of `word`. Overlapping stretches all count.\n\n## Examples\n\n- `text = "cbaebabacd"`, `word = "abc"` gives `2` (positions 0 and 6: `"cba"` and `"bac"`).\n- `text = "aaaa"`, `word = "aa"` gives `3` (the stretch at positions 0, 1 and 2).\n- `text = "xyz"`, `word = "abcd"` gives `0` (the word is longer than the banner).\n\n## Constraints\n\n- `0 <= text.length() <= 100000`\n- `1 <= word.length() <= 100000`\n- Both strings contain only `a` to `z`.\n',editorial:'## Signals\n"Does this stretch use the same letters in any order?" The stretch length is fixed (the word\'s length) and the property depends only on letter counts. Fixed length plus a count-based property is a fixed-size window with a frequency table.\n\n## Brute force\nFor each start, copy the stretch, sort it and compare with the sorted word. O(n * m log m) time, O(m) space. With `n = 100000` and `m = 50000` that is about 50000 windows of 50000 letters sorted each, far beyond the limit.\n\n## Key insight\nTwo multisets of letters are equal iff their 26 counters are equal. Sliding the window by one changes two counters, so the table can be kept up to date in O(1) and compared in O(26).\n\n## Optimal\nBuild `need[26]` from the word. Walk `i` over the banner: add `text[i]` to `window`; if the window now holds more than `m` letters (`i >= m`), remove `text[i - m]`; once `i >= m - 1`, compare `window == need` and count a match. Time O(26 * n) which is O(n); space O(1).\n\n## C++ walkthrough\n`array<int, 26>` has value semantics and a built-in `operator==`, so `window == need` is one readable line; `{}` zero-initialises it. Use `ch - \'a\'` as the index. Return `0` up front when `m > n`, otherwise the indices `i - m` and the full-window test need care. Cast `size()` to `int` before comparing or subtracting.\n\n## Common bugs\nLooping to `n - 1` and never checking the last window; removing `text[i - m - 1]` (off by one on the departing letter); comparing only which letters occur instead of how many (`"aab"` vs `"abb"`); counting windows before they reach full length; sorting every window and timing out.\n\n## Follow-ups\nReturn the starting positions instead of the count. Keep a `matches` counter of letters whose counts agree, so each slide is O(1) instead of O(26). Allow any Unicode alphabet (use a hash map for counts). Allow at most one differing letter.\n\n## Similar problems\nFind All Anagrams in a String (LeetCode 438), Permutation in String (LeetCode 567).\n',reference:"class Solution {\npublic:\n    int countShuffles(string text, string word) {\n        const int n = static_cast<int>(text.size());\n        const int m = static_cast<int>(word.size());\n        if (m > n) return 0;\n        array<int, 26> need{};    // letters the word demands\n        array<int, 26> window{};  // letters currently inside text[i - m + 1 .. i]\n        for (const char ch : word) ++need[ch - 'a'];\n        int found = 0;\n        for (int i = 0; i < n; ++i) {\n            ++window[text[i] - 'a'];                 // newcomer on the right\n            if (i >= m) --window[text[i - m] - 'a'];  // the letter that just left on the left\n            if (i >= m - 1 && window == need) ++found;  // a full-size window with equal counts\n        }\n        return found;\n    }\n};\n",hints:"## Nudge\nTwo stretches are shuffles of each other exactly when every letter appears the same number of times in both. How many numbers is that to compare, and how does the next stretch differ from the current one?\n\n## Approach\nCount the letters of `word` once. Slide a window of the same length over `text`, keeping its letter counts: one letter enters on the right, one leaves on the left. After each slide, check whether the two count tables are equal.\n\n## Key insight\nComparing 26 counters is O(1), so the whole scan is O(n) however long the word is. Sorting each window (or comparing it as a string) costs O(m log m) per position and times out. Check the window only once it has full length, and mind which index leaves: it is `i - m`, not `i - m - 1`.\n",loadTests:async()=>(await e.A(52396)).default},"tidy-tape":{meta:r.f,statement:'# Tidy Tape\n\nA label printer prints one lowercase letter per tick onto a long tape, given as the string `tape`. A stretch of consecutive letters is **tidy** if no letter appears more than `m` times inside it.\n\nReturn the length of the longest tidy stretch. (With `m = 1` this asks for the longest stretch of all-different letters.)\n\n## Examples\n\n- `tape = "abcabcbb"`, `m = 1` gives `3` (`"abc"`).\n- `tape = "aabaabaa"`, `m = 2` gives `4` (`"baab"`; every stretch of 5 holds at least three `a`).\n- `tape = "zzzz"`, `m = 10` gives `4`.\n\n## Constraints\n\n- `0 <= tape.length() <= 100000`\n- `tape` contains only `a` to `z`.\n- `1 <= m <= 100000`\n',editorial:'## Signals\n"Longest contiguous stretch" plus a rule that gets harder to satisfy as the stretch grows and easier as it shrinks (a count limit). Any sub-stretch of a tidy stretch is tidy, so the condition is monotone: the textbook variable-size sliding window.\n\n## Brute force\nTry every start and end, count letters, check the limit. O(n^3) naively, O(n^2) if you stop at the first violation per start. The quadratic version still does about 5 * 10^9 steps for `n = 100000` when the limit is never hit, which times out.\n\n## Key insight\nTwo pointers that only move right. When adding `tape[right]` pushes its count above `m`, the only way to repair the stretch is to drop letters from the left until that count is back to `m`. The left edge never needs to move backwards, because a smaller `right` already had its best answer recorded.\n\n## Optimal\nFor each `right`, increment its letter\'s count; while that count exceeds `m`, decrement the count of `tape[left]` and advance `left`; then record `right - left + 1`. Each index is added once and removed at most once: O(n) time, O(1) space (26 counters).\n\n## C++ walkthrough\n`int count[26] = {}` zero-initialises the array. Index with `ch - \'a\'`. Cast `size()` to `int` once for the loop bound. Use `while`, not `if`, for the shrink step.\n\n## Common bugs\n`if` instead of `while` (shrinks by one and leaves the window invalid); resetting the whole window when the limit is hit instead of dropping from the left; recording `right - left` (off by one); checking the limit on every letter instead of only the new one (still correct but slower to reason about).\n\n## Follow-ups\nReturn the stretch itself (track the best `left`). Allow `m` to differ per letter. For a stream, what is the memory cost? Compare with "at most K different letters" (a distinct counter instead of a per-letter limit).\n\n## Similar problems\nLongest Substring Without Repeating Characters (LeetCode 3).\n',reference:"class Solution {\npublic:\n    int longestTidy(string tape, int m) {\n        int count[26] = {};  // occurrences of each letter inside the window [left, right]\n        int left = 0;\n        int best = 0;\n        for (int right = 0; right < static_cast<int>(tape.size()); ++right) {\n            const int c = tape[right] - 'a';\n            ++count[c];\n            while (count[c] > m) {  // only the new letter can be over the limit\n                --count[tape[left] - 'a'];\n                ++left;\n            }\n            best = max(best, right - left + 1);\n        }\n        return best;\n    }\n};\n",hints:"## Nudge\nIf a stretch is tidy, is every stretch inside it tidy too? What does that suggest when a stretch stops being tidy?\n\n## Approach\nGrow the stretch one letter at a time on the right. If the letter you just added now appears more than `m` times, move the left edge forward until it appears at most `m` times again.\n\n## Key insight\nKeep 26 counts. Only the newly added letter can break the rule, so the shrink loop only needs to wait for that one count to drop. It must be a `while`, not an `if`: the letter leaving on the left is often a different letter. Each index enters and leaves once, so the scan is O(n).\n",loadTests:async()=>(await e.A(99570)).default},"tight-patch":{meta:{id:"tight-patch",region:"R3",title:"Tight Patch",difficulty:"M",patterns:["sliding-window"],signals:["shortest contiguous stretch","sum at least target","all values positive so the sum only grows"],prerequisites:["peak-stretch"],parSeconds:840,complexity:{time:"O(n)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.25,perf:.35},similar:[{name:"Minimum Size Subarray Sum",lcNumber:209}],spec:{kind:"function",name:"tightPatch",returns:"int",params:[{type:"vector<int>",name:"power"},{type:"long long",name:"need"}]}},statement:"# Tight Patch\n\nA solar array has panels in a row, and `power[i]` is the output of panel `i` (always positive). You want to wire up a **patch**: a run of consecutive panels whose total output is at least `need`.\n\nReturn the number of panels in the shortest patch that works, or `0` if even the whole row falls short.\n\n## Examples\n\n- `power = [2, 3, 1, 2, 4, 3]`, `need = 7` gives `2` (the patch `[4, 3]`).\n- `power = [1, 1, 1]`, `need = 10` gives `0`.\n- `power = [8]`, `need = 8` gives `1`.\n\n## Constraints\n\n- `0 <= power.size() <= 100000`\n- `1 <= power[i] <= 1000`\n- `1 <= need <= 1000000000`\n",editorial:'## Signals\n"Shortest contiguous stretch with sum at least a target" and every value is positive. Positivity makes the sum monotone: extending never lowers it, shrinking never raises it. That is the green light for a variable sliding window.\n\n## Brute force\nFor each start, extend until the sum reaches `need`. O(n^2) time, O(1) space; when `need` is unreachable (say a row of ones and `need = 10^9`) every start scans to the end, about 5 * 10^9 steps for `n = 100000`.\n\n## Key insight\nPanel outputs are positive, so prefix sums strictly increase. The shortest working patch ending at `right` starts at the largest `left` whose sum is still at least `need`, and that `left` never decreases as `right` grows. So both pointers only move forward.\n\n## Optimal\nMaintain `sum` of `power[left..right]`. After adding `power[right]`, while `sum >= need`: record `right - left + 1`, subtract `power[left]`, advance `left`. Return the best, or `0` when none. Time O(n), space O(1).\n\n## C++ walkthrough\n`need` can be up to 10^9 and the window sum up to 10^8; `long long` is the safe default for sums. Use `n + 1` as the sentinel for "not found" so a patch of full length `n` is still distinguishable. Remember that `vector::size()` is unsigned: cast before doing arithmetic with it.\n\n## Common bugs\n`if` instead of `while` for the shrink step; `>` instead of `>=`; returning the sentinel (or `n`) when no patch exists; resetting `left` to `right` after a success; using this approach when values can be negative (it breaks: see the Exact Stretches problem in Array Atoll, and the prefix-plus-deque problem later in this region).\n\n## Follow-ups\nWhat if values can be zero? (The same loop still works.) What if values can be negative? (Prefix sums with a monotonic deque.) Return the patch\'s position. Count all minimal patches.\n\n## Similar problems\nMinimum Size Subarray Sum (LeetCode 209).\n',reference:'class Solution {\npublic:\n    int tightPatch(vector<int> power, long long need) {\n        const int n = static_cast<int>(power.size());\n        int best = n + 1;  // n + 1 means "no patch found yet"\n        long long sum = 0;  // total of power[left..right]\n        int left = 0;\n        for (int right = 0; right < n; ++right) {\n            sum += power[right];\n            while (sum >= need) {  // as short as possible: drop from the left while it still works\n                best = min(best, right - left + 1);\n                sum -= power[left];\n                ++left;\n            }\n        }\n        return best == n + 1 ? 0 : best;\n    }\n};\n',hints:'## Nudge\nEvery panel adds power, so adding a panel can only help and removing one can only hurt. How can you use that to avoid trying every start?\n\n## Approach\nExtend the right end one panel at a time. As soon as the total reaches `need`, the current patch works: record its length, then shrink from the left while it still works.\n\n## Key insight\nShrinking is a loop, not a single step: one large newcomer can make several old panels unnecessary. Because all values are positive, the left edge never has to move back, so each panel enters and leaves once: O(n). Use `long long` for the total and a sentinel for "no patch yet".\n',loadTests:async()=>(await e.A(82492)).default},"brick-gap":{meta:{id:"brick-gap",region:"R4",title:"Brick Gap",difficulty:"M",patterns:["hash-design"],signals:["count how many rows share a boundary","prefix sums as keys","maximise a shared coordinate"],prerequisites:["twin-scripts"],parSeconds:900,complexity:{time:"O(B)",space:"O(B)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.25,perf:.35},similar:[{name:"Brick Wall",lcNumber:554}],spec:{kind:"function",name:"fewestCrossed",returns:"int",params:[{type:"vector<vector<int>>",name:"rows"}]}},statement:"# Brick Gap\n\nA wall is built from rows of bricks. Every row has the same total width, and each brick is one unit tall. `rows[i]` lists the widths of the bricks in row `i`, from left to right.\n\nYou draw a straight vertical line from the top of the wall to the bottom. The line **crosses** a brick if it passes strictly inside it. Passing exactly along the edge between two bricks crosses nothing. The line must stay strictly inside the wall: running along the far left or far right side is not allowed.\n\nReturn the fewest bricks the line can cross.\n\n## Examples\n\n- `rows = [[1,2,2,1],[3,1,2],[1,3,2],[2,4],[3,1,2],[1,3,1,1]]` gives `2`.\n- `rows = [[1],[1],[1]]` gives `3` (no interior edge exists, so every row is crossed).\n- `rows = [[2,2],[1,3]]` gives `1`.\n\n## Constraints\n\n- `1 <= rows.size() <= 10000`\n- `1 <= rows[i].size() <= 10000`, and the total number of bricks is at most `20000`\n- `1 <= rows[i][j] <= 1000000000`\n- All rows have the same total width, which may exceed the range of a 32-bit `int`.\n",editorial:'## Signals\n"Many rows, pick one coordinate shared by as many as possible" is frequency counting over a derived key. The key here is the prefix sum, a boundary position.\n\n## Brute force\nCollect every interior boundary position that appears in any row, then for each candidate scan every row to see whether it has an edge there. With B total bricks and R rows that is O(B · B) in the worst case (or O(B · R) with a set per row), far too slow at 20,000 bricks and 10,000 rows when positions are all distinct.\n\n## Key insight\nA row with an edge at `x` costs the line nothing; every other row costs exactly one brick. So crossings at `x` equal `R - (rows with an edge at x)`, and minimising crossings means maximising the number of rows that share an edge position.\n\n## Optimal\nFor each row, compute prefix sums of its widths, skipping the last (the right wall). Increment `edges[prefix]` for each. The answer is `R - max(edges)`; when there are no interior edges the maximum is 0 and the answer is `R`. Time O(B), space O(B) for the map.\n\n## C++ walkthrough\nPositions are `long long` because a row\'s total can pass 2^31 even though each brick fits an `int`. Each row has distinct prefix sums (widths are positive), so one row never counts the same edge twice. `unordered_map<long long,int>` with `++edges[pos]` increments and returns in one expression; for adversarial inputs you could use a sorted vector of all positions and count runs instead.\n\n## Common bugs\nIncluding the final prefix sum (the wall itself) so a single column looks free; overflowing `int` on the running sum; returning the best count instead of `R - best`.\n\n## Follow-ups\nWhat if the line may also be diagonal? What if bricks may be removed from the middle of a row? How would you stream rows without storing them?\n\n## Similar problems\nBrick Wall (LeetCode 554) is this problem.\n',reference:"class Solution {\npublic:\n    int fewestCrossed(vector<vector<int>> rows) {\n        // edges[x] = how many rows have a brick boundary at distance x from the left.\n        unordered_map<long long, int> edges;\n        int best = 0;\n        for (const auto& row : rows) {\n            long long pos = 0;  // The total width can exceed int, so use long long.\n            for (size_t j = 0; j + 1 < row.size(); ++j) {  // Skip the last brick: the right wall is not allowed.\n                pos += row[j];\n                best = max(best, ++edges[pos]);\n            }\n        }\n        return static_cast<int>(rows.size()) - best;\n    }\n};\n",hints:'## Nudge\nA line that crosses fewer bricks must run along as many brick edges as possible. Which edge is shared by the most rows?\n\n## Approach\nFor each row, walk its bricks and keep a running sum of widths. Each running sum (except the last, the right wall) is an edge position. Count how many rows have an edge at each position, using a hash map. The answer is the number of rows minus the largest count.\n\n## Key insight\nRows are independent, so "number of rows with an edge at x" can be accumulated row by row. Use `long long` for positions: the total width can exceed 32 bits. Never count the final prefix, since the line may not run along the wall.\n',loadTests:async()=>(await e.A(229)).default},"crate-variety":{meta:{id:"crate-variety",region:"R4",title:"Crate Variety",difficulty:"M",patterns:["hash-design","sliding-window"],signals:["longest stretch with at most K kinds","hash map as window state","shrink when too many distinct"],prerequisites:["twin-scripts","tidy-tape"],parSeconds:780,complexity:{time:"O(n)",space:"O(k)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.25,perf:.35},similar:[{name:"Longest Substring with At Most K Distinct Characters",lcNumber:340}],spec:{kind:"function",name:"longestVariety",returns:"int",params:[{type:"vector<int>",name:"kinds"},{type:"int",name:"k"}]}},statement:"# Crate Variety\n\nA conveyor carries crates in a row. `kinds[i]` is the kind code of the `i`-th crate. You may grab one **contiguous** stretch of crates, but your bag can hold at most `k` different kinds.\n\nReturn the length of the longest stretch you can grab.\n\n## Examples\n\n- `kinds = [1,2,1,3,3,2]`, `k = 2` gives `3` (the stretch `[1,2,1]`, or `[3,3,2]`).\n- `kinds = [7,7,7]`, `k = 1` gives `3`.\n- `kinds = [4,5]`, `k = 0` gives `0`.\n\n## Constraints\n\n- `0 <= kinds.size() <= 100000`\n- `-1000000000 <= kinds[i] <= 1000000000`\n- `0 <= k <= 100000`\n",editorial:'## Signals\n"Longest contiguous stretch with at most K distinct things" is a variable sliding window whose state is a frequency map. The state cannot be a single integer, so the hash map is part of the invariant.\n\n## Brute force\nFor each start, extend to the right with a set until it exceeds `k` kinds. O(n²) time in the worst case (few kinds, long runs), O(k) space.\n\n## Key insight\nIf a window has at most `k` kinds, every sub-window does too. So for each right end there is a smallest valid left end, and that left end never moves backwards as the right end advances. Two pointers visit each crate at most twice.\n\n## Optimal\nMaintain `inBag[kind]` = count in the window. Add `kinds[right]`; while `inBag.size() > k`, remove `kinds[left]` (erase the key when its count hits 0) and advance `left`. Update the answer with `right - left + 1`. Time O(n) expected, space O(k). With `k = 0` the window is always emptied, so the answer is 0.\n\n## C++ walkthrough\n`inBag.size()` counts keys, so zero counts must be erased. `unordered_map` is expected O(1) per operation; an adversary can craft integer keys that collide in some implementations, so for hostile inputs use a custom hash or a sorted compression of the codes to a dense array.\n\n## Common bugs\nLeaving zero-count keys in the map; testing `== k` instead of `<= k`; mishandling `k = 0` or an empty array.\n\n## Follow-ups\nExactly K kinds: compute at-most(K) minus at-most(K-1) for counting subarrays. Stream version: what if the crates arrive forever and you only need the current best?\n\n## Similar problems\nLongest Substring with At Most K Distinct Characters (LeetCode 340); Fruit Into Baskets (LeetCode 904) is the `k = 2` case.\n',reference:"class Solution {\npublic:\n    int longestVariety(vector<int> kinds, int k) {\n        unordered_map<int, int> inBag;  // kind -> how many crates of it are in the window\n        int best = 0;\n        int left = 0;\n        for (int right = 0; right < static_cast<int>(kinds.size()); ++right) {\n            ++inBag[kinds[right]];\n            while (static_cast<int>(inBag.size()) > k) {  // Invariant after this loop: at most k kinds.\n                if (--inBag[kinds[left]] == 0) inBag.erase(kinds[left]);\n                ++left;\n            }\n            best = max(best, right - left + 1);\n        }\n        return best;\n    }\n};\n",hints:"## Nudge\nIf a stretch has too many kinds, what does shrinking it from the left do to the count of kinds? Does a shorter stretch ever make things worse?\n\n## Approach\nGrow the right end one crate at a time, counting each kind in a hash map. While the map holds more than `k` kinds, drop crates from the left end until it does not. Record the window length after each step.\n\n## Key insight\nRemoving crates only ever lowers the number of kinds, so the window condition is monotone and two pointers suffice. When a count reaches zero you must erase the key, because the number of kinds is the map's size.\n",loadTests:async()=>(await e.A(6922)).default},"drum-bag":{meta:l,statement:'# Drum Bag\n\nA raffle drum holds distinct tickets, each with an integer number. A drawer picks a ticket by *slot*, so the drum must keep its tickets in a packed row of slots `0, 1, ..., size-1` and answer "what is in slot `i`?" instantly.\n\nDesign `DrumBag` with these operations, each in **average O(1)** time:\n\n- `bool insert(int val)`: if ticket `val` is already in the drum, do nothing and return `false`. Otherwise put it in the **next free slot** (the end of the row) and return `true`.\n- `bool erase(int val)`: if `val` is not in the drum, return `false`. Otherwise remove it, and close the gap by **moving the ticket from the last slot into the freed slot** (if the removed ticket was itself last, nothing moves). Return `true`.\n- `int slot(int i)`: return the ticket in slot `i`. Always called with `0 <= i < size()`.\n- `int size()`: return the number of tickets.\n\nBecause the slot rules are fixed, the contents of every slot are fully determined by the sequence of operations.\n\n## Example\n\n```\ninsert(5) -> true     slots: [5]\ninsert(8) -> true     slots: [5, 8]\ninsert(5) -> false\ninsert(2) -> true     slots: [5, 8, 2]\nerase(5)  -> true     slots: [2, 8]      (2 moved into slot 0)\nslot(0)   -> 2\nsize()    -> 2\n```\n\n## Constraints\n\n- Up to `200000` operations in total.\n- `-1000000000 <= val <= 1000000000`.\n',editorial:"## Signals\n\"O(1) insert, delete and access by position\" asks for two structures that each cover the other's weakness: an array is fast by index but slow to search or delete in the middle; a hash map finds by value but has no order. Combine them and keep them in sync.\n\n## Brute force\nA single vector with linear search for membership and removal. Insert and erase cost O(n) each, so 200,000 operations on a large drum is O(n²) in the worst case.\n\n## Key insight\nOrder among the slots does not matter for anything except determinism, so a delete can reorder: swap the victim with the last element and shrink the array. That is O(1) on a vector. The only price is bookkeeping, since one ticket changes slot and the map must follow.\n\n## Optimal\n`slots` holds the tickets; `where[ticket]` is its index. `insert` checks `where`, appends, records the index. `erase` finds the hole, writes the last ticket there, sets `where[last] = hole`, pops the back, and finally erases `val` from `where`. `slot(i)` is `slots[i]`. Every operation is expected time O(1); space O(n).\n\n## C++ walkthrough\n`unordered_map::find` once and reuse the iterator. The order of the last two lines in `erase` matters: when the erased ticket was last, `last == val`, so `where[last] = hole` re-creates its key and the final `where.erase(val)` removes it again. Doing the erase first re-inserts a dead key. `slots_.back()` on an empty vector is undefined, but `erase` only reaches it after a successful lookup, so the vector is non-empty.\n\n## Common bugs\nForgetting to update the moved ticket's slot (later erases hit the wrong index); the erase-then-move order above; using `vector::erase`, which shifts and costs O(n); returning from `insert` after changing the map but not the vector.\n\n## Follow-ups\nThe classic version returns a *random* element: pick `rand() % size()` and return `slots[that]`, which is uniform because every ticket occupies exactly one slot. Allow duplicates: the map's value becomes a set of indices (the harder LeetCode 381). Anti-hash inputs: replace `unordered_map` with a map using a randomised hash.\n\n## Similar problems\nInsert Delete GetRandom O(1) (LeetCode 380) is this design with a random pick instead of a deterministic `slot(i)`; Insert Delete GetRandom O(1) with duplicates is LeetCode 381.\n",reference:"class DrumBag {\npublic:\n    DrumBag() = default;\n\n    bool insert(int val) {\n        if (where_.count(val)) return false;\n        where_[val] = static_cast<int>(slots_.size());\n        slots_.push_back(val);\n        return true;\n    }\n\n    bool erase(int val) {\n        const auto it = where_.find(val);\n        if (it == where_.end()) return false;\n        const int hole = it->second;\n        const int last = slots_.back();\n        // Move the last ticket into the hole, fix its recorded slot, then drop the old last slot.\n        // Order matters when val == last: erase the key after the move so it does not come back.\n        slots_[hole] = last;\n        where_[last] = hole;\n        slots_.pop_back();\n        where_.erase(val);\n        return true;\n    }\n\n    int slot(int i) const { return slots_[i]; }\n\n    int size() const { return static_cast<int>(slots_.size()); }\n\nprivate:\n    vector<int> slots_;                 // Packed row of tickets.\n    unordered_map<int, int> where_;     // ticket -> its slot.\n};\n",hints:'## Nudge\nRemoving from the middle of an array is slow because everything after it shifts. Which element can you remove from an array in O(1)? And how could you make the hole disappear without shifting?\n\n## Approach\nStore tickets in a vector (the slots) and keep a hash map from ticket to its slot. To erase, copy the last ticket into the erased ticket\'s slot, update the map for that moved ticket, then `pop_back` and remove the erased key.\n\n## Key insight\nThe map must always say where each ticket really is, so every move updates it. The special case is erasing the last ticket itself: it "moves onto itself", so remove its key *after* the move, or it will reappear in the map.\n',loadTests:async()=>(await e.A(21766)).default},"echo-strand":{meta:h.f,statement:'# Echo Strand\n\nA lab records a strand as a string of the four letters `A`, `C`, `G` and `T`. An **echo** is a block of exactly `k` consecutive letters that occurs at **two or more different starting positions** (the occurrences may overlap).\n\nReturn every distinct echo exactly once, sorted in ascending alphabetical (lexicographic) order.\n\n## Example\n\n```\nstrand = "ACGACGAC", k = 3\nblocks:  ACG(0)  CGA(1)  GAC(2)  ACG(3)  CGA(4)  GAC(5)\nechoes:  ["ACG", "CGA", "GAC"]\n\nstrand = "AAAAAA", k = 2   ->  ["AA"]     (starts 0..4, overlapping)\nstrand = "ACGT",   k = 2   ->  []\n```\n\n## Constraints\n\n- `0 <= strand.length() <= 100000`; every letter is `A`, `C`, `G` or `T`.\n- `1 <= k <= 30`.\n- If `k > strand.length()` there are no blocks and the answer is empty.\n',editorial:'## Signals\n"Fixed-length substrings that appear again" means one question per window position: have I seen this block before? Any answer to that needs a key for the block. The fixed length is the hint that the key can be *updated* as the window slides instead of rebuilt.\n\n## Brute force\nFor every start, compare the block with every later block: O(n²·k) character work, or O(n²) block comparisons at best. With n up to 100,000 that is far too slow. Putting each `substr` in an `unordered_set<string>` is O(n·k) time and memory, which passes here but wastes the structure of the problem.\n\n## Key insight\nThe alphabet has four letters, so each letter is two bits. A block of k <= 30 letters is a number below 2^60, and different blocks give different numbers: the encoding is exact. Sliding by one letter is `key = ((key << 2) | code(next)) & mask`, where `mask` keeps the low 2k bits. That is a rolling hash with no collisions. For a general alphabet you would use `key = (key * base + next - out * base^k) mod M` (Rabin–Karp) and verify matches, because modular hashes can collide.\n\n## Optimal\nSlide the key across the strand once. When the window is full (`i >= k - 1`), bump a counter for the key. Add the block to the answer exactly when its counter reaches 2, so a block seen five times is listed once. Sort at the end. Time O(n + r·k·log r) for r echoes (O(n) hashing plus sorting the output); space O(n).\n\n## C++ walkthrough\nUse `long long`: `1 << 60` overflows `int`, and `1LL << (2 * k)` is the safe way to build the mask (2k <= 60 < 63). `seen.reserve(n * 2)` avoids rehashing. The `if (++seen[key] == 2)` form both counts and de-duplicates. Take `substr` only when reporting, never per window.\n\n## Common bugs\nA 32-bit key (collides once k > 16); counting `>= 2` instead of `== 2` (duplicates in the output); forgetting to mask (stale high bits make every key unique); treating overlapping occurrences as invalid; returning an unsorted answer; `k > n` underflowing `n - k` when n is unsigned.\n\n## Follow-ups\nLarger alphabets or k > 30: polynomial rolling hash with a 64-bit modulus or two moduli, and verify candidates. Longest repeated substring: binary search on k, calling this check each time (the hard version in this region). Streaming: the same key update works one character at a time.\n\n## Similar problems\nRepeated DNA Sequences (LeetCode 187) fixes k = 10; Longest Duplicate Substring (LeetCode 1044) adds binary search over k.\n',reference:"class Solution {\npublic:\n    vector<string> echoes(string strand, int k) {\n        const int n = static_cast<int>(strand.size());\n        vector<string> answer;\n        if (k > n) return answer;\n\n        const auto code = [](char c) -> long long {\n            switch (c) {\n                case 'A': return 0;\n                case 'C': return 1;\n                case 'G': return 2;\n                default:  return 3;  // 'T'\n            }\n        };\n\n        // Each letter is 2 bits, so a block of k letters is 2k <= 60 bits: exact, no collisions.\n        const long long mask = (1LL << (2 * k)) - 1;\n        unordered_map<long long, int> seen;  // block key -> how many starts so far\n        seen.reserve(n * 2);\n        long long key = 0;\n        for (int i = 0; i < n; ++i) {\n            key = ((key << 2) | code(strand[i])) & mask;  // slide: add the new letter, drop the oldest\n            if (i < k - 1) continue;                      // window not full yet\n            if (++seen[key] == 2) answer.push_back(strand.substr(i - k + 1, k));  // report on the 2nd sighting only\n        }\n        sort(answer.begin(), answer.end());\n        return answer;\n    }\n};\n",hints:"## Nudge\nThere are about n blocks of length k. Copying each one into a string and hashing it costs O(k) per block. Can you get the next block's identity from the previous block's in O(1)?\n\n## Approach\nOnly four letters means two bits per letter, so a block of up to 30 letters fits in a 60-bit integer. Slide: shift the key left by 2, add the new letter's code, mask off the bits that fell out of the window. Count each key in a hash map (or remember which keys were seen once), and record a block when its count reaches 2.\n\n## Key insight\nThe encoding is exact (no collisions), so equal keys mean equal blocks. Use `long long` (or `unsigned long long`): 2k bits is up to 60, which overflows `int`. Build the answer from the keys you recorded, or from the substring at the first repeat, then sort.\n",loadTests:async()=>(await e.A(43978)).default},"locker-board":{meta:c,statement:"# Locker Board\n\nA hall has lockers numbered by arbitrary non-negative integers (up to a billion), far too many to give each its own hook. Build the board yourself **without** `unordered_map`, `map`, `set` or any other library associative container (`vector`, `list` and `forward_list` are fine).\n\nDesign `LockerBoard` with these operations, each in **average O(1)** time:\n\n- `void put(int key, int val)`: store `val` in locker `key`. If the locker already holds a value, replace it.\n- `int get(int key)`: return the value in locker `key`, or `-1` if the locker is empty.\n- `void remove(int key)`: empty locker `key`. Does nothing if it is already empty.\n- `int count()`: return how many lockers currently hold a value.\n\n## Example\n\n```\nput(7, 70)    get(7) -> 70\nput(7, 71)    get(7) -> 71     (replaced, not duplicated)\nput(1000007, 5)               count() -> 2\nremove(7)     get(7) -> -1     count() -> 1\nremove(7)                      count() -> 1\n```\n\n## Constraints\n\n- Up to `200000` operations in total.\n- `0 <= key <= 1000000000`, `0 <= val <= 1000000000`.\n",editorial:'## Signals\n"Implement the map yourself" is a data-structure-internals question. Interviewers check three things: do you know why keys are reduced to a bucket index, what you do when two keys collide, and what keeps the structure fast as it grows.\n\n## Brute force\nOne vector of pairs with a linear scan for every operation. Correct, but each operation is O(n), so 200,000 operations on a large board is about 10^10 pair comparisons in the worst case.\n\n## Key insight\nA hash function maps a huge key space onto a small array of buckets; collisions are unavoidable, so each bucket holds a short chain. Lookup cost is the chain length, which averages `count / buckets` (the load factor). Keep that near 1 by doubling the bucket array when it is exceeded and re-inserting every entry. One rehash is O(n), but doubling means total rehash work over n inserts is O(n), so `put` is amortised O(1).\n\n## Optimal\n`put`: find the bucket (`key % buckets`), scan the chain, overwrite if the key exists, otherwise append and bump the count; grow if `count > buckets`. `get`: scan the chain, return `-1` on a miss. `remove`: find the pair, overwrite it with the chain\'s last pair and `pop_back` (chain order does not matter), decrement the count. Expected time O(1) per operation; space O(n).\n\n## C++ walkthrough\nUse `vector<pair<int,int>>` as the chain: it is cache-friendlier than `list`. `size_t` for indices avoids signed `%` surprises (keys here are non-negative; with negative keys `key % B` can be negative). `buckets_ = move(bigger)` hands over the new array without copying. `constexpr` for the initial size keeps the magic number named. `get` is `const`; note that `operator[]`-style access is not available on a hand-made structure, so a miss must not insert anything.\n\n## Common bugs\n`put` appending a second pair for an existing key (two values per key, wrong `count`); using `0` or `-1` as an in-band "empty" marker when `0` is a legal value; never growing, so chains degrade to O(n); forgetting to decrement the count on remove (or counting a replace as new); rehashing with the old modulus; erasing from a vector while an iterator into it is still in use.\n\n## Follow-ups\nOpen addressing (linear probing) needs tombstones for `remove`, and its load factor must stay below about 0.7. Power-of-two bucket counts replace `%` with a mask but need a mixed hash, or low bits collide. Defend against adversarial keys with a randomised seed. Thread safety: lock striping per bucket.\n\n## Similar problems\nDesign HashMap (LeetCode 706), Design HashSet (LeetCode 705); LRU Cache (LeetCode 146) combines this map with a list.\n',reference:"class LockerBoard {\npublic:\n    LockerBoard() : buckets_(kInitialBuckets) {}\n\n    void put(int key, int val) {\n        auto& chain = buckets_[indexOf(key, buckets_.size())];\n        for (auto& entry : chain) {\n            if (entry.first == key) { entry.second = val; return; }  // replace, never duplicate\n        }\n        chain.emplace_back(key, val);\n        ++count_;\n        if (count_ > buckets_.size()) grow();  // keep load factor <= 1 so chains stay short\n    }\n\n    int get(int key) const {\n        for (const auto& entry : buckets_[indexOf(key, buckets_.size())]) {\n            if (entry.first == key) return entry.second;\n        }\n        return -1;\n    }\n\n    void remove(int key) {\n        auto& chain = buckets_[indexOf(key, buckets_.size())];\n        for (auto it = chain.begin(); it != chain.end(); ++it) {\n            if (it->first == key) {\n                *it = chain.back();  // order inside a chain is irrelevant: swap-with-last, then pop\n                chain.pop_back();\n                --count_;\n                return;\n            }\n        }\n    }\n\n    int count() const { return static_cast<int>(count_); }\n\nprivate:\n    static constexpr size_t kInitialBuckets = 8;\n    using Chain = vector<pair<int, int>>;\n\n    static size_t indexOf(int key, size_t buckets) { return static_cast<size_t>(key) % buckets; }\n\n    void grow() {\n        vector<Chain> bigger(buckets_.size() * 2);\n        for (const auto& chain : buckets_) {\n            for (const auto& entry : chain) bigger[indexOf(entry.first, bigger.size())].push_back(entry);\n        }\n        buckets_ = move(bigger);\n    }\n\n    vector<Chain> buckets_;\n    size_t count_ = 0;\n};\n",hints:"## Nudge\nYou cannot index an array of a billion lockers, but you can squeeze every key into a small range with `key % B`. What happens when two keys land on the same number?\n\n## Approach\nKeep a vector of `B` buckets, each a short list of `(key, value)` pairs (separate chaining). `put` scans the bucket for the key and overwrites or appends; `get` scans; `remove` erases the matching pair. Track a running count. Choose `B` as a prime near the expected size.\n\n## Key insight\nChains stay short only if the table grows with the data. When `count / B` passes a load factor (about 1), allocate twice as many buckets and re-insert everything. Each rehash costs O(n) but happens after geometrically spaced growth, so the amortised cost per `put` is O(1).\n",loadTests:async()=>(await e.A(31059)).default},"longest-echo":{meta:{id:"longest-echo",region:"R4",title:"Longest Echo",difficulty:"H",patterns:["hash-design","binary-search"],signals:["longest block that occurs twice","if length L repeats then L-1 repeats (monotone)","check one length in O(n) with a rolling hash"],prerequisites:["echo-strand"],parSeconds:1800,complexity:{time:"O(n log n)",space:"O(n)"},timeLimitMs:1500,testWeights:{basic:.15,edge:.15,adversarial:.3,perf:.4},similar:[{name:"Longest Duplicate Substring",lcNumber:1044}],spec:{kind:"function",name:"longestEcho",returns:"string",params:[{type:"string",name:"strand"}]}},statement:'# Longest Echo\n\nA strand is a string of lowercase letters. An **echo** is a block (a run of consecutive letters) that occurs at **two or more different starting positions**; the occurrences may overlap.\n\nReturn the **longest** echo. If several echoes share the longest length, return the one whose **second occurrence starts earliest**. If the strand has no echo, return the empty string.\n\n## Example\n\n```\nstrand = "banana"          ->  "ana"     (starts 1 and 3, overlapping)\nstrand = "abcd"            ->  ""\nstrand = "xyabcabcz"       ->  "abc"     (starts 2 and 5)\nstrand = "aabaab"          ->  "aab"     (starts 0 and 3)\nstrand = "abab" + "cdcd"   ->  "ab"      (length 2: "ab" repeats at 2, "cd" repeats at 6; "ab" completes first)\nstrand = "abcdcdab"        ->  "cd"      ("ab" and "cd" both have length 2; "cd" repeats at 4, "ab" only at 6)\n```\n\n## Constraints\n\n- `0 <= strand.length() <= 100000`; every letter is `a` to `z`.\n- Only blocks that occur at two or more *different* starting positions count; a block is never an echo of itself.\n',editorial:'## Signals\n"Longest block that appears twice" asks for a maximum length with a yes/no test per length, and the test is monotone: a repeat of length L contains a repeat of length L-1. Whenever the answer is a number with a monotone predicate, binary search on the answer is the shape. The second signal is the predicate itself: "does any block of length L occur twice?" needs a key per block, and a rolling hash gives that key in O(1) per slide.\n\n## Brute force\nFor every length from n-1 down, compare every pair of start positions: O(n²) pairs per length, O(n³) comparisons overall (more with the O(L) compare). Even the better version, putting every `substr` in an `unordered_set<string>` for each length, costs O(n·L) per length and O(n²) for the whole descent, which is far too slow at n = 100,000.\n\n## Key insight\nTwo ideas compose. First, monotonicity lets you binary search L in [0, n): O(log n) checks instead of n. Second, one check is a single pass with a rolling hash: `h = h·B + next − out·B^L` (mod a prime), so each block\'s key costs O(1). Total O(n log n) time. The hash is a fingerprint, not an identity: two different blocks can share a hash, and an adversary can aim for it (a mod-2^64 hash breaks on a Thue–Morse strand). So use two moduli packed into one key, and on a match compare the actual letters before returning. The verification costs O(L) but only runs when the hashes already agree.\n\n## Optimal\n`lo = 0` (always achievable), `hi = n` (never achievable, a block of length n occurs once). While `hi - lo > 1`: test `mid`; if some start has a repeat, record that start and set `lo = mid`, else set `hi = mid`. In the check, keep `firstSeen[hash] = earliest start`. Scanning left to right, the first position whose block was seen before is the repeat that completes earliest, which is exactly the tie-break in the statement. Time O(n log n), space O(n).\n\n## C++ walkthrough\n`long long` for the arithmetic: `h·B` is about 10^18, so reduce after every multiply and add `M` before the final `%` when subtracting. `p = B^len` is rebuilt per check in O(len). Pack the two hashes as `h1·M2 + h2` (below 2^63). Reserve the map. Compare with `s.compare(a, len, s, b, len)` which avoids copying substrings. Return `substr(bestStart, lo)` only once, at the end.\n\n## Common bugs\nSetting `hi = n - 1` and so never testing length n-1 (`"aaaa"` has the echo `"aaa"`); an unverified hash match; a hash modulo 2^64 with natural overflow (Thue–Morse kills it); forgetting to subtract the outgoing letter, or taking a negative remainder; counting only non-overlapping occurrences; reporting the first occurrence instead of the repeat that completes earliest; rebuilding substrings per window (O(n·L)).\n\n## Follow-ups\nReturn all longest echoes; a suffix array plus LCP array gives the length in O(n log n) with no hashing risk (and a suffix automaton in O(n)); the same binary-search-plus-hash skeleton solves "longest common substring of two strings". Streaming input: a suffix automaton extends online, rolling hash does not.\n\n## Similar problems\nLongest Duplicate Substring (LeetCode 1044). Repeated DNA Sequences (LeetCode 187) is the fixed-length version (see Echo Strand in this region).\n',reference:"class Solution {\npublic:\n    string longestEcho(string strand) {\n        const int n = static_cast<int>(strand.size());\n        int lo = 0, hi = n;  // invariant: an echo of length lo exists (0 trivially); none of length hi exists\n        int bestStart = -1;\n        while (hi - lo > 1) {\n            const int mid = lo + (hi - lo) / 2;\n            const int start = firstRepeat(strand, mid);\n            if (start >= 0) { lo = mid; bestStart = start; }  // length mid repeats: try longer\n            else hi = mid;                                    // it does not: no longer length can\n        }\n        return lo == 0 ? string() : strand.substr(bestStart, lo);\n    }\n\nprivate:\n    static constexpr long long M1 = 1000000007LL, M2 = 998244353LL, B1 = 911382323LL % M1, B2 = 972663749LL % M2;\n\n    // Start of the earliest block of length len that already occurred before, or -1.\n    static int firstRepeat(const string& s, int len) {\n        const int n = static_cast<int>(s.size());\n        long long h1 = 0, h2 = 0, p1 = 1, p2 = 1;  // p = B^len, used to drop the outgoing letter\n        for (int i = 0; i < len; ++i) { p1 = p1 * B1 % M1; p2 = p2 * B2 % M2; }\n        unordered_map<long long, int> firstSeen;  // packed hash pair -> earliest start\n        firstSeen.reserve(n * 2);\n        for (int i = 0; i < n; ++i) {\n            h1 = (h1 * B1 + (s[i] - 'a' + 1)) % M1;\n            h2 = (h2 * B2 + (s[i] - 'a' + 1)) % M2;\n            if (i >= len) {  // remove s[i - len]\n                h1 = ((h1 - (s[i - len] - 'a' + 1) * p1) % M1 + M1) % M1;\n                h2 = ((h2 - (s[i - len] - 'a' + 1) * p2) % M2 + M2) % M2;\n            }\n            if (i < len - 1) continue;\n            const int start = i - len + 1;\n            const long long key = h1 * M2 + h2;  // < 1e9 * 1e9 + 1e9, fits in 63 bits\n            const auto it = firstSeen.find(key);\n            if (it == firstSeen.end()) firstSeen.emplace(key, start);\n            else if (s.compare(it->second, len, s, start, len) == 0) return start;  // verify: hashes can collide\n        }\n        return -1;\n    }\n};\n",hints:'## Nudge\nSuppose a block of length 7 occurs twice. Does a block of length 6 occur twice? Does length 8? What does that tell you about how to search for the longest length?\n\n## Approach\nBinary search on the length L. For a fixed L, slide a rolling hash across the strand: one O(1) update per position, store each block\'s hash in a map, and stop when a hash is already there. Move to a longer L if a repeat was found, otherwise a shorter one.\n\n## Key insight\n"Repeats at L" is monotone: if it repeats at L it repeats at L-1 (drop the last letter of both copies). That makes the check a yes/no predicate you can binary search, so the total is O(log n) rounds of an O(n) scan. Hashes can collide, so confirm a hash match by comparing the two blocks before you trust it.\n',loadTests:async()=>(await e.A(44576)).default},"twin-scripts":{meta:{id:"twin-scripts",region:"R4",title:"Twin Scripts",difficulty:"M",patterns:["hash-design"],signals:["same shape, different symbols","one-to-one mapping both ways","canonical form as key"],prerequisites:["scramble-check"],parSeconds:600,complexity:{time:"O(n)",space:"O(1)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.25,perf:.35},similar:[{name:"Isomorphic Strings",lcNumber:205}],spec:{kind:"function",name:"areTwins",returns:"bool",params:[{type:"string",name:"a"},{type:"string",name:"b"}]}},statement:'# Twin Scripts\n\nTwo scripts are **twins** if you can rename the symbols of one to get the other. A renaming must be a perfect pairing: the same symbol always becomes the same new symbol, and two different symbols never become the same new symbol. A symbol may be renamed to itself.\n\nGiven strings `a` and `b` of equal length, return `true` if they are twins.\n\n## Examples\n\n- `a = "paper"`, `b = "title"` gives `true` (`p→t`, `a→i`, `e→l`, `r→e`).\n- `a = "foo"`, `b = "bar"` gives `false` (`o` would have to become both `a` and `r`).\n- `a = "ab"`, `b = "cc"` gives `false` (`a` and `b` would both become `c`).\n\n## Constraints\n\n- `0 <= a.length() == b.length() <= 100000`\n- Both strings contain only lowercase letters and digits.\n',editorial:'## Signals\n"Rename symbols" and "same shape" mean the actual symbols do not matter, only the pattern of repeats. That pattern is a canonical form, and comparing canonical forms is a hash design problem.\n\n## Brute force\nFor every pair of positions `(i, j)`, require `a[i] == a[j]` exactly when `b[i] == b[j]`. This is correct but O(n²) time, too slow for 100,000 characters.\n\n## Key insight\nThe pairing is valid iff it is a bijection between the symbols that occur. Two symbols that must be paired always first appear at the same index, and every later appearance of one is an appearance of the other. Tracking the last position of each symbol in each string checks that without building the maps explicitly.\n\n## Optimal\nKeep `lastA[symbol]` and `lastB[symbol]`, both starting at 0. At index `i`, if `lastA[a[i]] != lastB[b[i]]` the two symbols disagree about their history, so return `false`. Otherwise set both to `i + 1`. Time O(n); space O(1) because the alphabet is fixed (128 slots per string).\n\n## C++ walkthrough\nIndex the arrays with `unsigned char` so a negative `char` can never produce a negative index. Storing `i + 1` keeps 0 free to mean "never seen". A pair of `unordered_map<char,char>` (forward and reverse) is the more explicit version and works for any alphabet.\n\n## Common bugs\nOnly checking the forward mapping; storing `i` instead of `i + 1` so the first position collides with "never seen"; forgetting the length check when lengths can differ.\n\n## Follow-ups\nGroup a list of words by their twin class: the key is the first-occurrence-index pattern (`"paper"` becomes `0,1,0,2,3`). Match a word pattern against a sentence of words: same idea with words as symbols.\n\n## Similar problems\nIsomorphic Strings (LeetCode 205) is this problem; Word Pattern (LeetCode 290) is the same bijection over words.\n',reference:'class Solution {\npublic:\n    bool areTwins(string a, string b) {\n        if (a.size() != b.size()) return false;\n        // Last position (+1) where each symbol was seen; 0 means "never".\n        // Two symbols are paired exactly when they always first appear together.\n        int lastA[128] = {};\n        int lastB[128] = {};\n        for (int i = 0; i < static_cast<int>(a.size()); ++i) {\n            const unsigned char x = a[i];\n            const unsigned char y = b[i];\n            if (lastA[x] != lastB[y]) return false;\n            lastA[x] = lastB[y] = i + 1;\n        }\n        return true;\n    }\n};\n',hints:'## Nudge\nIf `a[i]` and `a[j]` are the same symbol, what must be true of `b[i]` and `b[j]`? And the other way round?\n\n## Approach\nWalk both strings together. Remember, for each symbol of `a` and each symbol of `b`, the last position where it appeared. A pairing is valid at index `i` exactly when both symbols were last seen at the same place.\n\n## Key insight\nChecking only `a → b` misses two symbols that collapse onto one (`"ab"` vs `"cc"`). The mapping must be checked in both directions, and the "last seen" trick does both in one pass with two small arrays.\n',loadTests:async()=>(await e.A(46188)).default},"verse-match":{meta:d.f,statement:'# Verse Match\n\nA poet marks the rhyme of a poem with a **pattern**: one lowercase letter per line, where equal letters mean "these lines are the same word" and different letters mean "different words". A poem **fits** a pattern when letters and words pair up perfectly: the same letter always stands for the same word, and two different letters never stand for the same word.\n\nYou are given a `pattern` and a list of `words`. They may have different lengths. Return the length of the **longest prefix** (counting the first `L` letters against the first `L` words) that still fits. The empty prefix always fits.\n\n## Examples\n\n- `pattern = "abba"`, `words = ["sun","moon","moon","sun"]` gives `4`.\n- `pattern = "abba"`, `words = ["sun","moon","moon","star"]` gives `3` (`a` would have to be both `sun` and `star`).\n- `pattern = "abc"`, `words = ["x","x"]` gives `1` (`a` and `b` would both be `x`, and only two words exist).\n- `pattern = ""`, `words = ["a"]` gives `0`.\n\n## Constraints\n\n- `0 <= pattern.length() <= 100000`, `0 <= words.size() <= 100000`\n- Each word has `1` to `10` lowercase letters; the pattern has only lowercase letters.\n- The total number of word characters is at most `1000000`.\n',editorial:'## Signals\nLetters on one side, words on the other, and "the same must stay the same, different must stay different": a bijection check, the same shape as Twin Scripts with strings as one side\'s symbols. Asking for the longest prefix turns a yes/no into "where does it first fail".\n\n## Brute force\nFor each line `i`, compare it with every earlier line `j` and require `pattern[i] == pattern[j]` exactly when `words[i] == words[j]`. The first line that disagrees is the answer. O(n² · w) time, far too slow for 100,000 lines.\n\n## Key insight\nThe pairing is consistent so far exactly when each letter has had one word and each word one letter. Remembering the partner of every letter and every word lets you decide line `i` from two lookups instead of `i` comparisons.\n\n## Optimal\nWalk `n = min(pattern.size(), words.size())` lines. Look up `pattern[i]` in `wordOf` and `words[i]` in `letterOf`. If either exists with a different partner, return `i`. Otherwise store both directions. If the loop ends, return `n`. Time O(n · w) for hashing words of length at most `w` (here `w <= 10`); space O(n · w) in the worst case, though at most 26 letters means `wordOf` holds at most 26 entries.\n\n## C++ walkthrough\nUse `find` once and reuse the iterator rather than `count` followed by `operator[]`, and note that `operator[]` on a missing key inserts it, which would hide a mismatch. Compare strings with `!=`, which checks length and bytes. Because the key type for `letterOf` is `std::string`, no custom hash is needed.\n\n## Common bugs\nChecking only letter to word; returning 0 or `-1` on failure instead of the failing index; forgetting that the lists can have different lengths, so the loop bound must be the minimum; writing `wordOf[pattern[i]]` before checking, which silently creates an empty-string entry.\n\n## Follow-ups\nReturn the full yes/no for equal lengths (Word Pattern). Group many poems by their canonical pattern (first-occurrence indices as the key). Handle words that are not single-space separated.\n\n## Similar problems\nWord Pattern (LeetCode 290) is the yes/no version; Isomorphic Strings (LeetCode 205) is the same idea with characters.\n',reference:"class Solution {\npublic:\n    int matchingPrefix(string pattern, vector<string> words) {\n        const int n = static_cast<int>(min(pattern.size(), words.size()));\n        unordered_map<char, string> wordOf;   // letter -> the word it stands for\n        unordered_map<string, char> letterOf; // word -> the letter that stands for it\n        for (int i = 0; i < n; ++i) {\n            const auto w = wordOf.find(pattern[i]);\n            const auto l = letterOf.find(words[i]);\n            // Both directions must agree with what we already know, or line i breaks the fit.\n            if (w != wordOf.end() && w->second != words[i]) return i;\n            if (l != letterOf.end() && l->second != pattern[i]) return i;\n            wordOf[pattern[i]] = words[i];\n            letterOf[words[i]] = pattern[i];\n        }\n        return n;\n    }\n};\n",hints:"## Nudge\nWhen you reach line `i`, what do you need to remember about the letter `pattern[i]` and about the word `words[i]` from earlier lines?\n\n## Approach\nKeep two hash maps: letter to word, and word to letter. Walk the first `min(pattern length, word count)` lines. If either map already holds a different partner for this line, line `i` breaks the fit, so return `i`. Otherwise record the pair. If you finish, return that minimum length.\n\n## Key insight\nA one-way map accepts two letters standing for the same word. Both directions must be checked. Words are the keys of one map, so each lookup costs the word's length, which is why the bound is O(n · w) rather than O(n).\n",loadTests:async()=>(await e.A(23902)).default},"word-chain-window":{meta:{id:"word-chain-window",region:"R4",title:"Word Chain Window",difficulty:"H",patterns:["hash-design","sliding-window"],signals:["fixed-size window made of equal-length tokens","order does not matter, counts do","slide by whole tokens, once per alignment"],prerequisites:["crate-variety","longest-echo"],parSeconds:1800,complexity:{time:"O(n·w)",space:"O(k·w)"},timeLimitMs:1500,testWeights:{basic:.15,edge:.15,adversarial:.3,perf:.4},similar:[{name:"Substring with Concatenation of All Words",lcNumber:30}],spec:{kind:"function",name:"chainStarts",returns:"vector<int>",params:[{type:"string",name:"text"},{type:"vector<string>",name:"words"}]}},statement:'# Word Chain Window\n\nYou are given a long `text` of lowercase letters and a list of `words`. Every word has the **same length** `w`. Words may repeat in the list.\n\nA **chain** is any way of writing all the words one after another, each used exactly as many times as it appears in the list, in any order. A list of `k` words gives chains of length `k·w`.\n\nReturn, in increasing order, every position `i` such that the `k·w` letters of `text` starting at `i` form a chain. Chains may overlap.\n\n## Example\n\n```\ntext = "xabcdabcdy", words = ["ab", "cd"]   ->  [1, 3, 5] ("abcd" at 1, "cdab" at 3, "abcd" at 5)\ntext = "aaaaaa",     words = ["aa", "aa"]   ->  [0, 1, 2] ("aaaa" three times, overlapping)\ntext = "abbaab",     words = ["ab", "ba"]   ->  [0, 2]    ("abba" at 0, "baab" at 2; "bbaa" is not a chain)\ntext = "abc",        words = ["abcd"]       ->  []\n```\n\n## Constraints\n\n- `1 <= text.length() <= 100000`\n- `1 <= words.size() <= 20000`, every word has the same length `1 <= w <= 30`, all lowercase.\n- If `k·w > text.length()` the answer is empty.\n',editorial:'## Signals\nThe window has a fixed size (`k·w` letters) and the condition is "this multiset of tokens", not "this exact string". Equal-length tokens are the second signal: they cut the text into word-sized cells, and once you know the alignment, the window is a sliding window over cells with a frequency map, the same machinery as Crate Variety.\n\n## Brute force\nFor each start `i` in `[0, n - k·w]`, cut the next `k·w` letters into `k` words, count them, and compare with the target counts. That is `O(n·k)` word reads, each `O(w)`: with `n = 100,000` and `k = 20,000` (for example the text `aaaa...` with the word `aa`), more than a billion operations.\n\n## Key insight\nWords in a chain sit on a grid: the first starts at `i`, the next at `i + w`, and so on. So the starts of its words are all congruent to `i` mod `w`. Split the problem by alignment `offset = 0..w-1`. In one alignment the text is a sequence of cells `text[offset + j·w, +w)`, and a chain is `k` consecutive cells whose word counts equal the target counts. That is a sliding window with a count map: add the incoming cell, and while its count exceeds the allowed multiplicity, drop cells from the left. Two cases reset or shrink: a cell that is not a word at all clears the window; an excess copy shrinks it.\n\n## Optimal\nBuild `need` (word to multiplicity). For each alignment keep `have`, `inside` and `left`. For each cell: if it is unknown, clear everything and set `left` just past it. Otherwise increment `have`, and shrink from the left while `have[word] > need[word]`. When `inside == k`, no word exceeds its multiplicity and the total is `k`, so every count equals `need`: record `left`, then drop one cell to keep sliding. Total time `O(n·w)` (`w` alignments, `n/w` cells each, `O(w)` to hash a cell), space `O(k·w)` for the maps. Sort the answers, because alignments are processed one after another.\n\n## C++ walkthrough\n`unordered_map<string,int>` for `need` and `have`; reuse `it->second` for the cap instead of looking it up again. Guard `k·w > n` with `long long`, since `k·w` is at most 600,000 here but the habit matters. `text.substr(right, w)` allocates once per cell for `w > 15`; if that matters, map each cell to an integer id once per alignment. Do not `have.erase` when a count reaches zero in the shrink loop unless you also compare sizes; leaving zero entries is fine because only `inside` is tested.\n\n## Common bugs\nUsing a `set` and so ignoring repeated words; only trying alignment `0`; accepting any block made of known words without counting; forgetting to sort; not clearing the window on an unknown word, so cells from before it are counted; after recording an answer, not advancing `left`, so the next cell is counted twice; rebuilding the count map per start (`O(n·k)`).\n\n## Follow-ups\nWords of different lengths (use a trie or Aho-Corasick and a DP over positions). Count the chains instead of listing them. Allow one wrong word (track a "mismatch budget"). Streaming text.\n\n## Similar problems\nSubstring with Concatenation of All Words (LeetCode 30). Longest Substring with At Most K Distinct Characters (LeetCode 340, see Crate Variety in this region) for the count-map window.\n',reference:"class Solution {\npublic:\n    vector<int> chainStarts(string text, vector<string> words) {\n        const int n = static_cast<int>(text.size());\n        const int k = static_cast<int>(words.size());\n        const int w = static_cast<int>(words[0].size());\n        vector<int> result;\n        if (static_cast<long long>(k) * w > n) return result;\n\n        unordered_map<string, int> need;  // how many times each word must appear\n        for (const auto& word : words) ++need[word];\n\n        // A chain is a run of k aligned words, so slide one word at a time, once per alignment 0..w-1.\n        for (int offset = 0; offset < w; ++offset) {\n            unordered_map<string, int> have;  // counts of words inside [left, right)\n            int inside = 0;                   // number of words inside the window\n            int left = offset;\n            for (int right = offset; right + w <= n; right += w) {\n                const string word = text.substr(right, w);\n                const auto it = need.find(word);\n                if (it == need.end()) {  // a word that is not in the list breaks every window across it\n                    have.clear();\n                    inside = 0;\n                    left = right + w;\n                    continue;\n                }\n                ++have[word];\n                ++inside;\n                while (have[word] > it->second) {  // too many copies of this word: shrink from the left\n                    --have[text.substr(left, w)];\n                    left += w;\n                    --inside;\n                }\n                if (inside == k) {  // exactly k words, none in excess, so counts match need\n                    result.push_back(left);\n                    --have[text.substr(left, w)];\n                    left += w;\n                    --inside;\n                }\n            }\n        }\n        sort(result.begin(), result.end());  // alignments were processed one after another\n        return result;\n    }\n};\n",hints:'## Nudge\nOrder inside a chain does not matter, only how many times each word appears. If you already know where one word of the chain starts, where do the others start?\n\n## Approach\nEvery word of a chain starts at the same remainder mod `w`. So handle each alignment `0..w-1` on its own: slide a window over the aligned words, one word at a time, keeping a map of word counts inside the window. When a word shows up more often than the list allows, move the left edge forward until it fits; when the window holds `k` words, its left edge is an answer.\n\n## Key insight\nFixing the alignment turns a character-level problem into a word-level sliding window with a count map, exactly like "at most K of each kind". A word that is not in the list resets the window. Each alignment is one pass, so the whole thing is `w` passes of `n / w` steps. Collect the answers from all alignments and sort them at the end.\n',loadTests:async()=>(await e.A(4665)).default},"convoy-count":{meta:{id:"convoy-count",region:"R6",title:"Convoy Count",difficulty:"M",patterns:["monotonic-stack","sorting"],signals:["objects that merge and then move together","the one in front limits the one behind","sort by position, then compare arrival times"],prerequisites:["heat-wave"],parSeconds:720,complexity:{time:"O(n log n)",space:"O(n)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.25,perf:.35},similar:[{name:"Car Fleet",lcNumber:853}],spec:{kind:"function",name:"convoyCount",returns:"int",params:[{type:"int",name:"target"},{type:"vector<int>&",name:"position"},{type:"vector<int>&",name:"speed"}]}},statement:"# Convoy Count\n\nA single-lane road leads to a depot at mile `target`. Several trucks start at different miles, all driving toward the depot. Truck `i` starts at mile `position[i]` and drives at a constant `speed[i]` miles per hour.\n\nTrucks cannot overtake. When a faster truck catches up with a slower one, it slows down and follows right behind, so from then on the two travel together at the slower truck's speed. A group of trucks travelling together is a **convoy**. A truck that never catches anyone is a convoy of its own. Catching up exactly at the depot also counts as travelling together.\n\nReturn the number of distinct convoys that arrive at the depot.\n\n## Examples\n\n- `target = 30, position = [4, 10, 16, 22], speed = [5, 3, 2, 1]` gives `1`. Each truck is faster than the one ahead and catches it before the depot, so all four end up in one convoy.\n- `target = 30, position = [4, 10, 16], speed = [1, 2, 3]` gives `3`. Every truck ahead is faster, so nobody is ever caught.\n- `target = 10, position = [5, 0], speed = [1, 2]` gives `1`. Both would reach the depot at hour 5, so they arrive together.\n\n## Constraints\n\n- `0 <= position.length == speed.length <= 100000`\n- `0 <= position[i] < target <= 1000000000`, and all positions are distinct\n- `1 <= speed[i] <= 1000000000`\n- The trucks are given in no particular order.\n",editorial:'## Signals\n"Things that merge and then move together", "the one in front limits the one behind" and no overtaking. The order along the road matters, so sort by position first. After sorting this is a monotonic-stack (or running maximum) question about arrival times.\n\n## Brute force\nFor each truck, check every truck ahead of it: it leads its own convoy exactly when its lone arrival time is strictly greater than all of theirs. Correct, but a road where nobody ever merges needs every pair checked: O(n²) time, O(1) extra space, about 5 billion comparisons for 100000 trucks.\n\n## Key insight\nA truck\'s lone arrival time is `(target - position) / speed`. The truck in front can only slow someone behind it, never speed them up, so the convoy that truck belongs to arrives at the maximum lone time of everything ahead. A truck forms a new convoy exactly when its lone time is strictly greater than that maximum. Equal times mean it joins at the depot, which the statement counts as one convoy.\n\n## Optimal\nSort indices by position, descending. Keep `leadDist` and `leadSpeed` for the convoy in front (its time is `leadDist / leadSpeed`). For each truck with `dist = target - position` and `spd = speed`: if `dist * leadSpeed > leadDist * spd`, it arrives strictly later, so increment the count and make it the new lead. This is the stack version of the problem with the stack collapsed to its top, since nothing below the top is ever consulted. Sorting dominates: O(n log n) time, O(n) space for the index array.\n\n## C++ walkthrough\nSort an index array (or pairs) rather than the two input vectors separately, so position and speed stay together. Never divide: `dist * leadSpeed` can reach 10^9 · 10^9 = 10^18, which fits in `long long` (about 9.2 · 10^18) but overflows `int`; floating-point division risks wrong ties for large values. Use strict `>`, because a tie is a merge.\n\n## Common bugs\nNot sorting (trusting the input order); counting a tie as a separate convoy (`>=` instead of `>`); multiplying in `int`; comparing speeds instead of arrival times; sorting ascending and then merging in the wrong direction.\n\n## Follow-ups\nReturn the size of the largest convoy. Allow trucks to start at the same mile. Trucks that can overtake (then every truck is its own convoy). Do it without sorting if positions are known to be small integers (counting sort by position).\n\n## Similar problems\nCar Fleet (LeetCode 853) is this problem. Daily Temperatures (LeetCode 739) is the stack idea on a different question; Asteroid Collision (LeetCode 735) is the stack of things that merge or destroy each other.\n',reference:"class Solution {\npublic:\n    int convoyCount(int target, vector<int>& position, vector<int>& speed) {\n        const int n = static_cast<int>(position.size());\n        vector<int> order(n);\n        iota(order.begin(), order.end(), 0);\n        // Front of the road first: the truck ahead can only slow the one behind.\n        sort(order.begin(), order.end(), [&](int a, int b) { return position[a] > position[b]; });\n\n        int convoys = 0;\n        long long leadDist = 0, leadSpeed = 1;  // lone arrival time of the convoy in front = leadDist / leadSpeed\n        for (int idx : order) {\n            const long long dist = target - position[idx];\n            const long long spd = speed[idx];\n            // dist / spd > leadDist / leadSpeed, cross-multiplied (both denominators positive, product <= 1e18).\n            if (convoys == 0 || dist * leadSpeed > leadDist * spd) {\n                ++convoys;\n                leadDist = dist;\n                leadSpeed = spd;\n            }\n        }\n        return convoys;\n    }\n};\n",hints:"## Nudge\nIf a truck drove alone, when would it reach the depot? Which trucks can possibly affect it: the ones in front of it or the ones behind it?\n\n## Approach\nSort the trucks by starting mile, front to back. Walk through them keeping the arrival time of the convoy currently in front. A truck whose own lone arrival time is strictly later than that convoy's time can never catch it: it starts a new convoy. Otherwise it merges and adopts the convoy's time (so nothing changes).\n\n## Key insight\nA truck is held up only by what is ahead of it, and a convoy arrives when its slowest-to-arrive leader does. So the answer is the number of trucks whose lone arrival time is strictly greater than every truck's ahead of them; a running maximum in front-to-back order is enough. Compare times as fractions by cross-multiplying in `long long` to avoid rounding.\n",loadTests:async()=>(await e.A(97791)).default},"crate-brackets":{meta:u.f,statement:'# Crate Brackets\n\nA dock worker labels stacked crates with brackets: `(` `)` `[` `]` `{` `}`. A label is **balanced** when every opening bracket is closed by a bracket of the same kind, and brackets close in the reverse order they opened (the most recently opened one closes first).\n\nGiven the label `s`, return `true` if it is balanced and `false` otherwise.\n\n## Examples\n\n- `s = "([]{})"` gives `true`.\n- `s = "([)]"` gives `false`: the `)` arrives while `[` is the latest open bracket.\n- `s = "(("` gives `false`: nothing closes the openers.\n\n## Constraints\n\n- `0 <= s.length() <= 100000`\n- `s` contains only the six bracket characters.\n- The empty label is balanced.\n',editorial:'## Signals\nNesting where the latest opener must close first is last-in-first-out behaviour, so think stack.\n\n## Brute force\nRepeatedly delete adjacent matching pairs `()`, `[]`, `{}` until nothing changes. Each pass is O(n) and there can be O(n) passes: O(n^2) time.\n\n## Key insight\nOnly the most recently opened bracket can legally be closed next, and "most recent" is exactly what a stack stores.\n\n## Optimal\nScan once. Push each opener. For a closer, the stack must be non-empty and its top must be the matching opener; pop it. Invariant: the stack holds the unclosed openers in order of arrival. The label is balanced iff no step fails and the stack ends empty. Time O(n), space O(n).\n\n## C++ walkthrough\n`std::string` doubles as the stack (`push_back`, `back`, `pop_back`), so no extra include is needed. Check `empty()` before `back()`: calling `back()` on an empty string is undefined behaviour.\n\n## Common bugs\nNot checking for an empty stack before reading the top; returning `true` when openers are left over at the end; counting bracket kinds instead of tracking order, which accepts `([)]`.\n\n## Follow-ups\nReturn the index of the first bad bracket (store indices). Make it O(1) space for a single bracket kind (a counter is enough). Compute the minimum insertions to balance a label.\n\n## Similar problems\nValid Parentheses (LeetCode 20).\n',reference:"class Solution {\npublic:\n    bool isBalanced(string s) {\n        string open;  // unclosed openers in arrival order; top is open.back()\n        for (const char c : s) {\n            if (c == '(' || c == '[' || c == '{') {\n                open.push_back(c);\n                continue;\n            }\n            if (open.empty()) return false;  // closer with nothing to close\n            const char top = open.back();\n            const bool matches = (c == ')' && top == '(') || (c == ']' && top == '[') || (c == '}' && top == '{');\n            if (!matches) return false;\n            open.pop_back();\n        }\n        return open.empty();  // leftover openers mean unbalanced\n    }\n};\n",hints:'## Nudge\nWhen a closing bracket shows up, which earlier opener must it pair with?\n\n## Approach\nKeep the openers you have not closed yet in the order you met them. A closer is only legal if it matches the most recent one.\n\n## Key insight\nThat "most recent unclosed opener" is the top of a stack. Push openers, pop on a closer that matches, and fail on a mismatch or an empty stack. At the end the stack must be empty.\n',prompt:{question:"Why is a stack the right structure for matching brackets, rather than one counter per bracket kind?",options:["Counters are slower than a stack","Only the most recently opened bracket may close next, so order matters and counters lose it","A stack uses less memory than three integers","A counter cannot go above 100000"],answer:1,why:'Counters accept "([)]" because every kind balances out. The stack remembers the order of the unclosed openers, which is exactly the last-in, first-out rule of the problem.'},loadTests:async()=>(await e.A(78744)).default},"drift-rocks":{meta:{id:"drift-rocks",region:"R6",title:"Drift Rocks",difficulty:"M",patterns:["stack"],signals:["items that meet head-on and one or both vanish","only the most recent survivor can be hit","simulate collisions in one pass"],prerequisites:["crate-brackets"],parSeconds:600,complexity:{time:"O(n)",space:"O(n)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.25,perf:.35},similar:[{name:"Asteroid Collision",lcNumber:735}],spec:{kind:"function",name:"survivors",returns:"vector<int>",params:[{type:"vector<int>&",name:"rocks"}]}},statement:"# Drift Rocks\n\nRocks drift along a single line, listed from left to right. Each entry of `rocks` is a nonzero integer: its **absolute value** is the rock's size and its **sign** is the direction (positive moves right, negative moves left). All rocks move at the same speed.\n\nTwo rocks collide only when a right-moving rock is somewhere to the left of a left-moving rock with nothing between them. The smaller one shatters; if both have the same size, both shatter. Rocks moving the same direction never meet, and a left-moving rock with no right-moving rock to its left drifts away safely.\n\nReturn the rocks that remain after all collisions, in their original left-to-right order.\n\n## Examples\n\n- `rocks = [4, 7, -3]` gives `[4, 7]`: the 3 hits the 7 and shatters.\n- `rocks = [5, -5, 2]` gives `[2]`: equal sizes both shatter.\n- `rocks = [3, 2, -9, 6]` gives `[-9, 6]`: the 9 breaks the 2, then the 3, and then runs out of rocks to hit.\n- `rocks = [-2, -4, 8, 1]` gives `[-2, -4, 8, 1]`: nothing ever meets.\n\n## Constraints\n\n- `0 <= rocks.length <= 100000`\n- `1 <= abs(rocks[i]) <= 1000000000`\n",editorial:'## Signals\nItems on a line that cancel each other when they meet head-on, and the question asks what is left in order. The "most recent survivor" is the only one a new item can touch, which is a stack.\n\n## Brute force\nRepeatedly scan for the first adjacent pair (right-mover followed by left-mover), resolve it, delete the loser(s), and rescan from the start until no pair remains. Correct, but a big left-mover behind 50000 right-movers causes 50000 rescans plus array erases: O(n²) time, O(1) extra space.\n\n## Key insight\nResolve collisions the moment a rock arrives. A new left-moving rock can only meet the nearest surviving right-mover before it, which is the top of the stack. Left-movers already on the stack have nothing to their left that moves right (or they would have collided), so they never interact with later rocks except as the stack\'s bottom.\n\n## Optimal\nFor each rock `r` in order, let `alive = true`. While `alive`, `r < 0`, and the stack top is positive: compare sizes. If `top < -r`, pop and continue. If `top == -r`, pop and set `alive = false`. If `top > -r`, set `alive = false`. After the loop, push `r` if it is still alive. The stack is the answer, bottom to top. Invariant: the stack never contains a right-mover directly followed by a left-mover. Each rock is pushed once and popped at most once: O(n) time, O(n) space.\n\n## C++ walkthrough\nUse a `vector<int>` as the stack so the result needs no reversing. Test `kept.back() > 0` (not just non-empty) so left-movers stack up harmlessly on top of other left-movers. Compare `kept.back()` with `-r`, which is the size of a left-mover. Equal sizes remove the top as well; forgetting that leaves a ghost rock.\n\n## Common bugs\n`if` instead of `while` (the big rock only breaks one rock); comparing without checking directions, so two left-movers "collide"; on equal size, removing only the new rock; removing nothing on a tie; pushing the new rock after it has already been destroyed.\n\n## Follow-ups\nDifferent speeds per rock (then it becomes an event simulation with a heap). Return how many rocks shatter instead. Rocks on a circular track (no rock is "leftmost"; handle wrap-around by doubling the list carefully).\n\n## Similar problems\nAsteroid Collision (LeetCode 735) is this problem. Daily Temperatures (LeetCode 739) and Car Fleet (LeetCode 853) use the same one-pass stack.\n',reference:"class Solution {\npublic:\n    vector<int> survivors(vector<int>& rocks) {\n        vector<int> kept;  // invariant: no right-mover is directly followed by a left-mover\n        for (const int rock : rocks) {\n            bool alive = true;\n            while (alive && rock < 0 && !kept.empty() && kept.back() > 0) {\n                if (kept.back() < -rock) {\n                    kept.pop_back();  // the right-mover shatters; the new rock keeps going\n                } else {\n                    if (kept.back() == -rock) kept.pop_back();  // equal sizes: both shatter\n                    alive = false;\n                }\n            }\n            if (alive) kept.push_back(rock);\n        }\n        return kept;\n    }\n};\n",hints:"## Nudge\nWhen a new rock arrives, which earlier rocks could it possibly hit? Only a right-moving rock can be hit, and only the nearest one first.\n\n## Approach\nKeep a stack of survivors. For each new rock: while it moves left and the top of the stack moves right, they collide. If the top is smaller, pop it and keep going; if it is equal, pop it and the new rock is gone; if the top is bigger, the new rock is gone. If the new rock is still alive afterwards, push it.\n\n## Key insight\nA new rock can only ever interact with the top of the stack, and every collision removes at least one rock, so each rock is pushed once and popped at most once. Use `while`, not `if`: one big left-mover can plough through many right-movers.\n",loadTests:async()=>(await e.A(40457)).default},"gauge-stack":{meta:m,statement:"# Gauge Stack\n\nA workshop keeps a stack of pressure readings. A foreman wants to know, at any moment, the **lowest reading currently on the stack**, without scanning it.\n\nDesign `GaugeStack` with these operations, each in **O(1)** time:\n\n- `void push(int val)`: put a reading on top.\n- `void pop()`: remove the top reading.\n- `int top()`: return the top reading without removing it.\n- `int low()`: return the smallest reading currently on the stack.\n\n`pop`, `top` and `low` are only called when the stack is not empty.\n\n## Example\n\n```\npush(5)\npush(3)\npush(3)\npush(8)\nlow() -> 3\npop()            removes 8\npop()            removes a 3\nlow() -> 3       (the other 3 is still there)\npop()            removes the last 3\nlow() -> 5\ntop() -> 5\n```\n\n## Constraints\n\n- Up to `200000` operations in total.\n- `-1000000000 <= val <= 1000000000`.\n",editorial:'## Signals\n"A stack, plus one more question answered in O(1)" means the extra answer must survive pops. Whenever a structure only changes at one end, you can store a running summary with each element.\n\n## Brute force\nKeep a plain vector and scan it inside `low()`. Correct, but 200000 operations with a tall stack cost about n² / 2 element visits, which is billions: O(n) per `low` call, O(n) space.\n\n## Key insight\n`low()` is a function of the whole stack content, and the content below an element never changes while that element is on the stack. So each element can carry "lowest reading from the bottom up to me". Popping an element removes its summary with it and exposes the previous, still-correct, one.\n\n## Optimal\nStore `(val, lowestSoFar)` per item, where `lowestSoFar = min(val, lowestSoFar of the item below)`. All four operations are O(1) time; space is O(n), two ints per item. Alternative: a second stack of minimums that pushes on every push (not only on new minimums), which is the same idea split across two vectors.\n\n## C++ walkthrough\n`vector<pair<int,int>>` with `emplace_back` is a clean stack, and `back()` gives the top. Methods that do not modify state are `const`. The first push has no item below, so the lowest is the value itself. Do not `pop_back` on an empty vector: the statement promises it never happens, but it is worth a comment in a real codebase.\n\n## Common bugs\nKeeping one `min` variable and never repairing it after a pop; a side stack that pushes only when `val < currentMin`, so two equal minimums lose one on the first pop (use `<=` or push every time); recomputing with a scan.\n\n## Follow-ups\nReturn the lowest **and** highest. Support `popMin`-style removal (needs a different structure, such as a balanced tree or lazy deletion). Reach O(1) extra space for the minimum by storing differences from the running minimum. Add `low()` for a queue (two stacks, each tracking its own minimum).\n\n## Similar problems\nMin Stack (LeetCode 155) is this problem. Max Stack (LeetCode 716) adds `popMax`. Sliding Window Maximum (LeetCode 239) keeps a monotonic deque for the same "summary that survives removal" job.\n',reference:"class GaugeStack {\npublic:\n    GaugeStack() = default;\n\n    void push(int val) {\n        // Each entry remembers the lowest reading at or below it, so the answer survives pops.\n        const int lowest = items_.empty() ? val : min(val, items_.back().second);\n        items_.emplace_back(val, lowest);\n    }\n\n    void pop() { items_.pop_back(); }\n\n    int top() const { return items_.back().first; }\n\n    int low() const { return items_.back().second; }\n\nprivate:\n    vector<pair<int, int>> items_;  // (reading, lowest reading in the stack up to here)\n};\n",hints:'## Nudge\nAfter a pop, the old lowest reading may be gone. What would you need to have remembered at the moment each reading was pushed so that the answer is simply waiting for you?\n\n## Approach\nStore, with every reading, the lowest reading on the stack up to and including it. Pushing computes `min(val, lowest of the item below)`. `low()` reads the top item\'s stored lowest; `pop()` discards the pair, and the stored value of the new top is automatically right.\n\n## Key insight\nThe stack only changes at the top, so a summary of "everything below and including me" never goes stale. A single `min` variable breaks on pop, and a side stack that skips duplicates of the minimum breaks when two equal minimums are stacked.\n',loadTests:async()=>(await e.A(21250)).default},"heat-wave":{meta:{id:"heat-wave",region:"R6",title:"Heat Wave",difficulty:"M",patterns:["monotonic-stack"],signals:["next greater element","how many steps until something bigger","unresolved items wait on a stack"],prerequisites:["crate-brackets"],parSeconds:600,complexity:{time:"O(n)",space:"O(n)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.25,perf:.35},similar:[{name:"Daily Temperatures",lcNumber:739}],spec:{kind:"function",name:"waitDays",returns:"vector<int>",params:[{type:"vector<int>&",name:"temps"}]}},statement:"# Heat Wave\n\nA weather station logs one reading per day. For every day, the crew wants to know how long they must wait for a **strictly hotter** day.\n\nGiven the array `temps`, return an array `wait` of the same length where `wait[i]` is the number of days from day `i` to the nearest later day with a higher reading. If no later day is hotter, `wait[i]` is `0`.\n\n## Examples\n\n- `temps = [30, 40, 35, 50, 45]` gives `[1, 2, 1, 0, 0]`.\n- `temps = [60, 60, 60]` gives `[0, 0, 0]` (equal is not hotter).\n- `temps = [9, 8, 7, 10]` gives `[3, 2, 1, 0]`.\n\n## Constraints\n\n- `0 <= temps.length <= 100000`\n- `-1000000000 <= temps[i] <= 1000000000`\n",editorial:'## Signals\n"For each day, how long until something bigger?" is the next greater element question with the distance as the answer. Anything left over at the end simply gets 0.\n\n## Brute force\nFrom each day scan forward until a hotter reading appears. Correct, but a strictly falling year of 100000 readings makes about 5 billion comparisons: O(n²) time, O(1) extra space.\n\n## Key insight\nProcess days in order and remember only the days that are still waiting. They form a stack whose temperatures never increase from bottom to top, because a hotter day would already have resolved the colder one below it. A new day therefore resolves a suffix of the stack.\n\n## Optimal\nKeep a stack of indices. For each day `i`, while the stack is non-empty and `temps[top] < temps[i]`, set `wait[top] = i - top` and pop. Then push `i`. Invariant: temperatures on the stack are non-increasing. Each index is pushed once and popped at most once, so time is O(n); the stack and the answer use O(n) space.\n\n## C++ walkthrough\nUse `<` and not `<=` in the loop: an equal day is not hotter and must keep waiting (and then sits on the stack with its equal neighbour, which keeps the stack non-increasing, not strictly decreasing). Store indices, not temperatures, because the answer is a distance. Initialise `wait` to zeros so unresolved days need no extra pass.\n\n## Common bugs\nUsing `<=`; using `if` instead of `while` so only one day resolves per step; returning the hotter temperature instead of the distance; storing temperatures on the stack and losing the index.\n\n## Follow-ups\nReturn the *value* of the next greater element, or the *previous* greater instead (scan right to left, or flip the comparison). Make the array circular (Next Greater Element II): loop `2n` times with index `i % n`. Count the days until a *colder* day: flip the comparison.\n\n## Similar problems\nDaily Temperatures (LeetCode 739) is this problem. Next Greater Element II (LeetCode 503) and Online Stock Span (LeetCode 901) use the same stack.\n',reference:"class Solution {\npublic:\n    vector<int> waitDays(vector<int>& temps) {\n        const int n = static_cast<int>(temps.size());\n        vector<int> wait(n, 0);\n        vector<int> pending;  // indices still waiting for a hotter day; their temps never increase\n        for (int i = 0; i < n; ++i) {\n            while (!pending.empty() && temps[pending.back()] < temps[i]) {\n                wait[pending.back()] = i - pending.back();\n                pending.pop_back();\n            }\n            pending.push_back(i);\n        }\n        return wait;\n    }\n};\n",hints:"## Nudge\nWhich days are still waiting for a hotter day once you reach day `i`? What do their temperatures look like, from the oldest waiting day to the newest?\n\n## Approach\nKeep a stack of day indices that have not found a hotter day yet. When today is hotter than the day on top, that day's wait ends today: record `i - top` and pop. Keep popping while today still beats the top, then push today.\n\n## Key insight\nThe waiting days always have non-increasing temperatures, so only the top can be resolved first, and a warm day resolves a whole run of colder ones at once. Every day is pushed once and popped at most once.\n",loadTests:async()=>(await e.A(30690)).default},"ring-lane":{meta:p,statement:"# Ring Lane\n\nA drive-through has room for exactly `capacity` cars in a single lane, and a car that is served frees its spot for the next arrival. Build this lane as a **circular queue** backed by one fixed-size array: do not use `queue`, `deque` or `list`, and do not shift elements.\n\nDesign `RingLane` with these operations, each in **O(1)** time:\n\n- `RingLane(int capacity)`: create an empty lane.\n- `bool offer(int val)`: a car joins the back of the lane. Return `true` if it fit, `false` if the lane was full.\n- `bool poll()`: the car at the front leaves. Return `true` if a car was served, `false` if the lane was empty.\n- `int front()`: the car number at the front, or `-1` if the lane is empty.\n- `int back()`: the car number at the back, or `-1` if the lane is empty.\n- `bool empty()`: `true` if no car is waiting.\n- `bool full()`: `true` if `capacity` cars are waiting.\n\n## Example\n\n```\nRingLane(2)\noffer(7)  -> true\noffer(8)  -> true\noffer(9)  -> false   (full)\nfront()   -> 7\npoll()    -> true\noffer(9)  -> true    (reuses the freed slot)\nback()    -> 9\nfront()   -> 8\n```\n\n## Constraints\n\n- `1 <= capacity <= 100000`\n- `0 <= val <= 1000000000`\n- Up to `200000` operations in total.\n",editorial:'## Signals\n"Fixed-size buffer, oldest item leaves first, freed space is reused." That is a ring buffer: the storage never moves, the indices do. It shows up in streaming, logging and producer-consumer code.\n\n## Brute force\nStore the queue in a vector and `erase(begin())` on every `poll`. Each poll shifts up to `capacity` elements: O(capacity) per call, about 10^10 total moves when the lane holds 100000 cars and 100000 polls follow. It is correct but too slow.\n\n## Key insight\nLeave the elements where they are and move the *window*: `head` is the index of the front and `size` is how many cars are in the lane. The slot after the last car is `(head + size) % capacity`. Tracking `size` explicitly resolves the empty-versus-full ambiguity that `head == tail` has.\n\n## Optimal\nAllocate `vector<int> slots(capacity)`. `offer`: if `size == capacity` return false; write `slots[(head + size) % capacity] = val`, increment `size`. `poll`: if `size == 0` return false; `head = (head + 1) % capacity`, decrement `size`. `front`: `size == 0 ? -1 : slots[head]`. `back`: `size == 0 ? -1 : slots[(head + size - 1) % capacity]`. Every operation is O(1); the space is O(k) for capacity k.\n\n## C++ walkthrough\nUse `size_t` or `int` consistently; `head + size` is at most `2 * capacity`, so `int` is safe here. Mark the read-only methods `const`. The `%` is cheaper to get right than the alternative `if (++head == capacity) head = 0`, but both are fine in an interview; say why you chose one.\n\n## Common bugs\nUsing `head == tail` for both empty and full; computing `back` as `slots[tail]` (one past the last car) instead of one before it; forgetting to wrap `head` after a poll; letting `offer` succeed when the lane is full and overwriting the front car; returning `0` instead of `-1` for an empty lane.\n\n## Follow-ups\nThe same lane for a *deque* (add and remove at both ends: decrement `head` with a wrap). A ring buffer that overwrites the oldest on overflow. A thread-safe single-producer single-consumer queue using two atomic indices.\n\n## Similar problems\nDesign Circular Queue (LeetCode 622) is this problem. Design Circular Deque (LeetCode 641) extends it, and Moving Average from Data Stream (LeetCode 346) uses a ring window.\n',reference:"class RingLane {\npublic:\n    explicit RingLane(int capacity) : slots_(capacity) {}\n\n    bool offer(int val) {\n        if (full()) return false;\n        slots_[(head_ + size_) % capacity()] = val;  // first free slot after the last car\n        ++size_;\n        return true;\n    }\n\n    bool poll() {\n        if (empty()) return false;\n        head_ = (head_ + 1) % capacity();  // the array never shifts; the window moves\n        --size_;\n        return true;\n    }\n\n    int front() const { return empty() ? -1 : slots_[head_]; }\n\n    int back() const { return empty() ? -1 : slots_[(head_ + size_ - 1) % capacity()]; }\n\n    bool empty() const { return size_ == 0; }\n\n    bool full() const { return size_ == capacity(); }\n\nprivate:\n    int capacity() const { return static_cast<int>(slots_.size()); }\n\n    vector<int> slots_;\n    int head_ = 0;  // index of the front car\n    int size_ = 0;  // cars waiting; tracked so empty and full are never confused\n};\n",hints:'## Nudge\nWhen a car leaves the front of a plain array, you do not have to move everyone. What if the array\'s end simply joined back up to its start, like a ring?\n\n## Approach\nKeep a vector of `capacity` slots, a `head` index (the front car) and a `size` count. The back car lives at `(head + size - 1) % capacity`. `offer` writes at `(head + size) % capacity` and grows `size`; `poll` moves `head` forward by one (wrapping) and shrinks `size`.\n\n## Key insight\nWith only `head` and `tail` indices, "empty" and "full" look the same (`head == tail`). Store the **count** (or keep one slot unused) so the two states are distinguishable. Wrapping is just `% capacity`.\n',loadTests:async()=>(await e.A(20860)).default},"score-tape":{meta:{id:"score-tape",region:"R6",title:"Score Tape",difficulty:"E",patterns:["stack"],signals:["commands that look at or undo the latest entries","undo","simulate with a stack"],prerequisites:["crate-brackets"],parSeconds:420,complexity:{time:"O(n)",space:"O(n)"},timeLimitMs:1e3,testWeights:{basic:.3,edge:.25,adversarial:.2,perf:.25},similar:[{name:"Baseball Game",lcNumber:682}],spec:{kind:"function",name:"totalScore",returns:"long long",params:[{type:"vector<string>&",name:"commands"}]}},statement:'# Score Tape\n\nA quiz machine records a **score tape**. It starts empty and processes `commands` in order. Each command is one of:\n\n- an integer such as `"7"` or `"-3"`: append that score to the tape.\n- `"+"`: append the **sum of the last two** scores on the tape.\n- `"D"`: append **double the last** score.\n- `"H"`: append **half the last** score, rounded toward zero (`H` of `7` is `3`, of `-7` is `-3`).\n- `"C"`: **cancel** (remove) the last score on the tape.\n\nReturn the sum of all scores left on the tape at the end, or `0` if the tape is empty.\n\n## Examples\n\n- `commands = ["5", "2", "C", "D", "+"]` gives `30` (the tape goes `[5]`, `[5,2]`, `[5]`, `[5,10]`, `[5,10,15]`).\n- `commands = ["8", "H", "H", "+"]` gives `14` (the tape becomes `[8,4,2,6]`).\n- `commands = ["-4", "D", "C", "C"]` gives `0`.\n\n## Constraints\n\n- `0 <= commands.length <= 100000`.\n- Commands are always valid: `"+"` needs at least two scores on the tape, and `"D"`, `"H"` and `"C"` need at least one.\n- Every score that ever lands on the tape has absolute value at most `1000000000`, so scores fit in `int`; the final sum may not.\n',editorial:'## Signals\nCommands that read or undo "the latest" entries are a stack in disguise: all the action happens at one end, and "cancel" is a pop.\n\n## Brute force\nAfter each command, rebuild the tape from the start (or re-add all scores). It is correct but O(n²): with 100000 commands that is around 5 billion steps.\n\n## Key insight\nA command depends only on the newest one or two scores, and `C` only removes the newest. The tape never needs random access, so a stack replaces all recomputation.\n\n## Optimal\nProcess commands once, mutating a stack. Number: push `stoi`. `+`: push the sum of the top two. `D`: push double the top. `H`: push top / 2. `C`: pop. Finally sum the stack into a `long long`. Time O(n), space O(n).\n\n## C++ walkthrough\nCompare commands as whole strings (`cmd == "C"`), and treat anything else as a number: `"-3"` is a score, not a command. Read `tape[n-1]` and `tape[n-2]` **before** pushing, since `push_back` may reallocate and invalidate references. Integer `/ 2` truncates toward zero for negatives, which is what `H` needs; `floor` would be wrong. Scores fit `int` by the constraints, but the total of 100000 of them does not, so accumulate in `long long`.\n\n## Common bugs\nSumming into `int`; flooring negative halves; popping the top while computing `+`; treating `"-3"` as an operator; holding a reference to `back()` across a `push_back`.\n\n## Follow-ups\nAdd a command that duplicates the last *k* scores. Keep a running total so the answer is O(1) at any time (add on push, subtract on pop). Support redo as well as cancel (two stacks).\n\n## Similar problems\nBaseball Game (LeetCode 682) is the closest. Evaluate Reverse Polish Notation (LeetCode 150) is Tape Calculator in this region.\n',reference:'class Solution {\npublic:\n    long long totalScore(vector<string>& commands) {\n        vector<int> tape;\n        for (const auto& cmd : commands) {\n            if (cmd == "C") {\n                tape.pop_back();\n            } else if (cmd == "D") {\n                tape.push_back(tape.back() * 2);\n            } else if (cmd == "H") {\n                tape.push_back(tape.back() / 2);  // C++ division truncates toward zero\n            } else if (cmd == "+") {\n                const int n = static_cast<int>(tape.size());\n                tape.push_back(tape[n - 1] + tape[n - 2]);  // read both before pushing\n            } else {\n                tape.push_back(stoi(cmd));  // handles "-3"\n            }\n        }\n        long long sum = 0;  // up to 1e5 scores of 1e9 each: needs 64 bits\n        for (const int score : tape) sum += score;\n        return sum;\n    }\n};\n',hints:"## Nudge\nEvery command talks about the *latest* scores, and `C` throws the latest one away. What structure gives you cheap access to the newest entries and cheap removal of the newest?\n\n## Approach\nKeep the tape in a vector used as a stack. `C` pops. `D` and `H` push a value computed from `back()`. `+` reads the top two (read them before you push) and pushes their sum. A number is parsed and pushed. At the end add up what is left.\n\n## Key insight\nBecause each command only touches the top of the tape, a stack gives O(1) per command. Use C++ `/ 2` for `H` (it truncates toward zero, as the statement says) and sum into a `long long`.\n",loadTests:async()=>(await e.A(77171)).default},"skyline-hall":{meta:{id:"skyline-hall",region:"R6",title:"Skyline Hall",difficulty:"H",patterns:["monotonic-stack"],signals:["histogram area","previous smaller and next smaller","widest span where a bar is the minimum"],prerequisites:["crate-brackets"],parSeconds:1500,complexity:{time:"O(n)",space:"O(n)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.3,perf:.3},similar:[{name:"Largest Rectangle in Histogram",lcNumber:84}],spec:{kind:"function",name:"largestHall",returns:"long long",params:[{type:"vector<int>&",name:"heights"}]}},statement:"# Skyline Hall\n\nA row of walls stands side by side, each exactly one unit wide. Wall `i` has height `heights[i]`. You want to build a rectangular hall out of consecutive walls: pick a stretch of `w` adjacent walls; the hall's height is limited by the shortest wall in that stretch, so its floor area is `w` times that shortest height.\n\nReturn the largest floor area you can get from any stretch of consecutive walls. If there are no walls, return `0`.\n\n## Examples\n\n- `heights = [2,1,5,6,2,3]` gives `10` (the walls of height 5 and 6 give `2 * 5`).\n- `heights = [4,4,4]` gives `12`.\n- `heights = [7]` gives `7`.\n\n## Constraints\n\n- `0 <= heights.length <= 100000`\n- `0 <= heights[i] <= 10^9`\n- The answer can exceed 32 bits.\n",editorial:'## Signals\n"Best rectangle bounded by the shortest element in a stretch" asks, for each element, for the nearest smaller element on both sides. That is a monotonic stack question.\n\n## Brute force\nFor each wall, expand left and right while neighbours are at least as tall, then multiply. O(n^2) time, O(1) space. A staircase of 100000 equal walls does about 5 billion steps.\n\n## Key insight\nEach wall is popped from the stack exactly once, and the moment it is popped we learn both of its blockers: the wall that popped it (right) and the new top beneath it (left).\n\n## Optimal\nKeep a stack of indices with non-decreasing heights. For each index `i` (plus a sentinel height 0 at `i = n`), while the stack top is taller than `heights[i]`, pop it as `top`; its height `h = heights[top]`, its left blocker is the new stack top (or -1 if empty) and its right blocker is `i`, so the width is `i - left - 1`. Update the best area with `h * width`. Push `i`. Invariant: stack heights never decrease, so everything below the top is a valid left blocker candidate. Each index is pushed and popped once: time O(n), space O(n).\n\n## C++ walkthrough\nAreas are `long long`: `10^5 * 10^9 = 10^14`. The loop runs to `i == n` with a virtual height 0 instead of a second flush loop. Equal heights are popped too (`>=`) or kept (`>`); both are correct, because the wider rectangle is found when the last equal bar pops.\n\n## Common bugs\nForgetting to flush the stack after the last wall; computing the width with the popped index instead of `i - left - 1`; a 32-bit area that overflows; using the popped wall\'s own index as the left edge, which ignores taller walls already popped.\n\n## Follow-ups\nLargest rectangle of ones in a binary matrix: run this per row on running column heights. Solve it with divide and conquer on the minimum (O(n log n) with a segment tree). What if heights are real numbers?\n\n## Similar problems\nLargest Rectangle in Histogram (LeetCode 84); Maximal Rectangle (LeetCode 85) builds on it.\n',reference:"class Solution {\npublic:\n    long long largestHall(vector<int>& heights) {\n        const int n = static_cast<int>(heights.size());\n        vector<int> stack;  // indices with non-decreasing heights\n        long long best = 0;\n        for (int i = 0; i <= n; ++i) {\n            const long long cur = (i == n) ? 0 : heights[i];  // height 0 sentinel flushes the stack\n            while (!stack.empty() && heights[stack.back()] > cur) {\n                const long long h = heights[stack.back()];\n                stack.pop_back();\n                const int left = stack.empty() ? -1 : stack.back();  // nearest shorter-or-equal on the left\n                best = max(best, h * (i - left - 1));\n            }\n            stack.push_back(i);\n        }\n        return best;\n    }\n};\n",hints:"## Nudge\nFix one wall as the shortest in the hall. How far left and right can the hall stretch before a shorter wall blocks it?\n\n## Approach\nFor every wall, find the nearest strictly shorter wall on each side. The area for that wall is its height times the distance between those two blockers minus one.\n\n## Key insight\nProcess walls left to right with a stack whose heights are increasing. When a new wall is shorter than the top, the top's right blocker is the new wall and its left blocker is the element below it in the stack: pop, compute its area, repeat. Add a height-0 sentinel at the end to flush the stack. Use 64-bit areas.\n",loadTests:async()=>(await e.A(21964)).default},"smallest-seal":{meta:{id:"smallest-seal",region:"R6",title:"Smallest Seal",difficulty:"M",patterns:["monotonic-stack","greedy"],signals:["delete exactly k items to make the smallest sequence","a larger digit before a smaller one should go","earlier positions matter most"],prerequisites:["heat-wave"],parSeconds:840,complexity:{time:"O(n)",space:"O(n)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.25,perf:.35},similar:[{name:"Remove K Digits",lcNumber:402}],spec:{kind:"function",name:"smallestSeal",returns:"string",params:[{type:"string",name:"code"},{type:"int",name:"k"}]}},statement:'# Smallest Seal\n\nA vault seal is a number written as a string of digits. The vault clerk must scratch out exactly `k` digits of the `code`. The remaining digits keep their order and form a new number. The clerk wants the **smallest possible number**.\n\nReturn that number as a string. Write it with no leading zeros; if nothing is left, or only zeros are left, return `"0"`.\n\n## Examples\n\n- `code = "4132", k = 1` gives `"132"`: scratching the 4 beats every other choice.\n- `code = "10200", k = 1` gives `"200"`: scratch the 1, and the leading zero disappears.\n- `code = "9", k = 1` gives `"0"`.\n- `code = "12345", k = 2` gives `"123"`: the digits only grow, so the last ones go.\n\n## Constraints\n\n- `0 <= code.length() <= 100000`, and `code` contains only digits (it may start with `0`).\n- `0 <= k <= code.length()`\n- For an empty `code` the answer is `"0"`.\n',editorial:'## Signals\n"Delete exactly k elements so the remaining sequence is as small (or large) as possible, order preserved." A bigger value before a smaller one is the thing to get rid of: that is a monotonic stack with a budget.\n\n## Brute force\nTry every subset of `n - k` digits to keep, strip leading zeros, and compare as numbers (shorter is smaller, then lexicographic). Correct, but there are C(n, k) subsets: exponential. A smarter brute force deletes, k times, the first digit that is larger than its right neighbour: O(n · k), still 10^10 steps for n = 100000 and k = 50000.\n\n## Key insight\nCompare two candidates of equal length digit by digit from the left: the first difference decides. So at each position we want the smallest digit we can afford. If the previous kept digit is larger than the incoming one, removing it makes the number strictly smaller at that position no matter what follows, so it is optimal to spend a scratch on it.\n\n## Optimal\nKeep a string `kept` as a stack. For each digit `d`: while `k > 0` and `kept.back() > d`, pop and decrement `k`; then push `d`. After the scan the stack is non-decreasing among the digits that survived, so the biggest digits are at the end: drop `k` more characters from the end. Strip leading zeros and return `"0"` if empty. Every digit is pushed once and popped at most once: O(n) time, O(n) space.\n\n## C++ walkthrough\nA `std::string` works as the stack (`push_back`, `pop_back`, `back`). Compare `char`s directly since \'0\'..\'9\' are ordered. Removing the leftover `k` with `resize` is safe because `k <= kept.size()` always holds. Use `find_first_not_of(\'0\')` to find the first non-zero digit; `npos` means all zeros (or empty), so return `"0"`. Do the zero-stripping after the removals, never before.\n\n## Common bugs\nForgetting to apply leftover removals (an increasing code such as `12345`); keeping leading zeros; returning an empty string instead of `"0"`; popping with `>=` is harmless, but popping when `kept.back() < d` makes the largest number instead; scratching the `k` biggest digits ignoring position (order matters more than size).\n\n## Follow-ups\nMake the *largest* number. Keep exactly `m` digits to make the lexicographically smallest subsequence of a string of letters. Remove duplicates so that each letter appears once and the result is smallest (stack plus last-occurrence info).\n\n## Similar problems\nRemove K Digits (LeetCode 402) is this problem. Daily Temperatures (LeetCode 739) uses the same monotonic stack with a different question.\n',reference:"class Solution {\npublic:\n    string smallestSeal(string code, int k) {\n        string kept;  // invariant: digits that are still candidates, non-decreasing unless we ran out of removals\n        for (const char d : code) {\n            // A bigger digit directly before a smaller one makes the number larger: remove it while we can.\n            while (k > 0 && !kept.empty() && kept.back() > d) {\n                kept.pop_back();\n                --k;\n            }\n            kept.push_back(d);\n        }\n        kept.resize(kept.size() - static_cast<size_t>(k));  // still owe removals: drop from the end (largest tail)\n        const size_t firstNonZero = kept.find_first_not_of('0');\n        return firstNonZero == string::npos ? \"0\" : kept.substr(firstNonZero);\n    }\n};\n",hints:'## Nudge\nCompare two numbers with the same number of digits: which position decides the winner? So which digit is the best one to scratch first?\n\n## Approach\nScan left to right, keeping the digits you have kept in a stack-like string. When a new digit is smaller than the last kept digit and you still have scratches left, pop the last kept digit (scratch it). Then push the new digit. After the scan, if scratches remain, remove them from the end. Finally strip leading zeros and return `"0"` if nothing is left.\n\n## Key insight\nEarlier digits matter most, so a digit followed by a smaller digit is always worth removing: the number gets smaller at that position. A monotonic (non-decreasing) stack removes exactly those digits, and any leftover removals come off the largest tail because the kept digits are already non-decreasing.\n',loadTests:async()=>(await e.A(88196)).default},"tape-calculator":{meta:{id:"tape-calculator",region:"R6",title:"Tape Calculator",difficulty:"M",patterns:["stack"],signals:["operators come after their operands","expression evaluation","latest two values are combined"],prerequisites:["crate-brackets"],parSeconds:600,complexity:{time:"O(n)",space:"O(n)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.25,adversarial:.2,perf:.35},similar:[{name:"Evaluate Reverse Polish Notation",lcNumber:150}],spec:{kind:"function",name:"runTape",returns:"int",params:[{type:"vector<string>&",name:"tape"}]}},statement:'# Tape Calculator\n\nAn old shop calculator reads a **tape** of tokens left to right. A token is either an integer (such as `"12"` or `"-3"`) or one of the operators `"+"`, `"-"`, `"*"`, `"/"`. An operator takes the **two most recent unused values**, with the older one on the left, and replaces them with the result.\n\nDivision truncates toward zero (`7 / -2` is `-3`, and `-7 / 2` is `-3`). Return the final value left on the tape.\n\n## Examples\n\n- `tape = ["2", "3", "+", "4", "*"]` gives `20` (that is `(2 + 3) * 4`).\n- `tape = ["10", "2", "-"]` gives `8` (older value on the left: `10 - 2`).\n- `tape = ["-7", "2", "/"]` gives `-3`.\n\n## Constraints\n\n- `1 <= tape.length <= 100001`, and the tape is always valid: it leaves exactly one value.\n- Every operand is an integer in `[-1000000, 1000000]`.\n- Every division has a non-zero divisor, and every intermediate result fits in a 32-bit signed integer.\n',editorial:'## Signals\nOperators that come *after* their operands, and "combine the most recent two", describe a stack. Anything with nesting or last-in-first-out structure points the same way.\n\n## Brute force\nRepeatedly find the first operator, fold it with the two tokens before it, and erase them. Correct, but each fold costs a rescan and an erase from the middle of a vector: O(n²) time. A tape of 50000 additions after 50001 numbers does billions of element moves.\n\n## Key insight\nIn postfix form, when an operator appears its operands are fully evaluated and are the two newest values. Nothing older can matter yet, so one stack of values replaces the whole rewrite.\n\n## Optimal\nScan the tape once. Numbers are pushed. For an operator, pop `right`, pop `left`, push `left op right`. Invariant: the stack holds the values of the complete sub-expressions read so far. Time O(n); space O(n) in the worst case (all numbers first).\n\n## C++ walkthrough\nDetect operators by `size() == 1` and membership in `"+-*/"`, never by the first character, because `"-3"` starts with a minus sign. `stoi` parses negative numbers. C++ integer `/` already truncates toward zero, matching the statement, so no adjustment is needed (Python-style floor division would need one). Pop the right operand first.\n\n## Common bugs\nSwapping the operands, which silently breaks `-` and `/` while `+` and `*` still pass; treating `"-3"` as an operator; using floor division; popping without checking, which cannot happen on a valid tape but is worth a comment.\n\n## Follow-ups\nConvert an infix expression to postfix (shunting-yard) or evaluate it directly with two stacks, which is Basic Calculator territory. Support unary minus and parentheses. Detect an invalid tape by checking the stack size before every pop.\n\n## Similar problems\nEvaluate Reverse Polish Notation (LeetCode 150) is this problem. Basic Calculator II (LeetCode 227) and Basic Calculator (LeetCode 224) build on the same stack.\n',reference:"class Solution {\npublic:\n    int runTape(vector<string>& tape) {\n        vector<int> values;\n        for (const auto& token : tape) {\n            const bool isOperator = token.size() == 1 && string(\"+-*/\").find(token[0]) != string::npos;\n            if (!isOperator) {\n                values.push_back(stoi(token));  // handles \"-3\": a lone '-' is the only minus operator\n                continue;\n            }\n            const int right = values.back(); values.pop_back();  // newer value is the right operand\n            const int left = values.back(); values.pop_back();\n            switch (token[0]) {\n                case '+': values.push_back(left + right); break;\n                case '-': values.push_back(left - right); break;\n                case '*': values.push_back(left * right); break;\n                default:  values.push_back(left / right); break;  // C++ truncates toward zero\n            }\n        }\n        return values.back();\n    }\n};\n",hints:"## Nudge\nWhen an operator arrives, which values does it need, and where have you been keeping the values you have not used yet?\n\n## Approach\nPush every number onto a stack. On an operator, pop the right operand first and then the left one, combine them, and push the result. The answer is the only value left.\n\n## Key insight\nPostfix order guarantees the two operands of an operator are exactly the two newest unused values, so a stack needs no parentheses or precedence rules. Pop order matters: the first pop is the right-hand side.\n",loadTests:async()=>(await e.A(2566)).default},"tidy-route":{meta:{id:"tidy-route",region:"R6",title:"Tidy Route",difficulty:"M",patterns:["stack"],signals:["a path where one token undoes the previous one","split on a separator and process tokens in order","undo the most recent name"],prerequisites:["crate-brackets"],parSeconds:600,complexity:{time:"O(n)",space:"O(n)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.25,perf:.35},similar:[{name:"Simplify Path",lcNumber:71}],spec:{kind:"function",name:"tidyRoute",returns:"string",params:[{type:"string",name:"route"}]}},statement:'# Tidy Route\n\nStackspire\'s lifts are controlled by routes written like file paths. A `route` always starts with `/` and is made of **names** separated by slashes. Names are made of lowercase letters and dots.\n\n- A name `.` means "stay here" and does nothing.\n- A name `..` means "go up one level" (undo the most recent name). Going up from the top level stays at the top level.\n- Several slashes in a row count as one. Any other name, including `...` or `.a`, is an ordinary name.\n\nReturn the **tidy** form of the route: it starts with a single `/`, names are separated by a single `/`, it has no `.` or `..` names, and it does not end with `/` unless it is just the top level `/`.\n\n## Examples\n\n- `route = "/a/./b/../c/"` gives `"/a/c"`.\n- `route = "/../.."` gives `"/"`: you cannot go above the top.\n- `route = "//x///y"` gives `"/x/y"`.\n- `route = "/a/.../b/.."` gives `"/a/..."`: `...` is a normal name.\n\n## Constraints\n\n- `1 <= route.length() <= 100000`\n- `route` starts with `/` and contains only lowercase letters, `.` and `/`.\n',editorial:'## Signals\nA token that undoes the previous token (`..` after a name) and a separator that needs splitting: tokens processed in order with "undo the most recent" is a stack.\n\n## Brute force\nTokenise, drop empty names and `.`, then repeatedly find the first `..` and erase it together with the name before it (or just itself at the top level). Correct, but each erase shifts the vector and each search rescans from the start: with 25000 names followed by 25000 `..` that is O(n²) token moves and comparisons.\n\n## Key insight\nBecause tokens are handled left to right, when a `..` appears everything before it has already been tidied. So it only has to cancel the last kept name: the top of a stack.\n\n## Optimal\nScan characters, building the current name until a `/` (a sentinel `/` appended at the end flushes the last name). Empty or `.`: skip. `..`: pop if the stack is not empty. Anything else: push. Rebuild the answer as `/name` for each stack entry, or `/` if empty. Each character is read once and each name is pushed and popped at most once: O(n) time, O(n) space.\n\n## C++ walkthrough\n`vector<string>` as the stack, a `string name` accumulator, no `stringstream` needed. Compare with `==` against `".."` and `"."` exactly: a name like `...` or `.a` is ordinary. Build the result with `+=` in one pass rather than `result = "/" + name + result`, which would copy the string repeatedly. Return `"/"` explicitly when the stack is empty.\n\n## Common bugs\nPopping from an empty stack (undefined behaviour); keeping `..` as a name at the top level; treating `...` as special; returning `""` for the top level; leaving a trailing slash; not collapsing repeated slashes (empty names pushed).\n\n## Follow-ups\nResolve a *relative* route against a current directory (the stack starts non-empty and `..` at the top is kept). Handle symbolic links with a map and a depth limit to detect loops. Do it in place on the string with two pointers.\n\n## Similar problems\nSimplify Path (LeetCode 71) is this problem. Crate Brackets is the same "most recent first" stack skeleton.\n',reference:'class Solution {\npublic:\n    string tidyRoute(string route) {\n        vector<string> names;  // the names currently "open", from the top level down\n        string name;\n        route.push_back(\'/\');  // sentinel so the last name is flushed like any other\n        for (const char ch : route) {\n            if (ch != \'/\') {\n                name += ch;\n                continue;\n            }\n            if (name == "..") {\n                if (!names.empty()) names.pop_back();  // at the top level, ".." does nothing\n            } else if (!name.empty() && name != ".") {\n                names.push_back(name);\n            }\n            name.clear();\n        }\n        string tidy;\n        for (const auto& n : names) {\n            tidy += \'/\';\n            tidy += n;\n        }\n        return tidy.empty() ? "/" : tidy;\n    }\n};\n',hints:"## Nudge\nSplit the route into names. Which names undo something, and what exactly do they undo?\n\n## Approach\nWalk the route, collecting one name at a time between slashes. Ignore empty names and `.`. A `..` removes the most recent kept name, if there is one. Any other name (including `...`) is pushed. At the end join the kept names with `/` in front of each; if none are left the answer is `/`.\n\n## Key insight\n`..` always cancels the most recently kept name, which is a stack pop; at the top level the stack is empty and `..` is simply ignored. Only the exact strings `.` and `..` are special.\n",loadTests:async()=>(await e.A(68622)).default},"twin-stack-line":{meta:g,statement:"# Twin Stack Line\n\nA ticket booth has only two stacks to work with, yet customers must be served **first come, first served**. Build a queue out of two stacks.\n\nDesign `TwinStackLine` with these operations, each in **amortised O(1)** time (a single call may be slower, but any run of `m` calls must cost O(m) in total):\n\n- `void enqueue(int val)`: a customer joins the back of the line.\n- `int dequeue()`: remove the customer at the front and return their number.\n- `int front()`: return the number at the front without removing it.\n- `bool empty()`: return `true` if nobody is waiting.\n\n`dequeue` and `front` are only called when the line is not empty. Use two `stack` or `vector` containers as the only storage; do not use `queue` or `deque`.\n\n## Example\n\n```\nenqueue(1)\nenqueue(2)\nfront()   -> 1\ndequeue() -> 1\nenqueue(3)\ndequeue() -> 2\ndequeue() -> 3\nempty()   -> true\n```\n\n## Constraints\n\n- Up to `200000` operations in total.\n- `-1000000000 <= val <= 1000000000`.\n",editorial:'## Signals\n"Make a queue (FIFO) from stacks (LIFO)" works because reversing twice restores the original order. Two reversals, one per stack, hand customers to the front in arrival order.\n\n## Brute force\nHold everything in one vector and erase from the front on `dequeue`. Each dequeue shifts the rest: O(n) time per call, so 100000 enqueues followed by 100000 dequeues cost billions of moves.\n\n## Key insight\nPouring stack A into stack B reverses it. A customer who has been poured once is in serving order, and is never poured again. If you only pour when B is empty, every customer is moved at most once, so any `m` operations do O(m) total work even though a single `dequeue` can cost O(n).\n\n## Optimal\n`inbox` takes every `enqueue`. `dequeue` and `front` first call `refill()`, which does nothing if `outbox` has customers, otherwise moves all of `inbox` over. Then read or pop `outbox.back()`. `empty()` is true only if both stacks are empty. Time O(1) amortised per operation (each customer moves at most once); space O(n).\n\n## C++ walkthrough\n`vector<int>` with `push_back`, `back` and `pop_back` is a stack. `front()` is not `const` here because it may refill; `empty()` stays `const`. The guard `if (!outbox_.empty()) return;` is the whole correctness argument, so keep it first and comment it.\n\n## Common bugs\nRefilling while the outbox is non-empty (wrong order); `empty()` that only checks one stack; refilling inside `enqueue` (O(n) every time); forgetting that `front()` also needs the refill.\n\n## Follow-ups\nBuild a stack from two queues. Build a queue from **one** stack using recursion (the call stack is the second stack). Give worst-case O(1) operations with incremental transfer (a de-amortised queue). Combine with Gauge Stack to get a queue that reports its minimum.\n\n## Similar problems\nImplement Queue using Stacks (LeetCode 232) is this problem. Implement Stack using Queues (LeetCode 225) is the mirror image.\n',reference:"class TwinStackLine {\npublic:\n    TwinStackLine() = default;\n\n    void enqueue(int val) { inbox_.push_back(val); }\n\n    int dequeue() {\n        refill();\n        const int val = outbox_.back();\n        outbox_.pop_back();\n        return val;\n    }\n\n    int front() {\n        refill();\n        return outbox_.back();\n    }\n\n    bool empty() const { return inbox_.empty() && outbox_.empty(); }\n\nprivate:\n    // Only move when the outbox is empty: the outbox then holds the oldest customers in serving order.\n    void refill() {\n        if (!outbox_.empty()) return;\n        while (!inbox_.empty()) {\n            outbox_.push_back(inbox_.back());\n            inbox_.pop_back();\n        }\n    }\n\n    vector<int> inbox_;   // newest on top\n    vector<int> outbox_;  // oldest on top\n};\n",hints:"## Nudge\nA stack reverses the order of what you pour into it. What happens to the order if you pour the contents of one stack into a second stack?\n\n## Approach\nKeep an `inbox` for new customers and an `outbox` for serving. `enqueue` pushes onto the inbox. When you need the front and the outbox is empty, pour the whole inbox into the outbox (this reverses it, so the oldest ends on top). Serve from the outbox top.\n\n## Key insight\nOnly pour when the outbox is **empty**. Pouring while it still holds customers would put newer people ahead of older ones. Each customer is moved at most once, so the pours cost O(1) amortised per operation.\n",loadTests:async()=>(await e.A(41556)).default},"unroll-banner":{meta:{id:"unroll-banner",region:"R6",title:"Unroll Banner",difficulty:"M",patterns:["stack"],signals:["nested brackets with a repeat count in front","the innermost group resolves first","remember where each open group starts"],prerequisites:["crate-brackets"],parSeconds:900,complexity:{time:"O(n + L)",space:"O(n + L)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.25,perf:.35},similar:[{name:"Decode String",lcNumber:394}],spec:{kind:"function",name:"unroll",returns:"string",params:[{type:"string",name:"banner"}]}},statement:'# Unroll Banner\n\nStackspire\'s banner-makers shorten long banners with a repeat code: `k[text]` stands for `text` written `k` times in a row. The text inside the brackets may itself contain repeat codes, nested to any depth. Letters outside any code are written once.\n\nGiven the shortened `banner`, return the full banner.\n\n## Examples\n\n- `banner = "2[ab]c"` gives `"ababc"`.\n- `banner = "3[x2[y]]"` gives `"xyyxyyxyy"`: the inner code expands first.\n- `banner = "ab12[z]"` gives `"abzzzzzzzzzzzz"`: counts can have several digits.\n- `banner = "2[]x"` gives `"x"`: an empty text repeats into nothing.\n\n## Constraints\n\n- `0 <= banner.length() <= 100000`\n- `banner` contains lowercase letters, digits, `[` and `]`. Every `[` has exactly one digit string directly before it (a count from `1` to `300`, no leading zeros) and exactly one matching `]`.\n- Digits never appear except as a count in front of `[`.\n- The full banner has at most `100000` characters.\n',editorial:'## Signals\nBrackets nested to any depth, with a repeat count in front. The innermost group resolves first, and while you are inside it you must remember the outer text and count: that is a stack of frames.\n\n## Brute force\nFind the first `]`, walk back to its `[` (this is always an innermost group), read the count before it, replace the whole `k[body]` with `body` repeated `k` times, and rescan from the start. Correct, but every replacement rebuilds the whole string: with 25000 tiny groups that is 25000 rebuilds of a string tens of thousands of characters long, O(groups · length), quadratic in the worst case.\n\n## Key insight\nProcess the banner once, left to right, writing into a single output string. An open bracket only needs to remember where its body starts in the output and its repeat count. When the bracket closes, the body is the tail of the output from that start, and it already appears once, so append `count - 1` more copies.\n\n## Optimal\nState: `out`, `count` (digits seen since the last bracket) and a stack of `(start, count)`. Digit: `count = count * 10 + d`. `[`: push `(out.size(), count)` and reset `count`. `]`: pop `(start, times)`, copy `body = out.substr(start)`, append it `times - 1` times (or cut `out` back to `start` if `times` is 0). Letter: append. Every character written is part of the final banner at least once more often than it was written, so the total work is O(n + L) time and O(n + L) space, where n is the input length and L the output length.\n\n## C++ walkthrough\n`vector<pair<size_t, int>>` is the stack; storing an index instead of a saved string means entering a bracket copies nothing, and a group with count 1 costs only the body copy. Convert digits with `isdigit` on an `unsigned char` and accumulate in an `int` (counts are at most 300). Reset `count` after `[`, otherwise the next group inherits it. Take `body` as a copy before appending (and only when the count is above 1, so a count of 1 costs nothing): appending a string to itself is a bug waiting to happen.\n\n## Common bugs\nReading only one digit of the count; not saving the outer text (the result loses everything before the first bracket); repeating the text before the bracket together with the body; forgetting to reset the count; using recursion without care for 50000-deep nesting (stack overflow), which is a good reason to prefer the explicit stack.\n\n## Follow-ups\nDo it with recursive descent and discuss the depth limit. Return the length of the unrolled banner without building it (then the stack holds lengths and a count, and the limit on output length no longer matters, but use `long long`). Support a letter with no count meaning once, as it does here, plus uppercase letters.\n\n## Similar problems\nDecode String (LeetCode 394) is this problem. Crate Brackets (balanced brackets) is the matching skeleton; Tape Calculator is the same "save state when you dive in" idea for expressions.\n',reference:"class Solution {\npublic:\n    string unroll(string banner) {\n        string out;  // the banner built so far; an open bracket remembers where its body starts\n        vector<pair<size_t, int>> open;  // (start of the body in out, repeat count)\n        int count = 0;\n        for (const char ch : banner) {\n            if (isdigit(static_cast<unsigned char>(ch))) {\n                count = count * 10 + (ch - '0');\n            } else if (ch == '[') {\n                open.emplace_back(out.size(), count);\n                count = 0;\n            } else if (ch == ']') {\n                const auto [start, times] = open.back();\n                open.pop_back();\n                if (times == 0) {\n                    out.resize(start);\n                } else if (times > 1) {\n                    const string body = out.substr(start);  // copy first: appending a string to itself is a trap\n                    for (int i = 1; i < times; ++i) out += body;  // the body is already there once\n                }\n            } else {\n                out += ch;\n            }\n        }\n        return out;\n    }\n};\n",hints:"## Nudge\nWhich group do you finish first: the outermost one or the innermost one? What do you need to remember about each open group while you work inside it?\n\n## Approach\nWalk the characters. Build the count digit by digit (counts can have several digits). Keep one output string. On `[`, remember where the group's body starts in the output, and its count, on a stack. On `]`, the body is everything written since that start: append it `count - 1` more times. Letters just append.\n\n## Key insight\nThe stack holds one entry per currently open bracket. Closing a bracket repeats a tail of the output, and tails of tails compose correctly because inner groups are finished before outer ones. No character of the input is revisited, so the work is proportional to the output size.\n",loadTests:async()=>(await e.A(24515)).default},"valley-tally":{meta:{id:"valley-tally",region:"R6",title:"Valley Tally",difficulty:"M",patterns:["monotonic-stack"],signals:["sum over all subarrays of their minimum","count how many windows an element is the smallest of","previous smaller and next smaller"],prerequisites:["heat-wave"],parSeconds:1080,complexity:{time:"O(n)",space:"O(n)"},timeLimitMs:1e3,testWeights:{basic:.2,edge:.2,adversarial:.25,perf:.35},similar:[{name:"Sum of Subarray Minimums",lcNumber:907}],spec:{kind:"function",name:"valleyTally",returns:"int",params:[{type:"vector<int>&",name:"depths"}]}},statement:"# Valley Tally\n\nA surveyor walked a trail and wrote down the `depths` of the ground at each step. For every **contiguous stretch** of the trail (one or more steps in a row), she noted its **lowest** depth. Her assistant must add up those lowest depths over *every* stretch.\n\nReturn the total modulo `1000000007`.\n\n## Examples\n\n- `depths = [3, 1, 2, 4]` gives `17`. The ten stretches have lows `3, 1, 2, 4, 1, 1, 2, 1, 1, 1`.\n- `depths = [5]` gives `5`.\n- `depths = [2, 2]` gives `6`: the stretches `[2]`, `[2]` and `[2, 2]` each have low `2`.\n- `depths = []` gives `0`.\n\n## Constraints\n\n- `0 <= depths.size() <= 100000`\n- `1 <= depths[i] <= 1000000000`\n- Stretches are counted by position, so equal stretches at different places count separately.\n",editorial:'## Signals\n"Sum (or count) a per-subarray quantity such as min or max over all subarrays." Flip the loop: for each element, count the subarrays where it is the extreme. The boundaries come from previous-smaller and next-smaller, which is a monotonic stack question.\n\n## Brute force\nFix the left end, walk the right end and keep a running minimum, adding it to the total. That is O(n^2): for n = 100000 about 5 * 10^9 steps, too slow. Recomputing each minimum with a scan is O(n^3).\n\n## Key insight\nEvery stretch has exactly one **owner**: its minimum, with ties broken toward one side. Let `left[i]` be the distance back to the previous depth that is strictly smaller than `depths[i]`, and `right[i]` the distance forward to the next depth that is smaller than or equal to it. The stretches owned by `i` start in any of the `left[i]` positions to the left (including `i`) and end in any of the `right[i]` positions to the right (including `i`), so there are `left[i] * right[i]` of them. The answer is the sum of `depths[i] * left[i] * right[i]`.\n\nThe asymmetric comparison (strict on one side, non-strict on the other) is what makes the ownership unique. With `[2, 2]`, step 0 owns `[2]` and nothing else to its right, while step 1 owns `[2]` and `[2, 2]`.\n\n## Optimal\nUse one stack of indices with strictly increasing depths. Scan `i` from 0 to n, treating the position `n` as a sentinel smaller than everything. While the stack top has depth `>= depths[i]`, pop it as `mid`: its next smaller-or-equal is `i`, and its previous strictly smaller is the new top (or -1). Add `depths[mid] * (mid - prevSmaller) * (i - mid)`. Then push `i`. Each index is pushed and popped once: O(n) time, O(n) space. This single-pass form computes both boundaries without two arrays.\n\n## C++ walkthrough\nUse `long long` for `(mid - prev) * (i - mid)`, which reaches 2.5 * 10^9 and overflows `int`, then reduce modulo `1e9 + 7` before multiplying by the depth, so the product stays below 10^18. Accumulate in a `long long` and reduce every iteration. Loop `i` up to and including `n` and read the depth as `0` at `n` to flush the stack (all real depths are at least 1).\n\n## Common bugs\nUsing `>` and `>=` the same way on both sides, which double counts equal depths; storing the product in an `int`; forgetting the modulus or applying it only at the very end; forgetting to flush the stack after the loop; counting the stretch lengths off by one (`left` and `right` include the element itself).\n\n## Follow-ups\nSum of subarray *maximums*; sum of subarray ranges (max minus min), solved as two such sums; count subarrays where the minimum is at least `k` (a different, window-based question).\n\n## Similar problems\nSum of Subarray Minimums (LeetCode 907) is this problem. Daily Temperatures (LeetCode 739) uses the same stack with a simpler answer, and Largest Rectangle in Histogram (LeetCode 84) uses the same boundaries for area.\n',reference:"class Solution {\npublic:\n    int valleyTally(vector<int>& depths) {\n        constexpr long long MOD = 1'000'000'007;\n        const int n = static_cast<int>(depths.size());\n        long long total = 0;\n        vector<int> stack;  // indices; depths strictly increase from bottom to top\n        for (int i = 0; i <= n; ++i) {\n            const int now = i == n ? 0 : depths[i];  // sentinel 0 flushes the stack\n            while (!stack.empty() && depths[stack.back()] >= now) {\n                const int mid = stack.back();\n                stack.pop_back();\n                const int prev = stack.empty() ? -1 : stack.back();  // previous strictly smaller\n                // mid owns the stretches that start in (prev, mid] and end in [mid, i): i is the next smaller-or-equal.\n                const long long stretches = static_cast<long long>(mid - prev) * (i - mid) % MOD;\n                total = (total + stretches * depths[mid]) % MOD;\n            }\n            stack.push_back(i);\n        }\n        return static_cast<int>(total);\n    }\n};\n",hints:'## Nudge\nThere are about n^2/2 stretches, far too many to list. Instead of asking "what is the low of each stretch?", ask "for this one step, in how many stretches is it the low?"\n\n## Approach\nFor each position `i`, find how far you can extend left before meeting a smaller depth, and how far right before meeting a smaller (or equal) depth. If there are `L` choices for the left end and `R` choices for the right end, step `i` is the low of `L * R` stretches and contributes `depths[i] * L * R`. A monotonic stack finds both boundaries for every position in one pass.\n\n## Key insight\nTies need a rule, or equal depths are counted twice. Use "strictly smaller on the left, smaller-or-equal on the right": then the **rightmost** lowest step of a stretch owns it, and every stretch has exactly one owner. Reduce modulo after multiplying `L * R`, because `L * R * depth` can pass 10^18 only if you skip that reduction.\n',loadTests:async()=>(await e.A(68489)).default}};e.s(["f",0,f],92604)}]);